__d(function(t,c,s,e,r,q,a){r.exports={id:"u04",title:"\u0646\u0648\u0627\u0642\u0636 \u0627\u0644\u062a\u064a\u0645\u0645 \u0648\u0627\u0644\u0645\u0633\u062d \u0639\u0644\u0649 \u0627\u0644\u062e\u0641\u064a\u0646 \u0648\u0627\u0644\u062d\u064a\u0636 \u0648\u0627\u0644\u0646\u0641\u0627\u0633",subtitle:"\u0631\u064f\u062e\u064e\u0635\u064f \u0627\u0644\u0637\u064e\u0651\u0647\u0627\u0631\u0629\u0650 \u0648\u0623\u062d\u0643\u0627\u0645\u064f \u0627\u0644\u0646\u0650\u0651\u0633\u0627\u0621\u0650",color:"purple",section:"s4",source:{book:"\u0645\u0646\u0647\u0627\u062c \u0627\u0644\u0645\u0633\u0644\u0645",pages:[160,165]},lessons:[{id:"u04l1",title:"\u0646\u0648\u0627\u0642\u0636\u064f \u0627\u0644\u062a\u064a\u0645\u064f\u0651\u0645\u0650 \u0648\u0643\u064a\u0641\u064a\u064e\u0651\u062a\u064f\u0647\u064f",items:[{t:"info",h:"\u0645\u0627 \u064a\u0646\u0642\u0636\u064f \u0627\u0644\u062a\u064a\u0645\u064f\u0651\u0645\u064e",b:"\u064a\u0646\u0642\u0636\u064f \u0627\u0644\u062a\u064a\u0645\u064f\u0651\u0645\u064e \u0634\u064a\u0626\u0627\u0646\u0650: \u0643\u0644\u064f\u0651 \u0645\u0627 \u064a\u0646\u0642\u0636\u064f \u0627\u0644\u0648\u0636\u0648\u0621\u064e\u061b \u0625\u0630\u0652 \u0647\u0648\u064e \u0628\u062f\u0644\u064c \u0639\u0646\u0647\u064f\u060c \u0648\u0648\u062c\u0648\u062f\u064f \u0627\u0644\u0645\u0627\u0621\u0650 \u0644\u0645\u0646\u0652 \u0639\u062f\u0650\u0645\u064e\u0647\u064f \u0642\u0628\u0644\u064e \u0623\u0646\u0652 \u064a\u062f\u062e\u0644\u064e \u0641\u064a \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650 \u0623\u0648\u0652 \u0623\u062b\u0646\u0627\u0621\u064e\u0647\u0627.",src:160},{t:"info",h:"\u0645\u0627 \u064a\u064f\u0628\u0627\u062d\u064f \u0628\u0627\u0644\u062a\u064a\u0645\u064f\u0651\u0645\u0650",b:"\u0645\u0646\u0652 \u062a\u064a\u0645\u064e\u0651\u0645\u064e \u062d\u0644\u064e\u0651 \u0644\u0647\u064f \u0645\u0627 \u0643\u0627\u0646\u064e \u0645\u062d\u0638\u0648\u0631\u064b\u0627 \u0639\u0644\u064a\u0647\u0650 \u0642\u0628\u0644\u064e \u062a\u064a\u0645\u064f\u0651\u0645\u0650\u0647\u0650\u061b \u0641\u064a\u064f\u0635\u0644\u0650\u0651\u064a \u0648\u064a\u0637\u0648\u0641\u064f\u060c \u0648\u064a\u0645\u0633\u064f\u0651 \u0627\u0644\u0645\u0635\u062d\u0641\u064e \u0648\u064a\u0642\u0631\u0623\u064f \u0627\u0644\u0642\u0631\u0622\u0646\u064e\u060c \u0648\u064a\u0645\u0643\u062b\u064f \u0641\u064a \u0627\u0644\u0645\u0633\u062c\u062f\u0650.",src:160},{t:"mcq",q:"\u0643\u0645\u0652 \u0639\u062f\u062f\u064f \u0646\u0648\u0627\u0642\u0636\u0650 \u0627\u0644\u062a\u064a\u0645\u064f\u0651\u0645\u0650 \u0639\u0646\u062f\u064e \u0627\u0644\u0645\u0624\u0644\u0650\u0651\u0641\u0650\u061f",o:["\u0648\u0627\u062d\u062f\u064c","\u0634\u064a\u0626\u0627\u0646\u0650","\u062b\u0644\u0627\u062b\u0629\u064c","\u0623\u0631\u0628\u0639\u0629\u064c"],a:1,e:"\u0646\u0635\u064e\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u064f: \u064a\u0646\u0642\u0636\u064f \u0627\u0644\u062a\u064a\u0645\u064f\u0651\u0645\u064e \u0634\u064a\u0626\u0627\u0646\u0650: \u0643\u0644\u064f\u0651 \u0645\u0627 \u064a\u0646\u0642\u0636\u064f \u0627\u0644\u0648\u0636\u0648\u0621\u064e\u060c \u0648\u0648\u062c\u0648\u062f\u064f \u0627\u0644\u0645\u0627\u0621\u0650 \u0644\u0645\u0646\u0652 \u0639\u062f\u0650\u0645\u064e\u0647\u064f.",src:160},{t:"tf",q:"\u0645\u0646\u0652 \u062a\u064a\u0645\u064e\u0651\u0645\u064e \u0648\u0635\u0644\u064e\u0651\u0649 \u062b\u0645\u064e\u0651 \u0648\u062c\u062f\u064e \u0627\u0644\u0645\u0627\u0621\u064e \u0628\u0639\u062f\u064e \u0641\u0631\u0627\u063a\u0650\u0647\u0650 \u0645\u0646\u064e \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650 \u0644\u0632\u0650\u0645\u064e\u062a\u0652\u0647\u064f \u0627\u0644\u0625\u0639\u0627\u062f\u0629\u064f.",a:!1,e:"\u0628\u0644\u0652 \u0635\u062d\u064e\u0651\u062a\u0652 \u0635\u0644\u0627\u062a\u064f\u0647\u064f \u0648\u0644\u0627 \u0625\u0639\u0627\u062f\u0629\u064e \u0639\u0644\u064a\u0647\u0650\u061b \u0644\u0642\u0648\u0644\u0650\u0647\u0650 \ufdfa: \xab\u0644\u0627 \u062a\u064f\u0635\u0644\u064f\u0651\u0648\u0627 \u0635\u0644\u0627\u0629\u064b \u0641\u064a \u064a\u0648\u0645\u064d \u0645\u0631\u064e\u0651\u062a\u064a\u0646\u0650\xbb.",src:160},{t:"tf",q:"\u0648\u062c\u0648\u062f\u064f \u0627\u0644\u0645\u0627\u0621\u0650 \u0623\u062b\u0646\u0627\u0621\u064e \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650 \u0644\u0645\u0646\u0652 \u0643\u0627\u0646\u064e \u0639\u0627\u062f\u0645\u064b\u0627 \u0644\u0647\u064f \u064a\u0646\u0642\u0636\u064f \u062a\u064a\u0645\u064f\u0651\u0645\u064e\u0647\u064f.",a:!0,e:"\u0627\u0644\u0646\u064e\u0651\u0627\u0642\u0636\u064f \u0627\u0644\u062b\u064e\u0651\u0627\u0646\u064a \u0639\u0646\u062f\u064e \u0627\u0644\u0645\u0624\u0644\u0650\u0651\u0641\u0650: \u0648\u062c\u0648\u062f\u064f \u0627\u0644\u0645\u0627\u0621\u0650 \u0644\u0645\u0646\u0652 \u0639\u062f\u0650\u0645\u064e\u0647\u064f \u0642\u0628\u0644\u064e \u0623\u0646\u0652 \u064a\u062f\u062e\u0644\u064e \u0641\u064a \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650 \u0623\u0648\u0652 \u0623\u062b\u0646\u0627\u0621\u064e\u0647\u0627.",src:160},{t:"order",q:"\u0631\u062a\u0650\u0651\u0628\u0652 \u0643\u064a\u0641\u064a\u064e\u0651\u0629\u064e \u0627\u0644\u062a\u064a\u0645\u064f\u0651\u0645\u0650 \u0643\u0645\u0627 \u0630\u0643\u0631\u064e\u0647\u0627 \u0627\u0644\u0643\u062a\u0627\u0628\u064f",items:["\u064a\u0642\u0648\u0644\u064f: \u0628\u0633\u0645\u0650 \u0627\u0644\u0644\u0647\u0650\u060c \u0646\u0627\u0648\u064a\u064b\u0627 \u0627\u0633\u062a\u0628\u0627\u062d\u0629\u064e \u0645\u0627 \u064a\u062a\u064a\u0645\u064e\u0651\u0645\u064f \u0644\u0647\u064f","\u064a\u0636\u0631\u0628\u064f \u0628\u0643\u0641\u064e\u0651\u064a\u0647\u0650 \u0648\u062c\u0647\u064e \u0627\u0644\u0623\u0631\u0636\u0650","\u064a\u0646\u0641\u0636\u064f \u0627\u0644\u063a\u0628\u0627\u0631\u064e \u0645\u0646\u0652 \u0643\u0641\u064e\u0651\u064a\u0647\u0650 \u0646\u0641\u0636\u064b\u0627 \u062e\u0641\u064a\u0641\u064b\u0627","\u064a\u0645\u0633\u062d\u064f \u0648\u062c\u0647\u064e\u0647\u064f \u0645\u0633\u062d\u0629\u064b \u0648\u0627\u062d\u062f\u0629\u064b","\u064a\u0645\u0633\u062d\u064f \u0643\u0641\u064e\u0651\u064a\u0647\u0650\u060c \u0648\u0625\u0646\u0652 \u0634\u0627\u0621\u064e \u0645\u0639\u064e \u0630\u0631\u0627\u0639\u064a\u0647\u0650 \u0625\u0644\u0649 \u0627\u0644\u0645\u0631\u0641\u0642\u064a\u0646\u0650"],e:"\u0646\u0641\u0636\u064f \u0627\u0644\u063a\u0628\u0627\u0631\u0650 \u0644\u0627 \u0628\u0623\u0633\u064e \u0628\u0647\u0650\u060c \u0648\u0627\u0644\u0636\u064e\u0651\u0631\u0628\u0629\u064f \u0627\u0644\u062b\u064e\u0651\u0627\u0646\u064a\u0629\u064f \u0644\u0644\u0643\u0641\u064e\u0651\u064a\u0646\u0650 \u0648\u0627\u0644\u0630\u0650\u0651\u0631\u0627\u0639\u064a\u0646\u0650 \u0639\u0644\u0649 \u0627\u0644\u062a\u064e\u0651\u062e\u064a\u064a\u0631\u0650\u060c \u0648\u0625\u0646\u0650 \u0627\u0642\u062a\u0635\u0631\u064e \u0639\u0644\u0649 \u0627\u0644\u0643\u0641\u064e\u0651\u064a\u0646\u0650 \u0623\u062c\u0632\u0623\u064e\u0647\u064f.",src:160},{t:"fill",q:"\u064a\u0636\u0631\u0628\u064f \u0627\u0644\u0645\u062a\u064a\u0645\u0650\u0651\u0645\u064f \u0628\u0643\u0641\u064e\u0651\u064a\u0647\u0650 \u0648\u062c\u0647\u064e \u0627\u0644\u0623\u0631\u0636\u0650 \u0645\u0646\u0652 \u062a\u0631\u0627\u0628\u064d\u060c \u0623\u0648\u0652 \u0631\u0645\u0644\u064d\u060c \u0623\u0648\u0652 \u062d\u062c\u0627\u0631\u0629\u064d\u060c \u0623\u0648\u0652 ____ \u0648\u0646\u062d\u0648\u0650\u0647\u0627.",bank:["\u0633\u064e\u0628\u064e\u062e\u064e\u0629\u064d","\u062e\u0634\u0628\u064d","\u062d\u062f\u064a\u062f\u064d"],a:"\u0633\u064e\u0628\u064e\u062e\u064e\u0629\u064d",e:"\u0639\u062f\u064e\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0645\u0627 \u064a\u064f\u062a\u064a\u0645\u064e\u0651\u0645\u064f \u0639\u0644\u064a\u0647\u0650: \u0627\u0644\u062a\u064f\u0651\u0631\u0627\u0628\u064e \u0648\u0627\u0644\u0631\u064e\u0651\u0645\u0644\u064e \u0648\u0627\u0644\u062d\u062c\u0627\u0631\u0629\u064e \u0648\u0627\u0644\u0633\u064e\u0651\u0628\u064e\u062e\u064e\u0629\u064e \u0648\u0646\u062d\u0648\u064e\u0647\u0627.",src:160},{t:"mcq",q:"\u0647\u0644\u0652 \u064a\u064f\u0635\u0644\u0650\u0651\u064a \u0628\u0627\u0644\u062a\u064a\u0645\u064f\u0651\u0645\u0650 \u0627\u0644\u0648\u0627\u062d\u062f\u0650 \u0639\u062f\u064e\u0651\u0629\u064e \u0635\u0644\u0648\u0627\u062a\u064d \u0625\u0630\u0627 \u0644\u0645\u0652 \u064a\u0646\u062a\u0642\u0636\u0652 \u062a\u064a\u0645\u064f\u0651\u0645\u064f\u0647\u064f\u061f",o:["\u0646\u0639\u0645\u0652 \u0642\u0637\u0639\u064b\u0627\u060c \u0648\u0644\u0627 \u062e\u0644\u0627\u0641\u064e \u0641\u064a \u0630\u0644\u0643\u064e","\u0644\u0627 \u064a\u062c\u0648\u0632\u064f \u0628\u0625\u062c\u0645\u0627\u0639\u0650 \u0623\u0647\u0644\u0650 \u0627\u0644\u0639\u0644\u0645\u0650","\u0641\u064a \u0627\u0644\u0645\u0633\u0623\u0644\u0629\u0650 \u062e\u0644\u0627\u0641\u064c\u060c \u0648\u0627\u0644\u0627\u062d\u062a\u064a\u0627\u0637\u064f \u064a\u0642\u0636\u064a \u0628\u0627\u0644\u062a\u064a\u0645\u064f\u0651\u0645\u0650 \u0644\u0643\u0644\u0650\u0651 \u0635\u0644\u0627\u0629\u064d","\u064a\u062a\u064a\u0645\u064e\u0651\u0645\u064f \u062b\u0645\u064e\u0651 \u064a\u064f\u0639\u064a\u062f\u064f \u0635\u0644\u0627\u062a\u064e\u0647\u064f \u0628\u0639\u062f\u064e \u0630\u0644\u0643\u064e"],a:2,e:"\u0627\u0644\u0645\u0633\u0623\u0644\u0629\u064f \u0627\u062c\u062a\u0647\u0627\u062f\u064a\u064e\u0651\u0629\u064c \u0627\u062e\u062a\u0644\u0641\u064e \u0641\u064a\u0647\u0627 \u0623\u0647\u0644\u064f \u0627\u0644\u0639\u0644\u0645\u0650\u061b \u0625\u0630\u0652 \u0644\u0645\u0652 \u064a\u0631\u062f\u0652 \u0646\u0635\u064c\u0651 \u0642\u0627\u0637\u0639\u064c \u064a\u062d\u0633\u0645\u064f\u0647\u0627\u060c \u0641\u0631\u062c\u064e\u0651\u062d\u064e \u0627\u0644\u0645\u0624\u0644\u0650\u0651\u0641\u064f \u0627\u0644\u0623\u062d\u0648\u0637\u064e: \u062a\u064a\u0645\u064f\u0651\u0645\u064c \u0645\u0633\u062a\u0642\u0644\u064c\u0651 \u0644\u0643\u0644\u0650\u0651 \u0635\u0644\u0627\u0629\u064d.",src:160},{t:"mcq",q:"\u0627\u0644\u0645\u0643\u062b\u064f \u0641\u064a \u0627\u0644\u0645\u0633\u062c\u062f\u0650 \u0644\u0645\u0646\u0652 \u062a\u064a\u0645\u064e\u0651\u0645\u064e:",o:["\u0644\u0627 \u064a\u0635\u062d\u064f\u0651 \u062d\u062a\u064e\u0651\u0649 \u064a\u062c\u062f\u064e \u0627\u0644\u0645\u0627\u0621\u064e","\u064a\u064f\u0643\u0631\u0647\u064f \u0645\u0639\u064e \u0635\u062d\u064e\u0651\u0629\u0650 \u062a\u064a\u0645\u064f\u0651\u0645\u0650\u0647\u0650","\u064a\u064f\u0628\u0627\u062d\u064f\u061b \u0644\u0623\u0646\u064e\u0651\u0647\u064f \u0645\u0645\u064e\u0651\u0627 \u0643\u0627\u0646\u064e \u0645\u0645\u0646\u0648\u0639\u064b\u0627 \u0642\u0628\u0644\u064e \u0627\u0644\u062a\u064a\u0645\u064f\u0651\u0645\u0650"],a:2,e:"\u064a\u064f\u0628\u0627\u062d\u064f \u0628\u0627\u0644\u062a\u064a\u0645\u064f\u0651\u0645\u0650 \u0643\u0644\u064f\u0651 \u0645\u0627 \u0643\u0627\u0646\u064e \u0645\u0645\u0646\u0648\u0639\u064b\u0627 \u0642\u0628\u0644\u064e\u0647\u064f \u0645\u0646\u0652 \u0635\u0644\u0627\u0629\u064d\u060c \u0648\u0637\u0648\u0627\u0641\u064d\u060c \u0648\u0645\u0633\u0650\u0651 \u0645\u0635\u062d\u0641\u064d\u060c \u0648\u0642\u0631\u0627\u0621\u0629\u0650 \u0642\u0631\u0622\u0646\u064d\u060c \u0648\u0645\u0643\u062b\u064d \u0641\u064a \u0645\u0633\u062c\u062f\u064d.",src:160}]},{id:"u04l2",title:"\u0645\u0634\u0631\u0648\u0639\u064a\u064e\u0651\u0629\u064f \u0627\u0644\u0645\u0633\u062d\u0650 \u0639\u0644\u0649 \u0627\u0644\u062e\u0641\u064e\u0651\u064a\u0646\u0650 \u0648\u0627\u0644\u062c\u0628\u0627\u0626\u0631\u0650",items:[{t:"info",h:"\u0645\u0627 \u064a\u0642\u0648\u0645\u064f \u0645\u0642\u0627\u0645\u064e \u0627\u0644\u062e\u0641\u064e\u0651\u064a\u0646\u0650",b:"\u0645\u0634\u0631\u0648\u0639\u064a\u064e\u0651\u0629\u064f \u0627\u0644\u0645\u0633\u062d\u0650 \u062b\u0627\u0628\u062a\u0629\u064c \u0639\u0644\u0649 \u0627\u0644\u062e\u0641\u064e\u0651\u064a\u0646\u0650 \u0648\u0645\u0627 \u0641\u064a \u0645\u0639\u0646\u0627\u0647\u064f\u0645\u0627 \u0645\u0646\u064e \u0627\u0644\u062c\u064e\u0648\u0631\u0628\u064e\u064a\u0646\u0650 \u0648\u0627\u0644\u0645\u064f\u0648\u0642\u064e\u064a\u0646\u0650 \u0648\u0627\u0644\u062a\u064e\u0651\u0633\u0627\u062e\u064a\u0646\u0650\u060c \u0648\u0642\u062f\u0652 \u062b\u0628\u062a\u064e\u062a\u0652 \u0628\u0627\u0644\u0643\u062a\u0627\u0628\u0650 \u0648\u0627\u0644\u0633\u064f\u0651\u0646\u064e\u0651\u0629\u0650 \u0645\u0639\u064b\u0627.",src:160},{t:"info",h:"\u062f\u0644\u064a\u0644\u064f \u0627\u0644\u0645\u0633\u062d\u0650 \u0645\u0646\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u0650",b:"\u0642\u064f\u0631\u0650\u0626\u064e \u0642\u0648\u0644\u064f\u0647\u064f \u062a\u0639\u0627\u0644\u0649: {\u0648\u064e\u0623\u064e\u0631\u0652\u062c\u064f\u0644\u064e\u0643\u064f\u0645\u0652} \u0628\u0627\u0644\u062c\u0631\u0650\u0651 \u0639\u0637\u0641\u064b\u0627 \u0639\u0644\u0649 {\u0648\u064e\u0627\u0645\u0652\u0633\u064e\u062d\u064f\u0648\u0627 \u0628\u0650\u0631\u064f\u0621\u064f\u0648\u0633\u0650\u0643\u064f\u0645\u0652} [\u0627\u0644\u0645\u0627\u0626\u062f\u0629: \u0666]\u060c \u0641\u062f\u0644\u064e\u0651 \u0630\u0644\u0643\u064e \u0639\u0644\u0649 \u062c\u0648\u0627\u0632\u0650 \u0627\u0644\u0645\u0633\u062d\u0650.",src:161},{t:"mcq",q:"\u0628\u0623\u064a\u0650\u0651 \u0642\u0631\u0627\u0621\u0629\u064d \u0627\u0633\u062a\u062f\u0644\u064e\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0645\u0646\u064e \u0627\u0644\u0642\u0631\u0622\u0646\u0650 \u0639\u0644\u0649 \u062c\u0648\u0627\u0632\u0650 \u0627\u0644\u0645\u0633\u062d\u0650\u061f",o:["\u0642\u0631\u0627\u0621\u0629\u064f {\u0648\u064e\u0623\u064e\u0631\u0652\u062c\u064f\u0644\u064e\u0643\u064f\u0645\u0652} \u0628\u0627\u0644\u0646\u064e\u0651\u0635\u0628\u0650","\u0642\u0631\u0627\u0621\u0629\u064f {\u0648\u064e\u0623\u064e\u0631\u0652\u062c\u064f\u0644\u064e\u0643\u064f\u0645\u0652} \u0628\u0627\u0644\u062c\u0631\u0650\u0651 \u0639\u0637\u0641\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0631\u064f\u0651\u0624\u0648\u0633\u0650","\u0642\u0648\u0644\u064f\u0647\u064f \u062a\u0639\u0627\u0644\u0649: {\u0641\u064e\u0627\u063a\u0652\u0633\u0650\u0644\u064f\u0648\u0627 \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0643\u064f\u0645\u0652}","\u0644\u0645\u0652 \u064a\u0633\u062a\u062f\u0644\u064e\u0651 \u0645\u0646\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u0650 \u0628\u0634\u064a\u0621\u064d"],a:1,e:"\u0642\u064f\u0631\u0650\u0626\u064e\u062a\u0652 {\u0648\u064e\u0623\u064e\u0631\u0652\u062c\u064f\u0644\u064e\u0643\u064f\u0645\u0652} \u0628\u0627\u0644\u062c\u0631\u0650\u0651 \u0639\u0637\u0641\u064b\u0627 \u0639\u0644\u0649 {\u0648\u064e\u0627\u0645\u0652\u0633\u064e\u062d\u064f\u0648\u0627 \u0628\u0650\u0631\u064f\u0621\u064f\u0648\u0633\u0650\u0643\u064f\u0645\u0652} [\u0627\u0644\u0645\u0627\u0626\u062f\u0629: \u0666] \u0641\u062f\u0644\u064e\u0651 \u0647\u0630\u0627 \u0639\u0644\u0649 \u062c\u0648\u0627\u0632\u0650 \u0627\u0644\u0645\u0633\u062d\u0650.",src:161},{t:"tf",q:"\u062d\u062f\u064a\u062b\u064f: \xab\u0625\u0630\u0627 \u062a\u0648\u0636\u064e\u0651\u0623\u064e \u0623\u062d\u062f\u064f\u0643\u0645\u0652 \u0641\u0644\u0628\u0650\u0633\u064e \u062e\u0641\u064e\u0651\u064a\u0647\u0650 \u0641\u0644\u064a\u0645\u0633\u062d\u0652 \u0639\u0644\u064a\u0647\u0650\u0645\u0627 \u0648\u0644\u064a\u064f\u0635\u0644\u0650\u0651\xbb \u062c\u0627\u0621\u064e \u0645\u0637\u0644\u0642\u064b\u0627 \u0639\u0646\u0650 \u0627\u0644\u062a\u064e\u0651\u0648\u0642\u064a\u062a\u0650\u060c \u0648\u0642\u062f\u0652 \u0642\u064a\u064e\u0651\u062f\u064e\u0647\u064f \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0628\u062d\u062f\u064a\u062b\u0650 \u0627\u0644\u062a\u064e\u0651\u0648\u0642\u064a\u062a\u0650.",a:!0,e:"\u0642\u0627\u0644\u064e \u0627\u0644\u0645\u0624\u0644\u0650\u0651\u0641\u064f: \u0648\u0645\u0627 \u0641\u064a\u0647\u0650 \u0645\u0646\u0652 \u0625\u0637\u0644\u0627\u0642\u0650 \u0639\u062f\u0645\u0650 \u0627\u0644\u062a\u064e\u0651\u0648\u0642\u064a\u062a\u0650 \u0641\u0625\u0646\u064e\u0651\u0647\u064f \u0645\u0642\u064a\u064e\u0651\u062f\u064c \u0628\u062d\u062f\u064a\u062b\u0650 \u0627\u0644\u062a\u064e\u0651\u0648\u0642\u064a\u062a\u0650 \u0627\u0644\u0622\u062a\u064a.",src:161},{t:"mcq",q:"\u0641\u064a \u062d\u062f\u064a\u062b\u0650 \u0627\u0644\u0645\u0633\u062d\u0650 \u0639\u0644\u0649 \u0627\u0644\u062e\u0641\u064e\u0651\u064a\u0646\u0650\u060c \u0645\u0627 \u0627\u0644\u062d\u0627\u0644\u064f \u0627\u0644\u064e\u0651\u062a\u064a \u0627\u0633\u062a\u064f\u062b\u0646\u064a\u064e\u062a\u0652 \u0641\u064a\u0647\u0627 \u0645\u0646\u0652 \u062a\u0631\u0643\u0650 \u0627\u0644\u062e\u0644\u0639\u0650\u061f",o:["\u0627\u0644\u062c\u0646\u0627\u0628\u0629\u064f","\u0627\u0644\u0646\u064e\u0651\u0648\u0645\u064f","\u0627\u0644\u0633\u064e\u0651\u0641\u0631\u064f","\u062f\u062e\u0648\u0644\u064f \u0627\u0644\u0645\u0633\u062c\u062f\u0650"],a:0,e:"\u0644\u0641\u0638\u064f \u0627\u0644\u062d\u062f\u064a\u062b\u0650: \xab\u0648\u0644\u0627 \u064a\u062e\u0644\u0639\u0652\u0647\u064f\u0645\u0627 \u0625\u0646\u0652 \u0634\u0627\u0621\u064e \u0625\u0644\u064e\u0651\u0627 \u0645\u0646\u0652 \u062c\u0646\u0627\u0628\u0629\u064d\xbb.",src:161},{t:"mcq",q:"\u0628\u0645\u064e \u0627\u0633\u062a\u062f\u0644\u064e\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0639\u0644\u0649 \u0645\u0634\u0631\u0648\u0639\u064a\u064e\u0651\u0629\u0650 \u0627\u0644\u0645\u0633\u062d\u0650 \u0639\u0644\u0649 \u0627\u0644\u062c\u0628\u0627\u0626\u0631\u0650\u061f",o:["\u0628\u0622\u064a\u0629\u0650 \u0627\u0644\u0645\u0627\u0626\u062f\u0629\u0650","\u0628\u062d\u062f\u064a\u062b\u0650 \u0627\u0644\u0645\u064f\u063a\u064a\u0631\u0629\u0650 \u0628\u0646\u0650 \u0634\u0639\u0628\u0629\u064e","\u0628\u062d\u062f\u064a\u062b\u0650 \u0627\u0644\u064e\u0651\u0630\u064a \u0634\u064f\u062c\u064e\u0651 \u0631\u0623\u0633\u064f\u0647\u064f \u0641\u063a\u0633\u0644\u064e \u0631\u0623\u0633\u064e\u0647\u064f \u0641\u0645\u0627\u062a\u064e","\u0628\u0642\u0648\u0644\u0650 \u0639\u0644\u064a\u064d\u0651 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647\u064f"],a:2,e:"\u0642\u0627\u0644\u064e \u0641\u064a\u0647\u0650 \ufdfa: \xab\u0625\u0646\u064e\u0651\u0645\u0627 \u0643\u0627\u0646\u064e \u064a\u0643\u0641\u064a\u0647\u0650 \u0623\u0646\u0652 \u064a\u062a\u064a\u0645\u064e\u0651\u0645\u064e \u0648\u064a\u0639\u0635\u0650\u0628\u064e \u0639\u0644\u0649 \u062c\u0631\u062d\u0650\u0647\u0650 \u062e\u0650\u0631\u0642\u0629\u064b \u062b\u0645\u064e\u0651 \u064a\u0645\u0633\u062d\u064e \u0639\u0644\u064a\u0647\u0627 \u0648\u064a\u063a\u0633\u0644\u064e \u0633\u0627\u0626\u0631\u064e \u062c\u0633\u062f\u0650\u0647\u0650\xbb.",src:161},{t:"order",q:"\u0631\u062a\u0650\u0651\u0628\u0652 \u0645\u0627 \u0630\u0643\u0631\u064e \u0627\u0644\u062d\u062f\u064a\u062b\u064f \u0623\u0646\u064e\u0651\u0647\u064f \u0643\u0627\u0646\u064e \u064a\u0643\u0641\u064a \u0635\u0627\u062d\u0628\u064e \u0627\u0644\u0634\u064e\u0651\u062c\u064e\u0651\u0629\u0650",items:["\u0623\u0646\u0652 \u064a\u062a\u064a\u0645\u064e\u0651\u0645\u064e \u0648\u064a\u0639\u0635\u0650\u0628\u064e \u0639\u0644\u0649 \u062c\u0631\u062d\u0650\u0647\u0650 \u062e\u0650\u0631\u0642\u0629\u064b","\u0623\u0646\u0652 \u064a\u0645\u0633\u062d\u064e \u0639\u0644\u0649 \u0627\u0644\u062e\u0650\u0631\u0642\u0629\u0650","\u0623\u0646\u0652 \u064a\u063a\u0633\u0644\u064e \u0633\u0627\u0626\u0631\u064e \u062c\u0633\u062f\u0650\u0647\u0650"],e:"\u0639\u0637\u0641\u064e \u0627\u0644\u062d\u062f\u064a\u062b\u064f \u0627\u0644\u062a\u064a\u0645\u064f\u0651\u0645\u064e \u0648\u0627\u0644\u0639\u064e\u0635\u0652\u0628\u064e \u0628\u0627\u0644\u0648\u0627\u0648\u0650 \u0641\u062c\u0639\u0644\u064e\u0647\u064f\u0645\u0627 \u0645\u0639\u064b\u0627\u060c \u062b\u0645\u064e\u0651 \u0631\u062a\u064e\u0651\u0628\u064e \u0639\u0644\u064a\u0647\u0650\u0645\u0627 \u0627\u0644\u0645\u0633\u062d\u064e \u0628\u0640\xab\u062b\u0645\u064e\u0651\xbb\u061b \u0625\u0630\u0650 \u0627\u0644\u0636\u064e\u0651\u0645\u064a\u0631\u064f \u0641\u064a (\u0639\u0644\u064a\u0647\u0627) \u0639\u0627\u0626\u062f\u064c \u0639\u0644\u0649 \u0627\u0644\u062e\u0650\u0631\u0642\u0629\u0650\u060c \u0641\u0644\u0627 \u0645\u0633\u062d\u064e \u0642\u0628\u0644\u064e \u0627\u0644\u0639\u064e\u0635\u0652\u0628\u0650.",src:161},{t:"fill",q:"\u0627\u0644\u062c\u064e\u0648\u0631\u0628\u0627\u0646\u0650 \u0648\u0627\u0644\u0645\u064f\u0648\u0642\u0627\u0646\u0650 \u0648____ \u0645\u0645\u064e\u0651\u0627 \u0647\u0648\u064e \u0641\u064a \u0645\u0639\u0646\u0649 \u0627\u0644\u062e\u0641\u064e\u0651\u064a\u0646\u0650 \u0641\u064a \u062c\u0648\u0627\u0632\u0650 \u0627\u0644\u0645\u0633\u062d\u0650.",bank:["\u0627\u0644\u062a\u064e\u0651\u0633\u0627\u062e\u064a\u0646\u064f","\u0627\u0644\u062c\u0628\u0627\u0626\u0631\u064f","\u0627\u0644\u0639\u0645\u0627\u0626\u0645\u064f"],a:"\u0627\u0644\u062a\u064e\u0651\u0633\u0627\u062e\u064a\u0646\u064f",e:"\u0646\u0635\u064e\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u064f: \u0627\u0644\u0645\u0633\u062d\u064f \u0639\u0644\u0649 \u0627\u0644\u062e\u0641\u064e\u0651\u064a\u0646\u0650 \u0648\u0645\u0627 \u0641\u064a \u0645\u0639\u0646\u0627\u0647\u064f\u0645\u0627 \u0645\u0646\u064e \u0627\u0644\u062c\u064e\u0648\u0631\u0628\u064e\u064a\u0646\u0650 \u0648\u0627\u0644\u0645\u064f\u0648\u0642\u064e\u064a\u0646\u0650 \u0648\u0627\u0644\u062a\u064e\u0651\u0633\u0627\u062e\u064a\u0646\u0650.",src:160},{t:"tf",q:"\u0645\u0634\u0631\u0648\u0639\u064a\u064e\u0651\u0629\u064f \u0627\u0644\u0645\u0633\u062d\u0650 \u0639\u0644\u0649 \u0627\u0644\u062e\u0641\u064e\u0651\u064a\u0646\u0650 \u062b\u0628\u062a\u064e\u062a\u0652 \u0628\u0627\u0644\u0633\u064f\u0651\u0646\u064e\u0651\u0629\u0650 \u0648\u062d\u062f\u064e\u0647\u0627 \u062f\u0648\u0646\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u0650.",a:!1,e:"\u0628\u0644\u0652 \u062b\u0628\u062a\u064e\u062a\u0652 \u0628\u0627\u0644\u0643\u062a\u0627\u0628\u0650 \u0648\u0627\u0644\u0633\u064f\u0651\u0646\u064e\u0651\u0629\u0650\u061b \u0623\u0645\u064e\u0651\u0627 \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0641\u0642\u0631\u0627\u0621\u0629\u064f \u0627\u0644\u062c\u0631\u0650\u0651 \u0641\u064a {\u0648\u064e\u0623\u064e\u0631\u0652\u062c\u064f\u0644\u064e\u0643\u064f\u0645\u0652}\u060c \u0648\u0623\u0645\u064e\u0651\u0627 \u0627\u0644\u0633\u064f\u0651\u0646\u064e\u0651\u0629\u064f \u0641\u062d\u062f\u064a\u062b\u064f: \xab\u0641\u0644\u0628\u0650\u0633\u064e \u062e\u0641\u064e\u0651\u064a\u0647\u0650 \u0641\u0644\u064a\u0645\u0633\u062d\u0652 \u0639\u0644\u064a\u0647\u0650\u0645\u0627\xbb.",src:161},{t:"tf",q:"\u0644\u0627 \u0641\u0631\u0642\u064e \u0628\u064a\u0646\u064e \u0627\u0644\u0631\u064e\u0651\u062c\u0644\u0650 \u0648\u0627\u0644\u0645\u0631\u0623\u0629\u0650 \u0641\u064a \u0628\u0627\u0628\u0650 \u0645\u0633\u062d\u0650 \u0627\u0644\u062e\u0641\u064e\u0651\u064a\u0646\u0650 \u0648\u0627\u0644\u062c\u0628\u0627\u0626\u0631\u0650 \u0648\u063a\u0637\u0627\u0621\u0650 \u0627\u0644\u0631\u064e\u0651\u0623\u0633\u0650.",a:!0,e:"\u0642\u0627\u0644\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f: \u0641\u0645\u0627 \u062c\u0627\u0632\u064e \u0644\u0644\u0631\u064e\u0651\u062c\u0644\u0650 \u062c\u0627\u0632\u064e \u0644\u0644\u0645\u0631\u0623\u0629\u0650 \u0639\u0644\u0649 \u062d\u062f\u064d\u0651 \u0633\u0648\u0627\u0621\u064d.",src:162}]},{id:"u04l3",title:"\u0634\u0631\u0648\u0637\u064f \u0627\u0644\u0645\u0633\u062d\u0650 \u0648\u0643\u064a\u0641\u064a\u064e\u0651\u062a\u064f\u0647\u064f",items:[{t:"info",h:"\u0634\u0631\u0648\u0637\u064f \u0627\u0644\u0645\u0633\u062d\u0650 \u0639\u0644\u0649 \u0627\u0644\u062e\u0641\u064e\u0651\u064a\u0646\u0650",b:"\u064a\u064f\u0634\u062a\u0631\u0637\u064f: \u0644\u064f\u0628\u0633\u064f\u0647\u064f\u0645\u0627 \u0639\u0644\u0649 \u0637\u0647\u0627\u0631\u0629\u064d\u060c \u0648\u0623\u0646\u0652 \u064a\u0643\u0648\u0646\u0627 \u0633\u0627\u062a\u0631\u064e\u064a\u0646\u0650 \u0644\u0645\u062d\u0644\u0650\u0651 \u0627\u0644\u0641\u0631\u0636\u0650\u060c \u0633\u0645\u064a\u0643\u064e\u064a\u0646\u0650 \u0644\u0627 \u062a\u0628\u062f\u0648 \u0627\u0644\u0628\u0634\u0631\u0629\u064f \u0645\u0646\u0652 \u062a\u062d\u062a\u0650\u0647\u0650\u0645\u0627\u060c \u0648\u0623\u0644\u064e\u0651\u0627 \u062a\u0632\u064a\u062f\u064e \u0645\u062f\u064e\u0651\u0629\u064f \u0627\u0644\u0645\u0633\u062d\u0650 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0631\u064e\u0651\u0631\u0650\u060c \u0648\u0623\u0644\u064e\u0651\u0627 \u064a\u0646\u0632\u0639\u064e\u0647\u064f\u0645\u0627 \u0628\u0639\u062f\u064e \u0627\u0644\u0645\u0633\u062d\u0650.",src:161},{t:"mcq",q:"\u0643\u0645\u0652 \u0645\u062f\u064e\u0651\u0629\u064f \u0627\u0644\u0645\u0633\u062d\u0650 \u0639\u0644\u0649 \u0627\u0644\u062e\u0641\u064e\u0651\u064a\u0646\u0650 \u0644\u0644\u0645\u0642\u064a\u0645\u0650 \u0648\u0644\u0644\u0645\u0633\u0627\u0641\u0631\u0650\u061f",o:["\u064a\u0648\u0645\u064c \u0648\u0644\u064a\u0644\u0629\u064c \u0644\u0644\u0645\u0642\u064a\u0645\u0650\u060c \u0648\u062b\u0644\u0627\u062b\u0629\u064f \u0623\u064a\u064e\u0651\u0627\u0645\u064d \u0628\u0644\u064a\u0627\u0644\u064a\u0647\u0627 \u0644\u0644\u0645\u0633\u0627\u0641\u0631\u0650","\u062b\u0644\u0627\u062b\u0629\u064f \u0623\u064a\u064e\u0651\u0627\u0645\u064d \u0644\u0644\u0645\u0642\u064a\u0645\u0650\u060c \u0648\u064a\u0648\u0645\u064c \u0648\u0644\u064a\u0644\u0629\u064c \u0644\u0644\u0645\u0633\u0627\u0641\u0631\u0650","\u064a\u0648\u0645\u064c \u0648\u0644\u064a\u0644\u0629\u064c \u0644\u0647\u064f\u0645\u0627 \u062c\u0645\u064a\u0639\u064b\u0627","\u0644\u0627 \u062a\u0648\u0642\u064a\u062a\u064e \u0641\u064a \u0627\u0644\u0645\u0633\u062d\u0650 \u0623\u0635\u0644\u064b\u0627"],a:0,e:"\u0644\u0642\u0648\u0644\u0650 \u0639\u0644\u064a\u064d\u0651 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647\u064f: \xab\u062c\u0639\u0644\u064e \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647\u0650 \u062b\u0644\u0627\u062b\u0629\u064e \u0623\u064a\u064e\u0651\u0627\u0645\u064d \u0648\u0644\u064a\u0627\u0644\u064a\u0647\u0646\u064e\u0651 \u0644\u0644\u0645\u0633\u0627\u0641\u0631\u0650\u060c \u0648\u064a\u0648\u0645\u064b\u0627 \u0648\u0644\u064a\u0644\u0629\u064b \u0644\u0644\u0645\u0642\u064a\u0645\u0650\xbb.",src:161},{t:"mcq",q:"\u0628\u0645\u064e \u0627\u0633\u062a\u062f\u0644\u064e\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0639\u0644\u0649 \u0627\u0634\u062a\u0631\u0627\u0637\u0650 \u0644\u064f\u0628\u0633\u0650 \u0627\u0644\u062e\u0641\u064e\u0651\u064a\u0646\u0650 \u0639\u0644\u0649 \u0637\u0647\u0627\u0631\u0629\u064d\u061f",o:["\u0628\u0642\u0648\u0644\u0650 \u0623\u0645\u0650\u0651 \u0639\u0637\u064a\u064e\u0651\u0629\u064e \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647\u0627","\u0628\u0642\u0631\u0627\u0621\u0629\u0650 \u0627\u0644\u062c\u0631\u0650\u0651 \u0641\u064a \u0622\u064a\u0629\u0650 \u0627\u0644\u0645\u0627\u0626\u062f\u0629\u0650","\u0628\u062d\u062f\u064a\u062b\u0650 \u062d\u0645\u0646\u0629\u064e \u0628\u0646\u062a\u0650 \u062c\u062d\u0634\u064d \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647\u0627","\u0628\u062d\u062f\u064a\u062b\u0650 \u0627\u0644\u0645\u064f\u063a\u064a\u0631\u0629\u0650 \u0628\u0646\u0650 \u0634\u0639\u0628\u0629\u064e \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647\u064f"],a:3,e:"\u0642\u0627\u0644\u064e \u0644\u0647\u064f \ufdfa \u0644\u0645\u064e\u0651\u0627 \u0623\u0631\u0627\u062f\u064e \u0623\u0646\u0652 \u064a\u0646\u0632\u0639\u064e \u062e\u0641\u064e\u0651\u064a\u0650 \u0627\u0644\u0646\u064e\u0651\u0628\u064a\u0650\u0651 \u0644\u064a\u063a\u0633\u0644\u064e \u0631\u062c\u0644\u064a\u0647\u0650 \u0641\u064a \u0648\u0636\u0648\u0626\u0650\u0647\u0650: \xab\u062f\u0639\u0652\u0647\u064f\u0645\u0627 \u0641\u0625\u0646\u0650\u0651\u064a \u0623\u062f\u062e\u0644\u062a\u064f\u0647\u064f\u0645\u0627 \u0637\u0627\u0647\u0631\u062a\u064e\u064a\u0646\u0650\xbb.",src:161},{t:"tf",q:"\u0644\u0648\u0652 \u0646\u0632\u0639\u064e \u0627\u0644\u062e\u0641\u064e\u0651\u064a\u0646\u0650 \u0628\u0639\u062f\u064e \u0627\u0644\u0645\u0633\u062d\u0650 \u0648\u062c\u0628\u064e \u0639\u0644\u064a\u0647\u0650 \u063a\u0633\u0644\u064f \u0631\u062c\u0644\u064a\u0647\u0650\u060c \u0648\u0625\u0644\u064e\u0651\u0627 \u0628\u0637\u0644\u064e \u0648\u0636\u0648\u0624\u064f\u0647\u064f.",a:!0,e:"\u0647\u0648\u064e \u0627\u0644\u0634\u064e\u0651\u0631\u0637\u064f \u0627\u0644\u062e\u0627\u0645\u0633\u064f \u0639\u0646\u062f\u064e \u0627\u0644\u0645\u0624\u0644\u0650\u0651\u0641\u0650: \u0623\u0644\u064e\u0651\u0627 \u064a\u0646\u0632\u0639\u064e\u0647\u064f\u0645\u0627 \u0628\u0639\u062f\u064e \u0627\u0644\u0645\u0633\u062d\u0650.",src:161},{t:"match",q:"\u0648\u0635\u0650\u0651\u0644\u0652 \u0643\u0644\u064e\u0651 \u0645\u0645\u0633\u0648\u062d\u064d \u0639\u0644\u064a\u0647\u0650 \u0628\u0645\u0627 \u0630\u0643\u0631\u064e\u0647\u064f \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0641\u064a \u0634\u0623\u0646\u0650\u0647\u0650",pairs:[["\u0627\u0644\u062e\u0641\u064e\u0651\u0627\u0646\u0650","\u062a\u0642\u062f\u064f\u0651\u0645\u064f \u0627\u0644\u0637\u064e\u0651\u0647\u0627\u0631\u0629\u0650 \u0648\u0627\u0644\u062a\u064e\u0651\u0648\u0642\u064a\u062a\u064f \u0628\u0645\u062f\u064e\u0651\u0629\u064d \u0645\u0639\u0644\u0648\u0645\u0629\u064d"],["\u0627\u0644\u062c\u0628\u064a\u0631\u0629\u064f","\u0623\u0644\u064e\u0651\u0627 \u062a\u0632\u064a\u062f\u064e \u0639\u0644\u0649 \u0645\u062d\u0644\u0650\u0651 \u0627\u0644\u062c\u0631\u062d\u0650 \u0648\u0623\u0644\u064e\u0651\u0627 \u064a\u0628\u0631\u0623\u064e \u0627\u0644\u062c\u0631\u062d\u064f"],["\u0627\u0644\u0639\u0645\u0627\u0645\u0629\u064f","\u062a\u064f\u0645\u0633\u062d\u064f \u0644\u0636\u0631\u0648\u0631\u0629\u0650 \u0628\u0631\u062f\u064d \u0623\u0648\u0652 \u0633\u0641\u0631\u064d \u0645\u0639\u064e \u0645\u0633\u062d\u0650 \u0628\u0639\u0636\u0650 \u0627\u0644\u0646\u064e\u0651\u0627\u0635\u064a\u0629\u0650"]],e:"\u0644\u0643\u0644\u0650\u0651 \u0645\u0645\u0633\u0648\u062d\u064d \u0639\u0644\u064a\u0647\u0650 \u0628\u0627\u0628\u064f\u0647\u064f \u0639\u0646\u062f\u064e \u0627\u0644\u0645\u0624\u0644\u0650\u0651\u0641\u0650\u061b \u0648\u0645\u0633\u062d\u064f \u0627\u0644\u0639\u0645\u0627\u0645\u0629\u0650 \u0625\u0646\u064e\u0651\u0645\u0627 \u064a\u0643\u0648\u0646\u064f \u0644\u0636\u0631\u0648\u0631\u0629\u0650 \u0628\u0631\u062f\u064d \u0623\u0648\u0652 \u0633\u0641\u0631\u064d\u060c \u0644\u0631\u0648\u0627\u064a\u0629\u0650 \u0645\u0633\u0644\u0645\u064d \u0623\u0646\u064e\u0651\u0647\u064f \ufdfa \u0645\u0633\u062d\u064e \u0628\u0646\u0627\u0635\u064a\u062a\u0650\u0647\u0650 \u0648\u0639\u0644\u0649 \u0627\u0644\u0639\u0645\u0627\u0645\u0629\u0650\u060c \u0641\u0644\u0627 \u0628\u062f\u064e\u0651 \u0645\u0639\u064e\u0647\u0627 \u0645\u0646\u0652 \u0645\u0633\u062d\u0650 \u0628\u0639\u0636\u0650 \u0627\u0644\u0646\u064e\u0651\u0627\u0635\u064a\u0629\u0650.",src:161},{t:"tf",q:"\u064a\u064f\u0634\u062a\u0631\u0637\u064f \u0644\u0644\u0645\u0633\u062d\u0650 \u0639\u0644\u0649 \u0627\u0644\u062c\u0628\u064a\u0631\u0629\u0650 \u0623\u0646\u0652 \u062a\u064f\u0648\u0636\u0639\u064e \u0639\u0644\u0649 \u0637\u0647\u0627\u0631\u0629\u064d \u0643\u0645\u0627 \u064a\u064f\u0634\u062a\u0631\u0637\u064f \u0630\u0644\u0643\u064e \u0641\u064a \u0627\u0644\u062e\u0641\u064e\u0651\u064a\u0646\u0650.",a:!1,e:"\u0627\u0644\u062c\u0628\u064a\u0631\u0629\u064f \u062a\u064f\u062e\u0627\u0644\u0641\u064f \u0627\u0644\u062e\u0641\u064e\u0651 \u0647\u0646\u0627\u061b \u0641\u0644\u0627 \u064a\u0644\u0632\u0645\u064f \u0648\u0636\u0639\u064f\u0647\u0627 \u0639\u0644\u0649 \u0637\u0647\u0627\u0631\u0629\u064d\u060c \u0648\u0644\u0627 \u062a\u064f\u062d\u064e\u062f\u064f\u0651 \u0628\u0645\u062f\u064e\u0651\u0629\u064d \u0645\u0639\u0644\u0648\u0645\u0629\u064d.",src:161},{t:"mcq",q:"\u0623\u064a\u064f\u0651 \u0647\u0630\u0647\u0650 \u0645\u0646\u0652 \u0634\u0631\u0648\u0637\u0650 \u0627\u0644\u062c\u0628\u064a\u0631\u0629\u0650 \u0627\u0644\u064e\u0651\u062a\u064a \u0646\u0635\u064e\u0651 \u0639\u0644\u064a\u0647\u0627 \u0627\u0644\u0643\u062a\u0627\u0628\u064f\u061f",o:["\u0623\u0644\u064e\u0651\u0627 \u062a\u064f\u0646\u0632\u0639\u064e \u0645\u0646\u0652 \u0645\u0643\u0627\u0646\u0650\u0647\u0627\u060c \u0648\u0623\u0644\u064e\u0651\u0627 \u062a\u0632\u064a\u062f\u064e \u0639\u0644\u0649 \u0627\u0644\u062c\u0631\u062d\u0650 \u0625\u0644\u064e\u0651\u0627 \u0628\u0642\u062f\u0631\u0650 \u0627\u0644\u0631\u064e\u0651\u0628\u0637\u0650","\u0623\u0646\u0652 \u062a\u064f\u0648\u0636\u0639\u064e \u0628\u0639\u062f\u064e \u0637\u0647\u0627\u0631\u0629\u064d \u0643\u0627\u0645\u0644\u0629\u064d\u060c \u0648\u0623\u0646\u0652 \u064a\u064f\u062c\u062f\u064e\u0651\u062f\u064e \u0627\u0644\u0645\u0633\u062d\u064f \u0639\u0644\u064a\u0647\u0627 \u0643\u0644\u064e\u0651 \u064a\u0648\u0645\u064d","\u0623\u0646\u0652 \u062a\u0643\u0648\u0646\u064e \u0633\u0645\u064a\u0643\u0629\u064b \u0644\u0627 \u064a\u0646\u0641\u0630\u064f \u0645\u0646\u0647\u0627 \u0627\u0644\u0645\u0627\u0621\u064f\u060c \u0648\u0623\u0646\u0652 \u062a\u0633\u062a\u0648\u0639\u0628\u064e \u0627\u0644\u0639\u0636\u0648\u064e \u0643\u0644\u064e\u0651\u0647\u064f","\u0623\u0646\u0652 \u064a\u064f\u062a\u064a\u0645\u064e\u0651\u0645\u064e \u0644\u0647\u0627 \u0642\u0628\u0644\u064e \u0627\u0644\u0645\u0633\u062d\u0650\u060c \u0648\u0623\u0646\u0652 \u064a\u064f\u0645\u0633\u062d\u064e \u0639\u0644\u064a\u0647\u0627 \u062b\u0644\u0627\u062b\u064e \u0645\u0631\u064e\u0651\u0627\u062a\u064d"],a:0,e:"\u0634\u0631\u0637\u0627\u0646\u0650 \u0630\u0643\u0631\u064e\u0647\u064f\u0645\u0627 \u0627\u0644\u0645\u0624\u0644\u0650\u0651\u0641\u064f: \u0623\u0644\u064e\u0651\u0627 \u062a\u062a\u062c\u0627\u0648\u0632\u064e \u0627\u0644\u062c\u0628\u064a\u0631\u0629\u064f \u0645\u0648\u0636\u0639\u064e \u0627\u0644\u062c\u0631\u062d\u0650 \u0625\u0644\u064e\u0651\u0627 \u0628\u0642\u062f\u0631\u0650 \u0645\u0627 \u064a\u0644\u0632\u0645\u064f \u0644\u0634\u062f\u0650\u0651\u0647\u0627\u060c \u0648\u0623\u0646\u0652 \u062a\u0628\u0642\u0649 \u0641\u064a \u0645\u0643\u0627\u0646\u0650\u0647\u0627 \u0641\u0644\u0627 \u062a\u064f\u0646\u0632\u0639\u064e.",src:161},{t:"mcq",q:"\u0625\u0630\u0627 \u0633\u0642\u0637\u064e\u062a\u0650 \u0627\u0644\u062c\u0628\u064a\u0631\u0629\u064f \u0623\u0648\u0652 \u0628\u0631\u0626\u064e \u0627\u0644\u062c\u0631\u062d\u064f\u060c \u0641\u0645\u0627 \u0627\u0644\u062d\u0643\u0645\u064f\u061f",o:["\u064a\u0628\u0642\u0649 \u0627\u0644\u0645\u0633\u062d\u064f \u0635\u062d\u064a\u062d\u064b\u0627 \u0643\u0645\u0627 \u0647\u0648\u064e","\u0628\u0637\u0644\u064e \u0627\u0644\u0645\u0633\u062d\u064f \u0648\u0648\u062c\u0628\u064e \u0627\u0644\u063a\u0633\u0644\u064f","\u064a\u064f\u0639\u064a\u062f\u064f \u0627\u0644\u0645\u0633\u062d\u064e \u0645\u0631\u064e\u0651\u0629\u064b \u062b\u0627\u0646\u064a\u0629\u064b","\u064a\u062a\u064a\u0645\u064e\u0651\u0645\u064f \u0628\u062f\u0644\u064b\u0627 \u0645\u0646\u064e \u0627\u0644\u0645\u0633\u062d\u0650"],a:1,e:"\u0646\u0635\u064e\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u064f: \u0641\u0625\u0646\u0652 \u0633\u0642\u0637\u064e\u062a\u0652 \u0623\u0648\u0652 \u0628\u0631\u0626\u064e \u0627\u0644\u062c\u0631\u062d\u064f \u0628\u0637\u0644\u064e \u0627\u0644\u0645\u0633\u062d\u064f \u0648\u0648\u062c\u0628\u064e \u0627\u0644\u063a\u0633\u0644\u064f.",src:161},{t:"order",q:"\u0631\u062a\u0650\u0651\u0628\u0652 \u0643\u064a\u0641\u064a\u064e\u0651\u0629\u064e \u0627\u0644\u0645\u0633\u062d\u0650 \u0639\u0644\u0649 \u0627\u0644\u062e\u0641\u064e\u0651\u064a\u0646\u0650 \u0643\u0645\u0627 \u0648\u0635\u0641\u064e\u0647\u0627 \u0627\u0644\u0643\u062a\u0627\u0628\u064f",items:["\u064a\u0628\u0644\u064f\u0651 \u064a\u062f\u064a\u0647\u0650","\u064a\u0636\u0639\u064f \u0628\u0627\u0637\u0646\u064e \u0643\u0641\u0650\u0651\u0647\u0650 \u0627\u0644\u064a\u0633\u0631\u0649 \u062a\u062d\u062a\u064e \u0639\u0642\u0628\u0650 \u0627\u0644\u062e\u0641\u0650\u0651\u060c \u0648\u0643\u0641\u064e\u0651 \u0627\u0644\u064a\u0645\u0646\u0649 \u0639\u0644\u0649 \u0623\u0637\u0631\u0627\u0641\u0650 \u0623\u0635\u0627\u0628\u0639\u0650\u0647\u0650","\u064a\u064f\u0645\u0650\u0631\u064f\u0651 \u0627\u0644\u064a\u0645\u0646\u0649 \u0625\u0644\u0649 \u0633\u0627\u0642\u0650\u0647\u0650 \u0648\u0627\u0644\u064a\u0633\u0631\u0649 \u0625\u0644\u0649 \u0623\u0637\u0631\u0627\u0641\u0650 \u0623\u0635\u0627\u0628\u0639\u0650\u0647\u0650"],e:"\u0631\u062a\u064e\u0651\u0628\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0647\u0630\u0647\u0650 \u0627\u0644\u062e\u064f\u0637\u0627 \u0628\u0640\xab\u062b\u0645\u064e\u0651\xbb: \u0641\u0627\u0644\u0628\u0644\u064f\u0651 \u0642\u0628\u0644\u064e \u0648\u0636\u0639\u0650 \u0627\u0644\u0643\u0641\u064e\u0651\u064a\u0646\u0650\u060c \u0648\u0627\u0644\u0625\u0645\u0631\u0627\u0631\u064f \u0628\u0639\u062f\u064e \u0648\u0636\u0639\u0650\u0647\u0650\u0645\u0627\u061b \u0648\u0625\u0645\u0631\u0627\u0631\u064f \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0627\u0644\u064a\u0633\u0631\u0649 \u062d\u0631\u0643\u0629\u064c \u0648\u0627\u062d\u062f\u0629\u064c \u0639\u0637\u0641\u064e\u0647\u0627 \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0628\u0627\u0644\u0648\u0627\u0648\u0650 \u0641\u0644\u0627 \u062a\u0631\u062a\u064a\u0628\u064e \u0628\u064a\u0646\u064e\u0647\u064f\u0645\u0627.",src:162},{t:"fill",q:"\u0648\u0623\u0645\u064e\u0651\u0627 \u0627\u0644\u0645\u0633\u062d\u064f \u0639\u0644\u0649 \u0627\u0644\u062c\u0628\u0627\u0626\u0631\u0650 \u0641\u064a\u0628\u0644\u064f\u0651 \u064a\u062f\u064e\u0647\u064f \u0648\u064a\u0645\u0633\u062d\u064f \u0641\u0648\u0642\u064e \u0627\u0644\u062c\u0628\u064a\u0631\u0629\u0650 \u0643\u0644\u0650\u0651\u0647\u0627 ____.",bank:["\u0645\u0631\u064e\u0651\u0629\u064b \u0648\u0627\u062d\u062f\u0629\u064b","\u0645\u0631\u064e\u0651\u062a\u064e\u064a\u0646\u0650","\u062b\u0644\u0627\u062b\u064e \u0645\u0631\u064e\u0651\u0627\u062a\u064d"],a:"\u0645\u0631\u064e\u0651\u0629\u064b \u0648\u0627\u062d\u062f\u0629\u064b",e:"\u0646\u0635\u064f\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u0650: \u0648\u064a\u0645\u0633\u062d\u064f \u0641\u0648\u0642\u064e \u0627\u0644\u062c\u0628\u064a\u0631\u0629\u0650 \u0643\u0644\u0650\u0651\u0647\u0627 \u0645\u0631\u064e\u0651\u0629\u064b \u0648\u0627\u062d\u062f\u0629\u064b.",src:162}]},{id:"u04l4",title:"\u0627\u0644\u062d\u064a\u0636\u064f \u0648\u0623\u0642\u0633\u0627\u0645\u064f \u0627\u0644\u0646\u0650\u0651\u0633\u0627\u0621\u0650 \u0641\u064a\u0647\u0650",items:[{t:"info",h:"\u062a\u0639\u0631\u064a\u0641\u064f \u0627\u0644\u062d\u064a\u0636\u0650",b:"\u0627\u0644\u062d\u064a\u0636\u064f \u062f\u0645\u064c \u064a\u062f\u0641\u0639\u064f\u0647\u064f \u0631\u062d\u0645\u064f \u0627\u0644\u0645\u0631\u0623\u0629\u0650 \u0628\u0639\u062f\u064e \u0628\u0644\u0648\u063a\u0650\u0647\u0627\u060c \u064a\u0623\u062a\u064a\u0647\u0627 \u0641\u064a \u0645\u0648\u0627\u0639\u064a\u062f\u064e \u062a\u062a\u0643\u0631\u064e\u0651\u0631\u064f\u060c \u0648\u062d\u0643\u0645\u062a\u064f\u0647\u064f \u062a\u0631\u0628\u064a\u0629\u064f \u0627\u0644\u0648\u0644\u062f\u0650.",src:162},{t:"info",h:"\u0627\u0644\u0646\u0650\u0651\u0633\u0627\u0621\u064f \u0641\u064a \u0627\u0644\u062d\u064a\u0636\u0650 \u062b\u0644\u0627\u062b\u064c",b:"\u0642\u0633\u064e\u0651\u0645\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0627\u0644\u0646\u0650\u0651\u0633\u0627\u0621\u064e \u0641\u064a \u0627\u0644\u062d\u064a\u0636\u0650 \u062b\u0644\u0627\u062b\u064b\u0627: \u0645\u064f\u0628\u062a\u062f\u0623\u0629\u064c\u060c \u0648\u0645\u0639\u062a\u0627\u062f\u0629\u064c\u060c \u0648\u0645\u0633\u062a\u062d\u0627\u0636\u0629\u064c\u060c \u0648\u0644\u0643\u0644\u0650\u0651 \u0648\u0627\u062d\u062f\u0629\u064d \u0645\u0646\u0647\u0646\u064e\u0651 \u062d\u0643\u0645\u064c \u064a\u062e\u0635\u064f\u0651\u0647\u0627.",src:162},{t:"mcq",q:"\u0643\u0645\u0652 \u0623\u0642\u0644\u064f\u0651 \u0627\u0644\u062d\u064a\u0636\u0650 \u0648\u0623\u0643\u062b\u0631\u064f\u0647\u064f \u0639\u0646\u062f\u064e \u0627\u0644\u0645\u0624\u0644\u0650\u0651\u0641\u0650\u061f",o:["\u0623\u0642\u0644\u064f\u0651\u0647\u064f \u062b\u0644\u0627\u062b\u0629\u064f \u0623\u064a\u064e\u0651\u0627\u0645\u064d \u0648\u0623\u0643\u062b\u0631\u064f\u0647\u064f \u0639\u0634\u0631\u0629\u064c","\u0623\u0642\u0644\u064f\u0651\u0647\u064f \u064a\u0648\u0645\u064c \u0648\u0644\u064a\u0644\u0629\u064c \u0648\u0623\u0643\u062b\u0631\u064f\u0647\u064f \u062e\u0645\u0633\u0629\u064e \u0639\u0634\u0631\u064e \u064a\u0648\u0645\u064b\u0627","\u0623\u0642\u0644\u064f\u0651\u0647\u064f \u064a\u0648\u0645\u064c \u0648\u0623\u0643\u062b\u0631\u064f\u0647\u064f \u0623\u0631\u0628\u0639\u0648\u0646\u064e \u064a\u0648\u0645\u064b\u0627","\u0644\u0627 \u062d\u062f\u064e\u0651 \u0644\u0623\u0642\u0644\u0650\u0651\u0647\u0650 \u0648\u0644\u0627 \u0644\u0623\u0643\u062b\u0631\u0650\u0647\u0650"],a:1,e:"\u0642\u0627\u0644\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f: \u0648\u0623\u0642\u0644\u064f\u0651\u0647\u064f \u064a\u0648\u0645\u064c \u0648\u0644\u064a\u0644\u0629\u064c\u060c \u0648\u0623\u0643\u062b\u0631\u064f\u0647\u064f \u062e\u0645\u0633\u0629\u064e \u0639\u0634\u0631\u064e \u064a\u0648\u0645\u064b\u0627\u060c \u0648\u063a\u0627\u0644\u0628\u064f\u0647\u064f \u0633\u062a\u064e\u0651\u0629\u064f \u0623\u0648\u0652 \u0633\u0628\u0639\u0629\u064f \u0623\u064a\u064e\u0651\u0627\u0645\u064d.",src:162},{t:"match",q:"\u0648\u0635\u0650\u0651\u0644\u0652 \u0643\u0644\u064e\u0651 \u0645\u064f\u062f\u064e\u0651\u0629\u064d \u0628\u0645\u0642\u062f\u0627\u0631\u0650\u0647\u0627 \u0639\u0646\u062f\u064e \u0627\u0644\u0645\u0624\u0644\u0650\u0651\u0641\u0650",pairs:[["\u063a\u0627\u0644\u0628\u064f \u0627\u0644\u062d\u064a\u0636\u0650","\u0633\u062a\u064e\u0651\u0629\u064f \u0623\u0648\u0652 \u0633\u0628\u0639\u0629\u064f \u0623\u064a\u064e\u0651\u0627\u0645\u064d"],["\u0623\u0642\u0644\u064f\u0651 \u0627\u0644\u0637\u064f\u0651\u0647\u0631\u0650","\u062b\u0644\u0627\u062b\u0629\u064e \u0639\u0634\u0631\u064e \u064a\u0648\u0645\u064b\u0627 \u0623\u0648\u0652 \u062e\u0645\u0633\u0629\u064e \u0639\u0634\u0631\u064e \u064a\u0648\u0645\u064b\u0627"],["\u0623\u0643\u062b\u0631\u064f \u0627\u0644\u0637\u064f\u0651\u0647\u0631\u0650","\u0644\u0627 \u062d\u062f\u064e\u0651 \u0644\u0647\u064f"],["\u063a\u0627\u0644\u0628\u064f \u0627\u0644\u0637\u064f\u0651\u0647\u0631\u0650","\u062b\u0644\u0627\u062b\u0629\u064c \u0623\u0648\u0652 \u0623\u0631\u0628\u0639\u0629\u064c \u0648\u0639\u0634\u0631\u0648\u0646\u064e \u064a\u0648\u0645\u064b\u0627"]],e:"\u0647\u0630\u0647\u0650 \u0645\u064f\u062f\u064e\u062f\u064f \u0627\u0644\u062d\u064a\u0636\u0650 \u0648\u0627\u0644\u0637\u064f\u0651\u0647\u0631\u0650 \u0643\u0645\u0627 \u0639\u062f\u064e\u0651\u0647\u0627 \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0641\u064a \u062a\u0639\u0631\u064a\u0641\u0650 \u0627\u0644\u062d\u064a\u0636\u0650.",src:162},{t:"tf",q:"\u0627\u0644\u0645\u0628\u062a\u062f\u0623\u0629\u064f \u0625\u0630\u0627 \u0631\u0623\u062a\u0650 \u0627\u0644\u062f\u064e\u0651\u0645\u064e \u0623\u0648\u064e\u0651\u0644\u064e \u0645\u0631\u064e\u0651\u0629\u064d \u062a\u0631\u0643\u062a\u0650 \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u064e \u0648\u0627\u0644\u0635\u064e\u0651\u0648\u0645\u064e \u0648\u0627\u0644\u0648\u0637\u0621\u064e \u0648\u0627\u0646\u062a\u0638\u0631\u062a\u0650 \u0627\u0644\u0637\u064f\u0651\u0647\u0631\u064e.",a:!0,e:"\u0646\u0635\u064f\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u0650 \u0641\u064a \u062d\u0643\u0645\u0650 \u0627\u0644\u0645\u0628\u062a\u062f\u0623\u0629\u0650: \u0625\u0630\u0627 \u0631\u0623\u062a\u0650 \u0627\u0644\u062f\u064e\u0651\u0645\u064e \u062a\u0631\u0643\u062a\u0650 \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u064e \u0648\u0627\u0644\u0635\u064e\u0651\u0648\u0645\u064e \u0648\u0627\u0644\u0648\u0637\u0621\u064e\u060c \u0648\u0627\u0646\u062a\u0638\u0631\u062a\u0650 \u0627\u0644\u0637\u064f\u0651\u0647\u0631\u064e.",src:162},{t:"mcq",q:"\u0627\u0644\u0645\u0628\u062a\u062f\u0623\u0629\u064f \u0625\u0630\u0627 \u0627\u0633\u062a\u0645\u0631\u064e\u0651 \u0645\u0639\u0647\u0627 \u0627\u0644\u062f\u064e\u0651\u0645\u064f \u0628\u0639\u062f\u064e \u062e\u0645\u0633\u0629\u064e \u0639\u0634\u0631\u064e \u064a\u0648\u0645\u064b\u0627:",o:["\u0628\u0642\u0650\u064a\u064e\u062a\u0652 \u062d\u0627\u0626\u0636\u064b\u0627 \u062d\u062a\u064e\u0651\u0649 \u064a\u0646\u0642\u0637\u0639\u064e \u0627\u0644\u062f\u064e\u0651\u0645\u064f","\u0623\u0639\u0627\u062f\u064e\u062a\u0650 \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u064e \u0643\u0644\u064e\u0651\u0647\u0627","\u0627\u0639\u062a\u064f\u0628\u0631\u064e\u062a\u0652 \u0645\u0633\u062a\u062d\u0627\u0636\u0629\u064b \u0628\u0639\u062f\u064e \u0630\u0644\u0643\u064e \u0648\u062d\u0643\u0645\u064f\u0647\u0627 \u062d\u0643\u0645\u064f \u0627\u0644\u0645\u0633\u062a\u062d\u0627\u0636\u0629\u0650","\u0627\u0646\u062a\u0638\u0631\u064e\u062a\u0652 \u062a\u0645\u0627\u0645\u064e \u0623\u0631\u0628\u0639\u064a\u0646\u064e \u064a\u0648\u0645\u064b\u0627"],a:2,e:"\u0645\u062a\u0649 \u0627\u0646\u0642\u0637\u0639\u064e \u0627\u0644\u062f\u064e\u0651\u0645\u064f \u0641\u064a \u0645\u062f\u064e\u0651\u0629\u064d \u0628\u064a\u0646\u064e \u064a\u0648\u0645\u064d \u0648\u0644\u064a\u0644\u0629\u064d \u0648\u062e\u0645\u0633\u0629\u064e \u0639\u0634\u0631\u064e \u064a\u0648\u0645\u064b\u0627 \u0641\u0647\u0648\u064e \u062d\u064a\u0636\u064c\u060c \u062a\u063a\u062a\u0633\u0644\u064f \u0628\u0639\u062f\u064e\u0647\u064f \u0648\u062a\u064f\u0635\u0644\u0650\u0651\u064a\u061b \u0641\u0625\u0646\u0652 \u062c\u0627\u0648\u0632\u064e \u0627\u0644\u062f\u064e\u0651\u0645\u064f \u0647\u0630\u0647\u0650 \u0627\u0644\u0645\u062f\u064e\u0651\u0629\u064e \u0635\u0627\u0631\u064e\u062a\u0652 \u0645\u0633\u062a\u062d\u0627\u0636\u0629\u064b \u062a\u0623\u062e\u0630\u064f \u062d\u0643\u0645\u064e\u0647\u0627.",src:162},{t:"tf",q:"\u0627\u0644\u0645\u0628\u062a\u062f\u0623\u0629\u064f \u0625\u0630\u0627 \u062a\u0642\u0637\u064e\u0651\u0639\u064e \u062f\u0645\u064f\u0647\u0627 \u062e\u0644\u0627\u0644\u064e \u0627\u0644\u062e\u0645\u0633\u0629\u064e \u0639\u0634\u0631\u064e \u064a\u0648\u0645\u064b\u0627 \u0627\u063a\u062a\u0633\u0644\u064e\u062a\u0652 \u0648\u0635\u0644\u064e\u0651\u062a\u0652 \u0643\u0644\u064e\u0651\u0645\u0627 \u0631\u0623\u062a\u0650 \u0627\u0644\u0637\u064f\u0651\u0647\u0631\u064e\u060c \u0648\u0642\u0639\u062f\u064e\u062a\u0652 \u0643\u0644\u064e\u0651\u0645\u0627 \u0631\u0623\u062a\u0650 \u0627\u0644\u062f\u064e\u0651\u0645\u064e.",a:!0,e:"\u0647\u0648\u064e \u0646\u0635\u064f\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u0650 \u0641\u064a\u0645\u0646\u0652 \u062a\u0631\u0627\u0647\u064f \u064a\u0648\u0645\u064b\u0627 \u0623\u0648\u0652 \u064a\u0648\u0645\u064e\u064a\u0646\u0650 \u0648\u064a\u0646\u0642\u0637\u0639\u064f \u0645\u062b\u0644\u064e \u0630\u0644\u0643\u064e.",src:163},{t:"mcq",q:"\u0627\u0644\u0645\u0639\u062a\u0627\u062f\u0629\u064f \u062a\u0631\u0649 \u0635\u064f\u0641\u0631\u0629\u064b \u0623\u0648\u0652 \u0643\u064f\u062f\u0631\u0629\u064b \u0628\u0639\u062f\u064e \u0627\u0646\u0642\u0636\u0627\u0621\u0650 \u0639\u0627\u062f\u062a\u0650\u0647\u0627\u060c \u0641\u0645\u0627\u0630\u0627 \u062a\u0635\u0646\u0639\u064f\u061f",o:["\u062a\u062a\u0631\u0643\u064f \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u064e \u0648\u0627\u0644\u0635\u064e\u0651\u0648\u0645\u064e \u0645\u0646\u0652 \u0623\u062c\u0644\u0650\u0647\u0627","\u062a\u0635\u064a\u0631\u064f \u0628\u0647\u0627 \u0645\u0633\u062a\u062d\u0627\u0636\u0629\u064b \u062a\u062a\u0648\u0636\u064e\u0651\u0623\u064f \u0644\u0643\u0644\u0650\u0651 \u0635\u0644\u0627\u0629\u064d","\u062a\u0633\u062a\u0638\u0647\u0631\u064f \u0628\u062b\u0644\u0627\u062b\u0629\u0650 \u0623\u064a\u064e\u0651\u0627\u0645\u064d \u062b\u0645\u064e\u0651 \u062a\u063a\u062a\u0633\u0644\u064f \u0648\u062a\u064f\u0635\u0644\u0650\u0651\u064a","\u0644\u0627 \u062a\u0644\u062a\u0641\u062a\u064f \u0625\u0644\u064a\u0647\u0627 \u0648\u0644\u0627 \u062a\u062f\u0639\u064f \u0644\u0647\u0627 \u0635\u0644\u0627\u0629\u064b \u0648\u0644\u0627 \u0635\u0648\u0645\u064b\u0627"],a:3,e:"\u0644\u0642\u0648\u0644\u0650 \u0623\u0645\u0650\u0651 \u0639\u0637\u064a\u064e\u0651\u0629\u064e \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647\u0627: \xab\u0643\u0646\u064e\u0651\u0627 \u0644\u0627 \u0646\u0639\u064f\u062f\u064f\u0651 \u0627\u0644\u0635\u064f\u0651\u0641\u0631\u0629\u064e \u0623\u0648\u0650 \u0627\u0644\u0643\u064f\u062f\u0631\u0629\u064e \u0628\u0639\u062f\u064e \u0627\u0644\u0637\u064f\u0651\u0647\u0631\u0650 \u0634\u064a\u0626\u064b\u0627\xbb\u060c \u0623\u0645\u064e\u0651\u0627 \u0625\u0630\u0627 \u0631\u0623\u062a\u0652 \u0630\u0644\u0643\u064e \u0623\u062b\u0646\u0627\u0621\u064e \u0639\u0627\u062f\u062a\u0650\u0647\u0627 \u0641\u0647\u0648\u064e \u0645\u0646\u0652 \u062d\u064a\u0636\u062a\u0650\u0647\u0627.",src:163},{t:"fill",q:"\u0627\u0644\u0645\u0639\u062a\u0627\u062f\u0629\u064f \u0647\u064a\u064e \u0645\u0646\u0652 \u0643\u0627\u0646\u062a\u0652 \u0644\u0647\u0627 ____ \u0645\u0639\u0644\u0648\u0645\u0629\u064c \u062a\u062d\u064a\u0636\u064f\u0647\u0627 \u0645\u0646\u064e \u0627\u0644\u0634\u064e\u0651\u0647\u0631\u0650.",bank:["\u0623\u064a\u064e\u0651\u0627\u0645\u064c","\u0639\u0644\u0627\u0645\u0629\u064c","\u0635\u0641\u0629\u064c"],a:"\u0623\u064a\u064e\u0651\u0627\u0645\u064c",e:"\u0644\u0641\u0638\u064f \u0627\u0644\u0643\u062a\u0627\u0628\u0650: (\u0648\u0647\u064a\u064e \u0645\u0646\u0652 \u0643\u0627\u0646\u062a\u0652 \u0644\u0647\u0627 \u0623\u064a\u064e\u0651\u0627\u0645\u064c \u0645\u0639\u0644\u0648\u0645\u0629\u064c \u062a\u062d\u064a\u0636\u064f\u0647\u0627 \u0645\u0646\u064e \u0627\u0644\u0634\u064e\u0651\u0647\u0631\u0650)\u061b \u0641\u0627\u0644\u0639\u0627\u062f\u0629\u064f \u0639\u0646\u062f\u064e \u0627\u0644\u0645\u0624\u0644\u0650\u0651\u0641\u0650 \u0645\u0642\u062f\u0627\u0631\u064c \u0632\u0645\u0646\u064a\u064c\u0651 \u0645\u0639\u062f\u0648\u062f\u064c\u060c \u0644\u0627 \u0639\u0644\u0627\u0645\u0629\u064c \u0641\u064a \u0627\u0644\u062f\u064e\u0651\u0645\u0650 \u0648\u0644\u0627 \u0635\u0641\u0629\u064c \u0641\u064a\u0647\u0650\u060c \u0648\u062d\u0643\u0645\u064f\u0647\u0627 \u0623\u0646\u064e\u0651\u0647\u0627 \u062a\u062a\u0631\u0643\u064f \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u064e \u0648\u0627\u0644\u0635\u064e\u0651\u0648\u0645\u064e \u0648\u0627\u0644\u0648\u0637\u0621\u064e \u0623\u064a\u064e\u0651\u0627\u0645\u064e \u0639\u0627\u062f\u062a\u0650\u0647\u0627.",src:163},{t:"tf",q:"\u0630\u0643\u0631\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u062e\u0644\u0627\u0641\u064b\u0627 \u0641\u064a \u0639\u062f\u0650\u0651 \u0627\u0644\u062d\u0627\u0645\u0644\u0650 \u0642\u0633\u0645\u064b\u0627 \u0631\u0627\u0628\u0639\u064b\u0627\u061b \u0641\u0632\u0627\u062f\u064e\u0647\u0627 \u0628\u0639\u0636\u064f \u0627\u0644\u0645\u0627\u0644\u0643\u064a\u064e\u0651\u0629\u0650 \u0648\u0627\u0644\u0634\u064e\u0651\u0627\u0641\u0639\u064a\u064e\u0651\u0629\u0650 \u062f\u0648\u0646\u064e \u0627\u0644\u062d\u0646\u0627\u0628\u0644\u0629\u0650 \u0648\u0627\u0644\u062d\u0646\u0641\u064a\u064e\u0651\u0629\u0650.",a:!0,e:"\u0648\u0627\u0644\u062d\u0646\u0627\u0628\u0644\u0629\u064f \u0648\u0627\u0644\u0623\u062d\u0646\u0627\u0641\u064f \u0644\u0627 \u064a\u0639\u064f\u062f\u064f\u0651\u0648\u0646\u064e \u0627\u0644\u062f\u064e\u0651\u0645\u064e \u0641\u064a \u0627\u0644\u062d\u0645\u0644\u0650 \u062d\u064a\u0636\u064b\u0627\u060c \u0625\u0644\u064e\u0651\u0627 \u0645\u0627 \u0643\u0627\u0646\u064e \u0642\u0628\u0644\u064e \u0627\u0644\u0648\u0644\u0627\u062f\u0629\u0650 \u0628\u064a\u0648\u0645\u064d \u0623\u0648\u0652 \u064a\u0648\u0645\u064e\u064a\u0646\u0650 \u0623\u0648\u0652 \u062b\u0644\u0627\u062b\u0629\u064d \u0641\u062d\u0643\u0645\u064f\u0647\u064f \u062d\u0643\u0645\u064f \u062f\u0645\u0650 \u0627\u0644\u0646\u0650\u0651\u0641\u0627\u0633\u0650.",src:162}]},{id:"u04l5",title:"\u0627\u0644\u0645\u0633\u062a\u062d\u0627\u0636\u0629\u064f \u0648\u0627\u0644\u0646\u0650\u0651\u0641\u0627\u0633\u064f \u0648\u0645\u0639\u0631\u0641\u0629\u064f \u0627\u0644\u0637\u064f\u0651\u0647\u0631\u0650",items:[{t:"info",h:"\u0645\u0646\u0650 \u0627\u0644\u0645\u0633\u062a\u062d\u0627\u0636\u0629\u064f\u061f",b:"\u0627\u0644\u0645\u0633\u062a\u062d\u0627\u0636\u0629\u064f \u0647\u064a\u064e \u0627\u0644\u064e\u0651\u062a\u064a \u0644\u0627 \u064a\u0646\u0642\u0637\u0639\u064f \u0639\u0646\u0647\u0627 \u062c\u0631\u064a\u0627\u0646\u064f \u0627\u0644\u062f\u064e\u0651\u0645\u0650\u060c \u0648\u062d\u0643\u0645\u064f\u0647\u0627 \u064a\u062e\u062a\u0644\u0641\u064f \u0628\u062d\u0633\u0628\u0650 \u0645\u0639\u0631\u0641\u062a\u0650\u0647\u0627 \u0644\u0639\u0627\u062f\u062a\u0650\u0647\u0627 \u0648\u062a\u0645\u064a\u064a\u0632\u0650 \u062f\u0645\u0650\u0647\u0627.",src:163},{t:"mcq",q:"\u0627\u0644\u0645\u0633\u062a\u062d\u0627\u0636\u0629\u064f \u0627\u0644\u064e\u0651\u062a\u064a \u0643\u0627\u0646\u062a\u0652 \u0645\u0639\u062a\u0627\u062f\u0629\u064b \u0648\u062a\u0639\u0631\u0641\u064f \u0623\u064a\u064e\u0651\u0627\u0645\u064e \u0639\u0627\u062f\u062a\u0650\u0647\u0627\u060c \u0645\u0627 \u062d\u0643\u0645\u064f\u0647\u0627\u061f",o:["\u062a\u062c\u0644\u0633\u064f \u062e\u0645\u0633\u0629\u064e \u0639\u0634\u0631\u064e \u064a\u0648\u0645\u064b\u0627 \u0645\u0646\u0652 \u0643\u0644\u0650\u0651 \u0634\u0647\u0631\u064d \u062b\u0645\u064e\u0651 \u062a\u063a\u062a\u0633\u0644\u064f","\u062a\u0642\u0639\u062f\u064f \u0623\u064a\u064e\u0651\u0627\u0645\u064e \u0639\u0627\u062f\u062a\u0650\u0647\u0627 \u062b\u0645\u064e\u0651 \u062a\u063a\u062a\u0633\u0644\u064f \u0648\u062a\u064f\u0635\u0644\u0650\u0651\u064a \u0648\u062a\u064f\u0648\u0637\u0623\u064f","\u062a\u062c\u0644\u0633\u064f \u0633\u062a\u064e\u0651\u0629\u064e \u0623\u0648\u0652 \u0633\u0628\u0639\u0629\u064e \u0623\u064a\u064e\u0651\u0627\u0645\u064d \u062b\u0645\u064e\u0651 \u062a\u063a\u062a\u0633\u0644\u064f \u0648\u062a\u064f\u0635\u0644\u0650\u0651\u064a","\u0644\u0627 \u062a\u0642\u0639\u062f\u064f \u0639\u0646\u0650 \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650 \u0634\u064a\u0626\u064b\u0627 \u0645\u0646\u0652 \u0623\u064a\u064e\u0651\u0627\u0645\u0650 \u0627\u0644\u0634\u064e\u0651\u0647\u0631\u0650"],a:1,e:"\u0634\u0627\u0647\u062f\u064f\u0647\u064f \u062d\u062f\u064a\u062b\u064f \u0623\u0645\u0650\u0651 \u0633\u0644\u0645\u0629\u064e: \xab\u0644\u062a\u0646\u0638\u0631\u0652 \u0639\u062f\u064e\u0651\u0629\u064e \u0627\u0644\u0644\u064e\u0651\u064a\u0627\u0644\u064a \u0648\u0627\u0644\u0623\u064a\u064e\u0651\u0627\u0645\u0650 \u0627\u0644\u064e\u0651\u062a\u064a \u0643\u0627\u0646\u062a\u0652 \u062a\u062d\u064a\u0636\u064f\u0647\u0646\u064e\u0651 \u0645\u0646\u064e \u0627\u0644\u0634\u064e\u0651\u0647\u0631\u0650... \u0641\u0644\u062a\u062a\u0631\u0643\u0650 \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u064e \u0642\u062f\u0631\u064e \u0630\u0644\u0643\u064e \u0645\u0646\u064e \u0627\u0644\u0634\u064e\u0651\u0647\u0631\u0650\xbb\u061b \u0641\u0625\u0630\u0627 \u0627\u0646\u0642\u0636\u064e\u062a\u0652 \u0639\u0627\u062f\u062a\u064f\u0647\u0627 \u0627\u063a\u062a\u0633\u0644\u064e\u062a\u0652 \u0648\u0635\u0644\u064e\u0651\u062a\u0652 \u0648\u0635\u0627\u0645\u064e\u062a\u0652 \u0648\u062a\u064f\u0648\u0637\u0623\u064f.",src:163},{t:"mcq",q:"\u0645\u0646\u0652 \u0644\u0627 \u0639\u0627\u062f\u0629\u064e \u0644\u0647\u0627\u060c \u0644\u0643\u0646\u064e\u0651 \u062f\u0645\u064e\u0647\u0627 \u0645\u062a\u0645\u064a\u0650\u0651\u0632\u064c \u064a\u062c\u0631\u064a \u0645\u0631\u064e\u0651\u0629\u064b \u0623\u0633\u0648\u062f\u064e \u0648\u0645\u0631\u064e\u0651\u0629\u064b \u0623\u062d\u0645\u0631\u064e:",o:["\u062a\u062c\u0644\u0633\u064f \u0623\u064a\u064e\u0651\u0627\u0645\u064e \u0627\u0644\u0623\u0633\u0648\u062f\u0650\u060c \u062b\u0645\u064e\u0651 \u062a\u063a\u062a\u0633\u0644\u064f \u0648\u062a\u064f\u0635\u0644\u0650\u0651\u064a \u0628\u0639\u062f\u064e \u0627\u0646\u0642\u0636\u0627\u0626\u0650\u0647\u0650 \u0645\u0627 \u0644\u0645\u0652 \u064a\u062a\u062c\u0627\u0648\u0632\u0652 \u062e\u0645\u0633\u0629\u064e \u0639\u0634\u0631\u064e \u064a\u0648\u0645\u064b\u0627","\u062a\u062c\u0644\u0633\u064f \u0623\u064a\u064e\u0651\u0627\u0645\u064e \u0627\u0644\u0623\u062d\u0645\u0631\u0650\u060c \u062b\u0645\u064e\u0651 \u062a\u063a\u062a\u0633\u0644\u064f \u0648\u062a\u064f\u0635\u0644\u0650\u0651\u064a \u0628\u0639\u062f\u064e \u0627\u0646\u0642\u0636\u0627\u0626\u0650\u0647\u0650 \u0645\u0627 \u0644\u0645\u0652 \u064a\u062a\u062c\u0627\u0648\u0632\u0652 \u062e\u0645\u0633\u0629\u064e \u0639\u0634\u0631\u064e \u064a\u0648\u0645\u064b\u0627","\u062a\u062c\u0644\u0633\u064f \u0627\u0644\u0634\u064e\u0651\u0647\u0631\u064e \u0643\u0644\u064e\u0651\u0647\u064f\u060c \u062b\u0645\u064e\u0651 \u062a\u063a\u062a\u0633\u0644\u064f \u0641\u064a \u0622\u062e\u0631\u0650\u0647\u0650 \u0648\u062a\u064f\u0635\u0644\u0650\u0651\u064a \u0648\u0644\u0648\u0652 \u0644\u0645\u0652 \u064a\u0646\u0642\u0637\u0639\u0652 \u0639\u0646\u0647\u0627 \u0627\u0644\u062f\u064e\u0651\u0645\u064f","\u0644\u0627 \u062a\u062c\u0644\u0633\u064f \u0634\u064a\u0626\u064b\u0627\u060c \u0628\u0644\u0652 \u062a\u063a\u062a\u0633\u0644\u064f \u0644\u0643\u0644\u0650\u0651 \u0635\u0644\u0627\u0629\u064d \u0648\u062a\u064f\u0635\u0644\u0650\u0651\u064a \u0645\u0627 \u062f\u0627\u0645\u064e \u0627\u0644\u062f\u064e\u0651\u0645\u064f \u062c\u0627\u0631\u064a\u064b\u0627"],a:0,e:"\u0648\u0634\u0627\u0647\u062f\u064f\u0647\u064f \u062d\u062f\u064a\u062b\u064f \u0641\u0627\u0637\u0645\u0629\u064e \u0628\u0646\u062a\u0650 \u0623\u0628\u064a \u062d\u064f\u0628\u064e\u064a\u0634\u064d: \xab\u0625\u0630\u0627 \u0643\u0627\u0646\u064e \u062f\u0645\u064f \u0627\u0644\u062d\u064a\u0636\u0650 \u0641\u0625\u0646\u064e\u0651\u0647\u064f \u0623\u0633\u0648\u062f\u064f \u064a\u064f\u0639\u0631\u0641\u064f... \u0641\u0625\u0630\u0627 \u0643\u0627\u0646\u064e \u0627\u0644\u0622\u062e\u0631\u064f \u0641\u062a\u0648\u0636\u064e\u0651\u0626\u064a \u0640 \u0628\u0639\u062f\u064e \u0627\u0644\u0627\u063a\u062a\u0633\u0627\u0644\u0650 \u0640 \u0648\u0635\u0644\u0650\u0651\u064a\u061b \u0641\u0625\u0646\u064e\u0651\u0645\u0627 \u0647\u0648\u064e \u0639\u0631\u0642\u064c\xbb.",src:163},{t:"mcq",q:"\u0645\u0646\u0652 \u0644\u0627 \u0639\u0627\u062f\u0629\u064e \u0644\u0647\u0627 \u0648\u0644\u0627 \u062a\u0645\u064a\u064a\u0632\u064e \u0644\u062f\u0645\u0650\u0647\u0627\u060c \u0643\u0645\u0652 \u062a\u062c\u0644\u0633\u064f \u0645\u0646\u0652 \u0643\u0644\u0650\u0651 \u0634\u0647\u0631\u064d\u061f",o:["\u062b\u0644\u0627\u062b\u0629\u064e \u0623\u064a\u064e\u0651\u0627\u0645\u064d \u062b\u0645\u064e\u0651 \u062a\u063a\u062a\u0633\u0644\u064f \u0648\u062a\u064f\u0635\u0644\u0650\u0651\u064a","\u062e\u0645\u0633\u0629\u064e \u0639\u0634\u0631\u064e \u064a\u0648\u0645\u064b\u0627 \u062b\u0645\u064e\u0651 \u062a\u063a\u062a\u0633\u0644\u064f \u0648\u062a\u064f\u0635\u0644\u0650\u0651\u064a","\u0633\u062a\u064e\u0651\u0629\u064e \u0623\u0648\u0652 \u0633\u0628\u0639\u0629\u064e \u0623\u064a\u064e\u0651\u0627\u0645\u064d \u062b\u0645\u064e\u0651 \u062a\u063a\u062a\u0633\u0644\u064f \u0648\u062a\u064f\u0635\u0644\u0650\u0651\u064a","\u0623\u0631\u0628\u0639\u064a\u0646\u064e \u064a\u0648\u0645\u064b\u0627 \u062b\u0645\u064e\u0651 \u062a\u063a\u062a\u0633\u0644\u064f \u0648\u062a\u064f\u0635\u0644\u0650\u0651\u064a"],a:2,e:"\u062a\u062c\u0644\u0633\u064f \u0645\u0646\u0652 \u0643\u0644\u0650\u0651 \u0634\u0647\u0631\u064d \u0623\u063a\u0644\u0628\u064e \u0627\u0644\u062d\u064a\u0636\u0650\u061b \u0648\u0634\u0627\u0647\u062f\u064f\u0647\u064f \u062d\u062f\u064a\u062b\u064f \u062d\u0645\u0646\u0629\u064e \u0628\u0646\u062a\u0650 \u062c\u062d\u0634\u064d: \xab\u0641\u062a\u062d\u064a\u064e\u0651\u0636\u064a \u0633\u062a\u064e\u0651\u0629\u064e \u0623\u064a\u064e\u0651\u0627\u0645\u064d \u0623\u0648\u0652 \u0633\u0628\u0639\u0629\u064e \u0623\u064a\u064e\u0651\u0627\u0645\u064d\u060c \u062b\u0645\u064e\u0651 \u0627\u063a\u062a\u0633\u0644\u064a\xbb.",src:163},{t:"tf",q:"\u0627\u0644\u0645\u0633\u062a\u062d\u0627\u0636\u0629\u064f \u0623\u064a\u064e\u0651\u0627\u0645\u064e \u0627\u0633\u062a\u062d\u0627\u0636\u062a\u0650\u0647\u0627 \u062a\u062a\u0648\u0636\u064e\u0651\u0623\u064f \u0644\u0643\u0644\u0650\u0651 \u0635\u0644\u0627\u0629\u064d \u0648\u062a\u0633\u062a\u062b\u0641\u0650\u0631\u064f \u0648\u062a\u064f\u0635\u0644\u0650\u0651\u064a \u0648\u0644\u0648\u0652 \u0643\u0627\u0646\u064e \u0627\u0644\u062f\u064e\u0651\u0645\u064f \u064a\u0635\u064f\u0628\u064f\u0651 \u0635\u0628\u064b\u0651\u0627.",a:!0,e:"\u0647\u0648\u064e \u0646\u0635\u064f\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u0650\u060c \u0648\u0632\u0627\u062f\u064e: \u0648\u0644\u0627 \u062a\u064f\u0648\u0637\u0623\u064f \u0625\u0644\u064e\u0651\u0627 \u0644\u0636\u0631\u0648\u0631\u0629\u064d.",src:163},{t:"info",h:"\u062a\u0639\u0631\u064a\u0641\u064f \u0627\u0644\u0646\u0650\u0651\u0641\u0627\u0633\u0650",b:"\u0627\u0644\u0646\u0650\u0651\u0641\u0627\u0633\u064f \u0647\u0648\u064e \u0627\u0644\u062f\u064e\u0651\u0645\u064f \u0627\u0644\u062e\u0627\u0631\u062c\u064f \u0645\u0646\u064e \u0627\u0644\u0641\u0631\u062c\u0650 \u0639\u0642\u0628\u064e \u0627\u0644\u0648\u0644\u0627\u062f\u0629\u0650\u060c \u0648\u0644\u0627 \u062d\u062f\u064e\u0651 \u0644\u0623\u0642\u0644\u0650\u0651\u0647\u0650\u060c \u0648\u0623\u0643\u062b\u0631\u064f\u0647\u064f \u0623\u0631\u0628\u0639\u0648\u0646\u064e \u064a\u0648\u0645\u064b\u0627.",src:164},{t:"mcq",q:"\u0627\u0644\u0646\u064f\u0651\u0641\u0633\u0627\u0621\u064f \u0625\u0630\u0627 \u0631\u0623\u062a\u0650 \u0627\u0644\u0637\u064f\u0651\u0647\u0631\u064e \u0642\u0628\u0644\u064e \u062a\u0645\u0627\u0645\u0650 \u0627\u0644\u0623\u0631\u0628\u0639\u064a\u0646\u064e:",o:["\u062a\u0646\u062a\u0638\u0631\u064f \u062a\u0645\u0627\u0645\u064e \u0627\u0644\u0623\u0631\u0628\u0639\u064a\u0646\u064e \u062b\u0645\u064e\u0651 \u062a\u063a\u062a\u0633\u0644\u064f","\u062a\u064f\u0639\u062f\u064f\u0651 \u0645\u0633\u062a\u062d\u0627\u0636\u0629\u064b","\u062a\u0642\u0636\u064a \u0645\u0627 \u0641\u0627\u062a\u064e\u0647\u0627 \u0645\u0646\u064e \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650","\u062a\u063a\u062a\u0633\u0644\u064f \u0648\u062a\u064f\u0635\u0644\u0650\u0651\u064a\u061b \u0625\u0630\u0652 \u0644\u0627 \u062d\u062f\u064e\u0651 \u0644\u0623\u0642\u0644\u0650\u0651 \u0627\u0644\u0646\u0650\u0651\u0641\u0627\u0633\u0650"],a:3,e:"\u0633\u064f\u0626\u0644\u064e \ufdfa: \u0643\u0645\u0652 \u062a\u062c\u0644\u0633\u064f \u0627\u0644\u0645\u0631\u0623\u0629\u064f \u0625\u0630\u0627 \u0648\u0644\u062f\u064e\u062a\u0652\u061f \u0641\u0642\u0627\u0644\u064e: \xab\u0623\u0631\u0628\u0639\u064a\u0646\u064e \u064a\u0648\u0645\u064b\u0627\u060c \u0625\u0644\u064e\u0651\u0627 \u0623\u0646\u0652 \u062a\u0631\u0649 \u0627\u0644\u0637\u064f\u0651\u0647\u0631\u064e \u0642\u0628\u0644\u064e \u0630\u0644\u0643\u064e\xbb.",src:164},{t:"tf",q:"\u0627\u0644\u0646\u064f\u0651\u0641\u0633\u0627\u0621\u064f \u0625\u0630\u0627 \u0631\u0623\u062a\u0650 \u0627\u0644\u0637\u064f\u0651\u0647\u0631\u064e \u0642\u0628\u0644\u064e \u0627\u0644\u0623\u0631\u0628\u0639\u064a\u0646\u064e \u062d\u064e\u0631\u064f\u0645\u064e \u0639\u0644\u064a\u0647\u0627 \u0627\u0644\u0648\u0637\u0621\u064f \u062d\u062a\u064e\u0651\u0649 \u062a\u064f\u062a\u0650\u0645\u064e\u0651 \u0627\u0644\u0623\u0631\u0628\u0639\u064a\u0646\u064e.",a:!1,e:"\u0628\u0644\u0652 \u064a\u064f\u0643\u0631\u064e\u0647\u064f \u0644\u0647\u0627 \u0643\u0631\u0627\u0647\u0629\u064e \u062a\u0646\u0632\u064a\u0647\u064d \u0642\u0628\u0644\u064e \u0627\u0644\u0623\u0631\u0628\u0639\u064a\u0646\u064e \u064a\u0648\u0645\u064b\u0627 \u062e\u0634\u064a\u0629\u064e \u0623\u0646\u0652 \u062a\u062a\u0623\u0630\u064e\u0651\u0649 \u0628\u0627\u0644\u0648\u0637\u0621\u0650\u060c \u0644\u0627 \u062a\u062d\u0631\u064a\u0645\u064b\u0627.",src:164},{t:"tf",q:"\u0625\u0630\u0627 \u0628\u0644\u063a\u062a\u0650 \u0627\u0644\u0646\u064f\u0651\u0641\u0633\u0627\u0621\u064f \u0623\u0631\u0628\u0639\u064a\u0646\u064e \u064a\u0648\u0645\u064b\u0627 \u0648\u0644\u0645\u0652 \u062a\u0637\u0647\u0631\u0652 \u0628\u0642\u0650\u064a\u064e\u062a\u0652 \u0639\u0644\u0649 \u062d\u0643\u0645\u0650 \u0627\u0644\u0646\u0650\u0651\u0641\u0627\u0633\u0650 \u062d\u062a\u064e\u0651\u0649 \u062a\u0637\u0647\u0631\u064e.",a:!1,e:"\u0628\u0644\u0652 \u062a\u063a\u062a\u0633\u0644\u064f \u0648\u062a\u064f\u0635\u0644\u0650\u0651\u064a \u0648\u062a\u0635\u0648\u0645\u064f \u0648\u0644\u0648\u0652 \u0644\u0645\u0652 \u062a\u0637\u0647\u0631\u0652\u060c \u0648\u062a\u0635\u064a\u0631\u064f \u0643\u0627\u0644\u0645\u0633\u062a\u062d\u0627\u0636\u0629\u0650 \u0633\u0648\u0627\u0621\u064b \u0628\u0633\u0648\u0627\u0621\u064d. \u0648\u0639\u0646\u0652 \u0628\u0639\u0636\u0650 \u0623\u0647\u0644\u0650 \u0627\u0644\u0639\u0644\u0645\u0650 \u0623\u0646\u064e\u0651\u0647\u0627 \u062a\u062c\u0644\u0633\u064f \u062e\u0645\u0633\u064a\u0646\u064e \u0623\u0648\u0652 \u0633\u062a\u0650\u0651\u064a\u0646\u064e \u064a\u0648\u0645\u064b\u0627\u060c \u0648\u0643\u0648\u0646\u064f\u0647\u0627 \u062a\u062c\u0644\u0633\u064f \u0623\u0631\u0628\u0639\u064a\u0646\u064e \u0623\u062d\u0648\u0637\u064f \u0644\u062f\u064a\u0646\u0650\u0647\u0627.",src:164},{t:"match",q:"\u0648\u0635\u0650\u0651\u0644\u0652 \u0643\u0644\u064e\u0651 \u0645\u0635\u0637\u0644\u062d\u064d \u0628\u0645\u0627 \u064a\u064f\u0642\u0627\u0628\u0644\u064f\u0647\u064f \u0639\u0646\u062f\u064e \u0627\u0644\u0645\u0624\u0644\u0650\u0651\u0641\u0650",pairs:[["\u0627\u0644\u0642\u064e\u0635\u064e\u0651\u0629\u064f \u0627\u0644\u0628\u064a\u0636\u0627\u0621\u064f","\u0645\u0627\u0621\u064c \u0623\u0628\u064a\u0636\u064f \u064a\u062e\u0631\u062c\u064f \u0639\u0642\u0628\u064e \u0627\u0644\u0637\u064f\u0651\u0647\u0631\u0650"],["\u0627\u0644\u062c\u0641\u0648\u0641\u064f","\u0623\u0646\u0652 \u062a\u064f\u062f\u062e\u0644\u064e \u0627\u0644\u0642\u0637\u0646\u0629\u064e \u0641\u062a\u064f\u062e\u0631\u062c\u064e\u0647\u0627 \u062c\u0627\u0641\u064e\u0651\u0629\u064b"],["\u0648\u0642\u062a\u064f \u0627\u062e\u062a\u0628\u0627\u0631\u0650 \u0627\u0644\u0637\u064f\u0651\u0647\u0631\u0650","\u0642\u0628\u0644\u064e \u0627\u0644\u0646\u064e\u0651\u0648\u0645\u0650 \u0648\u0628\u0639\u062f\u064e\u0647\u064f"]],e:"\u064a\u064f\u0639\u0631\u0641\u064f \u0627\u0644\u0637\u064f\u0651\u0647\u0631\u064f \u0628\u0623\u062d\u062f\u0650 \u0634\u064a\u0626\u064e\u064a\u0646\u0650: \u0627\u0644\u0642\u064e\u0635\u064e\u0651\u0629\u0650 \u0627\u0644\u0628\u064a\u0636\u0627\u0621\u0650 \u0648\u0627\u0644\u062c\u0641\u0648\u0641\u0650\u060c \u062a\u0641\u0639\u0644\u064f \u0630\u0644\u0643\u064e \u0642\u0628\u0644\u064e \u0627\u0644\u0646\u064e\u0651\u0648\u0645\u0650 \u0648\u0628\u0639\u062f\u064e\u0647\u064f \u0644\u062a\u0631\u0649 \u0647\u0644\u0652 \u0637\u0647\u0631\u064e\u062a\u0652 \u0623\u0645\u0652 \u0644\u0645\u0652 \u062a\u0637\u0647\u0631\u0652.",src:164}]},{id:"u04l6",title:"\u0645\u0627 \u064a\u064f\u0645\u0646\u0639\u064f \u0628\u0627\u0644\u062d\u064a\u0636\u0650 \u0648\u0627\u0644\u0646\u0650\u0651\u0641\u0627\u0633\u0650 \u0648\u0645\u0627 \u064a\u064f\u0628\u0627\u062d\u064f",items:[{t:"info",h:"\u062e\u0645\u0633\u0629\u064c \u062a\u064f\u0645\u0646\u0639\u064f \u0628\u0627\u0644\u062d\u064a\u0636\u0650 \u0648\u0627\u0644\u0646\u0650\u0651\u0641\u0627\u0633\u0650",b:"\u064a\u0645\u0646\u0639\u064f \u0628\u0627\u0644\u062d\u064a\u0636\u0650 \u0648\u0627\u0644\u0646\u0650\u0651\u0641\u0627\u0633\u0650: \u0627\u0644\u0648\u0637\u0621\u064f\u060c \u0648\u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u064f \u0648\u0627\u0644\u0635\u0650\u0651\u064a\u0627\u0645\u064f\u060c \u0648\u062f\u062e\u0648\u0644\u064f \u0627\u0644\u0645\u0633\u062c\u062f\u0650\u060c \u0648\u0642\u0631\u0627\u0621\u0629\u064f \u0627\u0644\u0642\u0631\u0622\u0646\u0650\u060c \u0648\u0627\u0644\u0637\u064e\u0651\u0644\u0627\u0642\u064f.",src:165},{t:"mcq",q:"\u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u064f \u0648\u0627\u0644\u0635\u064e\u0651\u0648\u0645\u064f \u064a\u0633\u0642\u0637\u0627\u0646\u0650 \u0628\u0627\u0644\u062d\u064a\u0636\u0650\u060c \u0641\u0645\u0627 \u062d\u0643\u0645\u064f \u0642\u0636\u0627\u0626\u0650\u0647\u0650\u0645\u0627\u061f",o:["\u064a\u064f\u0642\u0636\u064a\u0627\u0646\u0650 \u062c\u0645\u064a\u0639\u064b\u0627 \u0628\u0639\u062f\u064e \u0627\u0644\u0637\u064f\u0651\u0647\u0631\u0650","\u0644\u0627 \u064a\u064f\u0642\u0636\u0649 \u0648\u0627\u062d\u062f\u064c \u0645\u0646\u0647\u064f\u0645\u0627","\u0627\u0644\u0635\u064e\u0651\u0648\u0645\u064f \u064a\u064f\u0642\u0636\u0649 \u0628\u0639\u062f\u064e \u0627\u0644\u0637\u064f\u0651\u0647\u0631\u0650 \u0648\u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u064f \u0644\u0627 \u062a\u064f\u0642\u0636\u0649","\u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u064f \u062a\u064f\u0642\u0636\u0649 \u0648\u0627\u0644\u0635\u064e\u0651\u0648\u0645\u064f \u0644\u0627 \u064a\u064f\u0642\u0636\u0649"],a:2,e:"\u0644\u0642\u0648\u0644\u0650 \u0639\u0627\u0626\u0634\u0629\u064e \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647\u0627: \xab\u0643\u0646\u064e\u0651\u0627 \u0646\u062d\u064a\u0636\u064f \u0639\u0644\u0649 \u0639\u0647\u062f\u0650 \u0631\u0633\u0648\u0644\u0650 \u0627\u0644\u0644\u0647\u0650 \ufdfa \u0641\u0646\u064f\u0624\u0645\u0631\u064f \u0628\u0642\u0636\u0627\u0621\u0650 \u0627\u0644\u0635\u064e\u0651\u0648\u0645\u0650 \u0648\u0644\u0627 \u0646\u064f\u0624\u0645\u0631\u064f \u0628\u0642\u0636\u0627\u0621\u0650 \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650\xbb.",src:165},{t:"tf",q:"\u0627\u0644\u062d\u0627\u0626\u0636\u064f \u0644\u0627 \u062a\u064f\u0637\u0644\u064e\u0651\u0642\u064f\u060c \u0628\u0644\u0652 \u064a\u064f\u0646\u062a\u0638\u0631\u064f \u0628\u0647\u0627 \u062d\u062a\u064e\u0651\u0649 \u062a\u0637\u0647\u0631\u064e.",a:!0,e:"\u0644\u0645\u064e\u0651\u0627 \u0637\u0644\u064e\u0651\u0642\u064e \u0627\u0628\u0646\u064f \u0639\u0645\u0631\u064e \u0627\u0645\u0631\u0623\u062a\u064e\u0647\u064f \u0648\u0647\u064a\u064e \u062d\u0627\u0626\u0636\u064c \u0623\u0645\u0631\u064e\u0647\u064f \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647\u0650 \ufdfa \u0623\u0646\u0652 \u064a\u064f\u0631\u0627\u062c\u0639\u064e\u0647\u0627 \u0648\u064a\u064f\u0645\u0633\u0643\u064e\u0647\u0627 \u062d\u062a\u064e\u0651\u0649 \u062a\u0637\u0647\u0631\u064e\u060c \u0648\u0642\u0628\u0644\u064e \u0623\u0646\u0652 \u064a\u0645\u0633\u064e\u0651\u0647\u0627 \u062a\u064f\u0637\u0644\u064e\u0651\u0642\u064f.",src:165},{t:"fill",q:"\u0642\u0627\u0644\u064e \u062a\u0639\u0627\u0644\u0649 \u0641\u064a \u0645\u0646\u0639\u0650 \u0627\u0644\u0648\u0637\u0621\u0650: {\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0652\u0631\u064e\u0628\u064f\u0648\u0647\u064f\u0646\u064e\u0651 \u062d\u064e\u062a\u064e\u0651\u0649 ____}.",bank:["\u064a\u064e\u0637\u0652\u0647\u064f\u0631\u0652\u0646\u064e","\u064a\u064e\u063a\u0652\u062a\u064e\u0633\u0650\u0644\u0652\u0646\u064e","\u064a\u064f\u0635\u064e\u0644\u0650\u0651\u064a\u0646\u064e"],a:"\u064a\u064e\u0637\u0652\u0647\u064f\u0631\u0652\u0646\u064e",e:"\u0627\u0644\u0622\u064a\u0629\u064f \u0645\u0646\u0652 \u0633\u0648\u0631\u0629\u0650 \u0627\u0644\u0628\u0642\u0631\u0629\u0650 [\u0662\u0662\u0662]\u060c \u0648\u0647\u064a\u064e \u0623\u0648\u064e\u0651\u0644\u064f \u0623\u062f\u0644\u064e\u0651\u0629\u0650 \u0645\u0627 \u064a\u064f\u0645\u0646\u0639\u064f \u0628\u0627\u0644\u062d\u064a\u0636\u0650 \u0648\u0627\u0644\u0646\u0650\u0651\u0641\u0627\u0633\u0650.",src:165},{t:"match",q:"\u0648\u0635\u0650\u0651\u0644\u0652 \u0643\u0644\u064e\u0651 \u062d\u0643\u0645\u064d \u0628\u062f\u0644\u064a\u0644\u0650\u0647\u0650 \u0643\u0645\u0627 \u0633\u0627\u0642\u064e\u0647\u064f \u0627\u0644\u0643\u062a\u0627\u0628\u064f",pairs:[["\u0645\u0646\u0639\u064f \u062f\u062e\u0648\u0644\u0650 \u0627\u0644\u0645\u0633\u062c\u062f\u0650","\xab\u0644\u0627 \u0623\u064f\u062d\u0650\u0644\u064f\u0651 \u0627\u0644\u0645\u0633\u062c\u062f\u064e \u0644\u062d\u0627\u0626\u0636\u064d \u0648\u0644\u0627 \u0644\u062c\u064f\u0646\u0628\u064d\xbb"],["\u0645\u0646\u0639\u064f \u0642\u0631\u0627\u0621\u0629\u0650 \u0627\u0644\u0642\u0631\u0622\u0646\u0650","\xab\u0644\u0627 \u064a\u0642\u0631\u0623\u064f \u0627\u0644\u062c\u064f\u0646\u0628\u064f \u0648\u0644\u0627 \u0627\u0644\u062d\u0627\u0626\u0636\u064f \u0634\u064a\u0626\u064b\u0627 \u0645\u0646\u064e \u0627\u0644\u0642\u0631\u0622\u0646\u0650\xbb"],["\u0625\u0628\u0627\u062d\u0629\u064f \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u0629\u0650 \u0641\u064a\u0645\u0627 \u062f\u0648\u0646\u064e \u0627\u0644\u0641\u0631\u062c\u0650","\xab\u0627\u0635\u0646\u0639\u0648\u0627 \u0643\u0644\u064e\u0651 \u0634\u064a\u0621\u064d \u0625\u0644\u064e\u0651\u0627 \u0627\u0644\u0646\u0650\u0651\u0643\u0627\u062d\u064e\xbb"]],e:"\u0647\u0630\u0647\u0650 \u0623\u062f\u0644\u064e\u0651\u0629\u064f \u0627\u0644\u0643\u062a\u0627\u0628\u0650 \u0641\u064a \u0628\u0627\u0628\u0650 \u0645\u0627 \u064a\u064f\u0645\u0646\u0639\u064f \u0648\u0645\u0627 \u064a\u064f\u0628\u0627\u062d\u064f \u0628\u0627\u0644\u062d\u064a\u0636\u0650 \u0648\u0627\u0644\u0646\u0650\u0651\u0641\u0627\u0633\u0650.",src:165},{t:"info",h:"\u0623\u0631\u0628\u0639\u0629\u064c \u062a\u064f\u0628\u0627\u062d\u064f \u0645\u0639\u064e \u0627\u0644\u062d\u064a\u0636\u0650 \u0648\u0627\u0644\u0646\u0650\u0651\u0641\u0627\u0633\u0650",b:"\u064a\u064f\u0628\u0627\u062d\u064f: \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u0629\u064f \u0641\u064a\u0645\u0627 \u062f\u0648\u0646\u064e \u0627\u0644\u0641\u0631\u062c\u0650\u060c \u0648\u0630\u0643\u0631\u064f \u0627\u0644\u0644\u0647\u0650 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0627\u0644\u0625\u062d\u0631\u0627\u0645\u064f \u0648\u0627\u0644\u0648\u0642\u0648\u0641\u064f \u0628\u0639\u0631\u0641\u0629\u064e \u0648\u0633\u0627\u0626\u0631\u064f \u0623\u0639\u0645\u0627\u0644\u0650 \u0627\u0644\u062d\u062c\u0650\u0651 \u0623\u0648\u0650 \u0627\u0644\u0639\u0645\u0631\u0629\u0650 \u0625\u0644\u064e\u0651\u0627 \u0627\u0644\u0637\u064e\u0651\u0648\u0627\u0641\u064e\u060c \u0648\u0645\u064f\u0624\u0627\u0643\u0644\u062a\u064f\u0647\u064f\u0645\u0627 \u0648\u0645\u064f\u0634\u0627\u0631\u0628\u062a\u064f\u0647\u064f\u0645\u0627.",src:165},{t:"mcq",q:"\u0645\u0627 \u0627\u0644\u0639\u0645\u0644\u064f \u0627\u0644\u064e\u0651\u0630\u064a \u062a\u064f\u0645\u0646\u0639\u064f \u0645\u0646\u0647\u064f \u0627\u0644\u062d\u0627\u0626\u0636\u064f \u0645\u0646\u0652 \u0623\u0639\u0645\u0627\u0644\u0650 \u0627\u0644\u062d\u062c\u0650\u0651\u061f",o:["\u0627\u0644\u0648\u0642\u0648\u0641\u064f \u0628\u0639\u0631\u0641\u0629\u064e","\u0627\u0644\u0625\u062d\u0631\u0627\u0645\u064f \u0628\u0627\u0644\u062d\u062c\u0650\u0651 \u0623\u0648\u0650 \u0627\u0644\u0639\u0645\u0631\u0629\u0650","\u0627\u0644\u0637\u064e\u0651\u0648\u0627\u0641\u064f \u0628\u0627\u0644\u0628\u064a\u062a\u0650","\u0633\u0627\u0626\u0631\u064f \u0623\u0639\u0645\u0627\u0644\u0650 \u0627\u0644\u062d\u062c\u0650\u0651"],a:2,e:"\u0642\u0627\u0644\u064e \ufdfa \u0644\u0639\u0627\u0626\u0634\u0629\u064e: \xab\u0627\u0641\u0639\u0644\u064a \u0645\u0627 \u064a\u0641\u0639\u0644\u064f \u0627\u0644\u062d\u0627\u062c\u064f\u0651\u060c \u063a\u064a\u0631\u064e \u0623\u0646\u0652 \u0644\u0627 \u062a\u0637\u0648\u0641\u064a \u0628\u0627\u0644\u0628\u064a\u062a\u0650 \u062d\u062a\u064e\u0651\u0649 \u062a\u0637\u0647\u064f\u0631\u064a\xbb\u061b \u0641\u0644\u0627 \u064a\u062d\u0644\u064f\u0651 \u0627\u0644\u0637\u064e\u0651\u0648\u0627\u0641\u064f \u0625\u0644\u064e\u0651\u0627 \u0628\u0639\u062f\u064e \u0627\u0644\u0637\u064f\u0651\u0647\u0631\u0650 \u0648\u0627\u0644\u063a\u0633\u0644\u0650.",src:165},{t:"tf",q:"\u0645\u064f\u0624\u0627\u0643\u0644\u0629\u064f \u0627\u0644\u062d\u0627\u0626\u0636\u0650 \u0648\u0645\u064f\u0634\u0627\u0631\u0628\u062a\u064f\u0647\u0627 \u0645\u0645\u0646\u0648\u0639\u0629\u064c \u062d\u062a\u064e\u0651\u0649 \u062a\u0637\u0647\u0631\u064e.",a:!1,e:"\u0628\u0644\u0652 \u0647\u064a\u064e \u0645\u064f\u0628\u0627\u062d\u0629\u064c\u061b \u0644\u0642\u0648\u0644\u0650 \u0639\u0627\u0626\u0634\u0629\u064e: \xab\u0643\u0646\u062a\u064f \u0623\u0634\u0631\u0628\u064f \u0648\u0623\u0646\u0627 \u062d\u0627\u0626\u0636\u064c \u0641\u0623\u064f\u0646\u0627\u0648\u0644\u064f\u0647\u064f \u0627\u0644\u0646\u064e\u0651\u0628\u064a\u064e\u0651 \ufdfa \u0641\u064a\u0636\u0639\u064f \u0641\u0627\u0647\u064f \u0639\u0644\u0649 \u0645\u0648\u0636\u0639\u0650 \u0641\u0650\u064a\u064e\u0651 \u0641\u064a\u0634\u0631\u0628\u064f\xbb.",src:165},{t:"tf",q:"\u0630\u0643\u0631\u064f \u0627\u0644\u0644\u0647\u0650 \u062a\u0639\u0627\u0644\u0649 \u0645\u064f\u0628\u0627\u062d\u064c \u0644\u0644\u062d\u0627\u0626\u0636\u0650 \u0648\u0627\u0644\u0646\u064f\u0651\u0641\u0633\u0627\u0621\u0650.",a:!0,e:"\u0644\u0645\u0652 \u064a\u0631\u062f\u0652 \u0641\u064a \u0630\u0644\u0643\u064e \u0646\u0647\u064a\u064c \u0639\u0646\u0650 \u0627\u0644\u0634\u064e\u0651\u0627\u0631\u0639\u0650\u060c \u0641\u0639\u062f\u064e\u0651\u0647\u064f \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0645\u0645\u064e\u0651\u0627 \u064a\u064f\u0628\u0627\u062d\u064f \u0645\u0639\u064e \u0627\u0644\u062d\u064a\u0636\u0650 \u0648\u0627\u0644\u0646\u0650\u0651\u0641\u0627\u0633\u0650\u060c \u0628\u062e\u0644\u0627\u0641\u0650 \u0642\u0631\u0627\u0621\u0629\u0650 \u0627\u0644\u0642\u0631\u0622\u0646\u0650 \u0641\u0642\u062f\u0652 \u0648\u0631\u062f\u064e \u0641\u064a\u0647\u0627: \xab\u0644\u0627 \u064a\u0642\u0631\u0623\u064f \u0627\u0644\u062c\u064f\u0646\u0628\u064f \u0648\u0644\u0627 \u0627\u0644\u062d\u0627\u0626\u0636\u064f \u0634\u064a\u0626\u064b\u0627 \u0645\u0646\u064e \u0627\u0644\u0642\u0631\u0622\u0646\u0650\xbb.",src:165}]}]}},1508,[]);
