__d(function(t,c,s,e,q,r,a){q.exports={id:"u06",title:"\u0641\u0631\u0648\u0636 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0633\u0646\u0646\u0647\u0627",subtitle:"\u0645\u0646\u064e \u0627\u0644\u0634\u0631\u0648\u0637\u0650 \u0625\u0644\u0649 \u0627\u0644\u0633\u0646\u0646\u0650",color:"orange",section:"s4",source:{book:"\u0645\u0646\u0647\u0627\u062c \u0627\u0644\u0645\u0633\u0644\u0645",pages:[169,174]},lessons:[{id:"u06l1",title:"\u0634\u0631\u0648\u0637\u064f \u0635\u062d\u0629\u0650 \u0627\u0644\u0635\u0644\u0627\u0629\u0650",items:[{t:"info",h:"\u0634\u0631\u0648\u0637\u064f \u0635\u062d\u064e\u0651\u0629\u0650 \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650",b:"\u0630\u0643\u0631\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0644\u0635\u062d\u064e\u0651\u0629\u0650 \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650 \u062b\u0644\u0627\u062b\u0629\u064e \u0634\u0631\u0648\u0637\u064d: \u0627\u0644\u0637\u064e\u0651\u0647\u0627\u0631\u0629\u064f \u0645\u0646\u064e \u0627\u0644\u062d\u062f\u062b\u0650 \u0627\u0644\u0623\u0635\u063a\u0631\u0650 \u0648\u0627\u0644\u0623\u0643\u0628\u0631\u0650 \u0648\u0645\u0646\u064e \u0627\u0644\u062e\u0628\u062b\u0650\u060c \u0648\u0633\u062a\u0631\u064f \u0627\u0644\u0639\u0648\u0631\u0629\u0650\u060c \u0648\u0627\u0633\u062a\u0642\u0628\u0627\u0644\u064f \u0627\u0644\u0642\u0628\u0644\u0629\u0650. \u0641\u0645\u064e\u0627 \u0644\u0645\u0652 \u062a\u062c\u062a\u0645\u0639\u0652 \u0647\u0630\u0647\u0650 \u0627\u0644\u062b\u064e\u0651\u0644\u0627\u062b\u0629\u064f \u0645\u0639\u064e \u0627\u0644\u0642\u062f\u0631\u0629\u0650 \u0644\u0645\u0652 \u062a\u0635\u062d\u064e\u0651 \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u064f\u060c \u0648\u064a\u0633\u0642\u0637\u064f \u0634\u0631\u0637\u064f \u0627\u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644\u0650 \u0639\u0646\u0650 \u0627\u0644\u0639\u0627\u062c\u0632\u0650 \u0644\u062e\u0648\u0641\u064d \u0623\u0648\u0652 \u0645\u0631\u0636\u064d. \u0648\u0641\u0650\u064a \u0627\u0644\u0637\u064e\u0651\u0647\u0627\u0631\u0629\u0650 \u0642\u0627\u0644\u064e \ufdfa: \xab\u0644\u064e\u0627 \u064a\u0642\u0628\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0635\u0644\u0627\u0629\u064b \u0628\u063a\u064a\u0631\u0650 \u0637\u0647\u0648\u0631\u064d\xbb.",src:169},{t:"mcq",q:"\xab\u0627\u0644\u062d\u062f\u062b\u064f \u0627\u0644\u0623\u0635\u063a\u0631\u064f\xbb \u0641\u0650\u064a \u0643\u0644\u0627\u0645\u0650 \u0627\u0644\u0643\u062a\u0627\u0628\u0650 \u0647\u0648\u064e:",o:["\u0639\u062f\u0645\u064f \u0627\u0644\u0648\u0636\u0648\u0621\u0650","\u0639\u062f\u0645\u064f \u0627\u0644\u063a\u0633\u0644\u0650 \u0645\u0646\u064e \u0627\u0644\u062c\u0646\u0627\u0628\u0629\u0650","\u0627\u0644\u0646\u064e\u0651\u062c\u0627\u0633\u0629\u064f \u0641\u0650\u064a \u0627\u0644\u062b\u064e\u0651\u0648\u0628\u0650 \u0623\u0648\u0650 \u0627\u0644\u0628\u062f\u0646\u0650","\u0643\u0634\u0641\u064f \u0627\u0644\u0639\u0648\u0631\u0629\u0650"],a:0,e:"\u0627\u0644\u0643\u062a\u0627\u0628\u064f: \u0627\u0644\u062d\u062f\u062b\u064f \u0627\u0644\u0623\u0635\u063a\u0631\u064f \u0647\u0648\u064e \u0639\u062f\u0645\u064f \u0627\u0644\u0648\u0636\u0648\u0621\u0650\u060c \u0648\u0627\u0644\u0623\u0643\u0628\u0631\u064f \u0639\u062f\u0645\u064f \u0627\u0644\u063a\u0633\u0644\u0650 \u0645\u0646\u064e \u0627\u0644\u062c\u0646\u0627\u0628\u0629\u0650\u060c \u0648\u0627\u0644\u062e\u0628\u062b\u064f \u0647\u0648\u064e \u0627\u0644\u0646\u064e\u0651\u062c\u0627\u0633\u0629\u064f \u0641\u0650\u064a \u062b\u0648\u0628\u0650 \u0627\u0644\u0645\u0635\u0644\u0650\u0651\u064a \u0623\u0648\u0652 \u0628\u062f\u0646\u0647\u0650 \u0623\u0648\u0652 \u0645\u0643\u0627\u0646\u0647\u0650.",src:169},{t:"match",q:"\u0648\u0635\u0650\u0651\u0644\u0652 \u0643\u0644\u064e\u0651 \u0646\u0648\u0639\u064d \u0645\u0646\u064e \u0627\u0644\u0637\u064e\u0651\u0647\u0627\u0631\u0629\u0650 \u0628\u0645\u0639\u0646\u0627\u0647\u064f \u0643\u0645\u064e\u0627 \u0630\u0643\u0631\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f.",pairs:[["\u0627\u0644\u062d\u062f\u062b\u064f \u0627\u0644\u0623\u0635\u063a\u0631\u064f","\u0639\u062f\u0645\u064f \u0627\u0644\u0648\u0636\u0648\u0621\u0650"],["\u0627\u0644\u062d\u062f\u062b\u064f \u0627\u0644\u0623\u0643\u0628\u0631\u064f","\u0639\u062f\u0645\u064f \u0627\u0644\u063a\u0633\u0644\u0650 \u0645\u0646\u064e \u0627\u0644\u062c\u0646\u0627\u0628\u0629\u0650"],["\u0627\u0644\u062e\u0628\u062b\u064f","\u0627\u0644\u0646\u064e\u0651\u062c\u0627\u0633\u0629\u064f \u0641\u0650\u064a \u0627\u0644\u062b\u064e\u0651\u0648\u0628\u0650 \u0623\u0648\u0650 \u0627\u0644\u0628\u062f\u0646\u0650 \u0623\u0648\u0650 \u0627\u0644\u0645\u0643\u0627\u0646\u0650"]],e:"\u0627\u0644\u0637\u064e\u0651\u0647\u0627\u0631\u0629\u064f \u0645\u0646\u0652 \u0647\u0630\u0647\u0650 \u0627\u0644\u062b\u064e\u0651\u0644\u0627\u062b\u0629\u0650 \u0634\u0631\u0637\u064c \u0644\u0635\u062d\u064e\u0651\u0629\u0650 \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650\u061b \u0644\u0642\u0648\u0644\u0647\u0650 \ufdfa: \xab\u0644\u064e\u0627 \u064a\u0642\u0628\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0635\u0644\u0627\u0629\u064b \u0628\u063a\u064a\u0631\u0650 \u0637\u0647\u0648\u0631\u064d\xbb.",src:169},{t:"tf",q:"\u0639\u0648\u0631\u0629\u064f \u0627\u0644\u0631\u064e\u0651\u062c\u0644\u0650 \u0639\u0646\u062f\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u0650 \u0645\u064e\u0627 \u0628\u064a\u0646\u064e \u0633\u0631\u064e\u0651\u062a\u0647\u0650 \u0648\u0631\u0643\u0628\u062a\u064a\u0647\u0650.",a:!0,e:"\u0646\u0635\u064e\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0639\u0644\u064e\u0649 \u0630\u0644\u0643\u064e\u060c \u0648\u062c\u0639\u0644\u064e \u0639\u0648\u0631\u0629\u064e \u0627\u0644\u0645\u0631\u0623\u0629\u0650 \u0645\u064e\u0627 \u0639\u062f\u064e\u0627 \u0648\u062c\u0647\u0647\u064e\u0627 \u0648\u0643\u0641\u064e\u0651\u064a\u0647\u064e\u0627\u061b \u0648\u0644\u064e\u0627 \u062a\u0635\u062d\u064f\u0651 \u0635\u0644\u0627\u0629\u064f \u0645\u0643\u0634\u0648\u0641\u0650 \u0627\u0644\u0639\u0648\u0631\u0629\u0650\u061b \u0644\u0642\u0648\u0644\u0647\u0650 \u062a\u0639\u0627\u0644\u064e\u0649: {\u062e\u064f\u0630\u064f\u0648\u0627 \u0632\u0650\u064a\u0646\u064e\u062a\u064e\u0643\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0643\u064f\u0644\u0650\u0651 \u0645\u064e\u0633\u0652\u062c\u0650\u062f\u064d}.",src:169},{t:"mcq",q:"\u0639\u0648\u0631\u0629\u064f \u0627\u0644\u0645\u0631\u0623\u0629\u0650 \u0641\u0650\u064a \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650 \u0639\u0646\u062f\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u0650:",o:["\u0645\u064e\u0627 \u0628\u064a\u0646\u064e \u0627\u0644\u0633\u064f\u0651\u0631\u064e\u0651\u0629\u0650 \u0648\u0627\u0644\u0631\u064f\u0651\u0643\u0628\u0629\u0650","\u0648\u062c\u0647\u0647\u064e\u0627 \u0648\u0643\u0641\u064e\u0651\u0627\u0647\u064e\u0627 \u0641\u0642\u0637\u0652","\u0645\u064e\u0627 \u0639\u062f\u064e\u0627 \u0648\u062c\u0647\u0647\u064e\u0627 \u0648\u0643\u0641\u064e\u0651\u064a\u0647\u064e\u0627","\u0628\u062f\u0646\u0647\u064e\u0627 \u0643\u0644\u064f\u0651\u0647\u064f \u0628\u0644\u064e\u0627 \u0627\u0633\u062a\u062b\u0646\u0627\u0621\u064d"],a:2,e:"\u0644\u0642\u0648\u0644\u0647\u0650 \ufdfa: \xab\u0644\u064e\u0627 \u064a\u0642\u0628\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0635\u0644\u0627\u0629\u064e \u062d\u0627\u0626\u0636\u064d \u0625\u0644\u064e\u0651\u0627 \u0628\u062e\u0645\u0627\u0631\u064d\xbb\u060c \u0648\u0633\u064f\u0626\u0644\u064e \u0639\u0646\u0652 \u0635\u0644\u0627\u062a\u0647\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u062f\u0650\u0651\u0631\u0639\u0650 \u0648\u0627\u0644\u062e\u0645\u0627\u0631\u0650 \u0628\u063a\u064a\u0631\u0650 \u0625\u0632\u0627\u0631\u064d \u0641\u0642\u0627\u0644\u064e: \xab\u0625\u0630\u064e\u0627 \u0643\u0627\u0646\u064e \u0627\u0644\u062f\u0650\u0651\u0631\u0639\u064f \u0633\u0627\u0628\u063a\u064b\u0627 \u064a\u063a\u0637\u0650\u0651\u064a \u0638\u0647\u0648\u0631\u064e \u0642\u062f\u0645\u064a\u0647\u064e\u0627\xbb.",src:169},{t:"fill",q:"\u0627\u0633\u062a\u0642\u0628\u0627\u0644\u064f \u0627\u0644\u0642\u0628\u0644\u0629\u0650 \u0634\u0631\u0637\u064c \u0644\u0635\u062d\u064e\u0651\u0629\u0650 \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650\u060c \u0648\u064a\u0633\u0642\u0637\u064f \u0639\u0646\u0650 \u0627\u0644\u0639\u0627\u062c\u0632\u0650 \u0639\u0646\u0647\u064f ____ \u0623\u0648\u0652 \u0645\u0631\u0636\u064d \u0648\u0646\u062d\u0648\u0650\u0647\u0645\u064e\u0627.",bank:["\u0644\u062e\u0648\u0641\u064d","\u0644\u0646\u0633\u064a\u0627\u0646\u064d","\u0644\u0633\u0641\u0631\u064d"],a:"\u0644\u062e\u0648\u0641\u064d",e:"\u0642\u0627\u0644\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f: \u0627\u0644\u0639\u0627\u062c\u0632\u064f \u0639\u0646\u0650 \u0627\u0633\u062a\u0642\u0628\u0627\u0644\u0650 \u0627\u0644\u0642\u0628\u0644\u0629\u0650 \u0644\u062e\u0648\u0641\u064d \u0623\u0648\u0652 \u0645\u0631\u0636\u064d \u0648\u0646\u062d\u0648\u0650\u0647\u0645\u064e\u0627 \u064a\u0633\u0642\u0637\u064f \u0639\u0646\u0647\u064f \u0647\u0630\u064e\u0627 \u0627\u0644\u0634\u064e\u0651\u0631\u0637\u064f \u0644\u0639\u062c\u0632\u0647\u0650\u061b \u0648\u0627\u0644\u0623\u0635\u0644\u064f \u0642\u0648\u0644\u0647\u064f \u062a\u0639\u0627\u0644\u064e\u0649: {\u0648\u064e\u062d\u064e\u064a\u0652\u062b\u064f \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0648\u064e\u0644\u064f\u0651\u0648\u0627 \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0643\u064f\u0645\u0652 \u0634\u064e\u0637\u0652\u0631\u064e\u0647\u064f}.",src:169},{t:"tf",q:"\u0627\u0644\u0645\u0633\u0627\u0641\u0631\u064f \u0644\u064e\u0627 \u064a\u062c\u0648\u0632\u064f \u0644\u0647\u064f \u0627\u0644\u062a\u064e\u0651\u0646\u0641\u064f\u0651\u0644\u064f \u0639\u0644\u064e\u0649 \u0638\u0647\u0631\u0650 \u062f\u0627\u0628\u064e\u0651\u062a\u0647\u0650 \u0625\u0644\u064e\u0651\u0627 \u0625\u0630\u064e\u0627 \u062a\u0648\u062c\u064e\u0651\u0647\u062a\u0652 \u0625\u0644\u064e\u0649 \u0627\u0644\u0642\u0628\u0644\u0629\u0650.",a:!1,e:"\u0628\u0644\u0652 \u0644\u0647\u064f \u0623\u0646\u0652 \u064a\u062a\u0646\u0641\u064e\u0651\u0644\u064e \u0639\u0644\u064e\u0649 \u0638\u0647\u0631\u0650 \u062f\u0627\u0628\u064e\u0651\u062a\u0647\u0650 \u062d\u064a\u062b\u0645\u064e\u0627 \u062a\u0648\u062c\u064e\u0651\u0647\u062a\u0652\u060c \u0644\u0644\u0642\u0628\u0644\u0629\u0650 \u0648\u0644\u063a\u064a\u0631\u0647\u064e\u0627\u061b \u0625\u0630\u0652 \u0631\u064f\u0626\u064a\u064e \ufdfa \xab\u064a\u0635\u0644\u0650\u0651\u064a \u0639\u0644\u064e\u0649 \u0631\u0627\u062d\u0644\u062a\u0647\u0650 \u0648\u0647\u0648\u064e \u0645\u0642\u0628\u0644\u064c \u0645\u0646\u0652 \u0645\u0643\u064e\u0651\u0629\u064e \u0625\u0644\u064e\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u0650 \u062d\u064a\u062b\u0645\u064e\u0627 \u062a\u0648\u062c\u064e\u0651\u0647\u062a\u0652 \u0628\u0647\u0650\xbb.",src:169},{t:"mcq",q:"\u0627\u0633\u062a\u062f\u0644\u064e\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0639\u0644\u064e\u0649 \u0634\u0631\u0637\u0650 \u0633\u062a\u0631\u0650 \u0627\u0644\u0639\u0648\u0631\u0629\u0650 \u0628\u0642\u0648\u0644\u0647\u0650 \u062a\u0639\u0627\u0644\u064e\u0649:",o:["{\u0648\u064e\u0642\u064f\u0648\u0645\u064f\u0648\u0627 \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u0642\u064e\u0627\u0646\u0650\u062a\u0650\u064a\u0646\u064e}","{\u0648\u064e\u062d\u064e\u064a\u0652\u062b\u064f \u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0648\u064e\u0644\u064f\u0651\u0648\u0627 \u0648\u064f\u062c\u064f\u0648\u0647\u064e\u0643\u064f\u0645\u0652 \u0634\u064e\u0637\u0652\u0631\u064e\u0647\u064f}","{\u062e\u064f\u0630\u064f\u0648\u0627 \u0632\u0650\u064a\u0646\u064e\u062a\u064e\u0643\u064f\u0645\u0652 \u0639\u0650\u0646\u0652\u062f\u064e \u0643\u064f\u0644\u0650\u0651 \u0645\u064e\u0633\u0652\u062c\u0650\u062f\u064d}"],a:2,e:"\u0642\u0627\u0644\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f: \u0625\u0630\u0650 \u0627\u0644\u0632\u0650\u0651\u064a\u0646\u0629\u064f \u0641\u0650\u064a \u0627\u0644\u062b\u0650\u0651\u064a\u0627\u0628\u0650 \u0645\u064e\u0627 \u064a\u0633\u062a\u0631\u064f \u0627\u0644\u0639\u0648\u0631\u0629\u064e. \u0648\u0623\u0645\u064e\u0651\u0627 {\u0648\u064e\u0642\u064f\u0648\u0645\u064f\u0648\u0627 \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u0642\u064e\u0627\u0646\u0650\u062a\u0650\u064a\u0646\u064e} \u0641\u062f\u0644\u064a\u0644\u064f \u0627\u0644\u0642\u064a\u0627\u0645\u0650\u060c \u0648\u0627\u0644\u0622\u064a\u0629\u064f \u0627\u0644\u0623\u062e\u0631\u064e\u0649 \u062f\u0644\u064a\u0644\u064f \u0627\u0633\u062a\u0642\u0628\u0627\u0644\u0650 \u0627\u0644\u0642\u0628\u0644\u0629\u0650.",src:169}]},{id:"u06l2",title:"\u0641\u0631\u0648\u0636\u064f \u0627\u0644\u0635\u0644\u0627\u0629\u0650",items:[{t:"info",h:"\u0641\u0631\u0648\u0636\u064f \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650 \u0627\u062b\u0646\u064e\u0627 \u0639\u0634\u0631\u064e",b:"\u0639\u062f\u064e\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0641\u0631\u0648\u0636\u064e \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650 \u0627\u062b\u0646\u064a\u0652 \u0639\u0634\u0631\u064e \u0641\u0631\u0636\u064b\u0627\u060c \u0623\u0648\u064e\u0651\u0644\u0647\u064e\u0627 \u0627\u0644\u0642\u064a\u0627\u0645\u064f \u0641\u0650\u064a \u0627\u0644\u0641\u0631\u064a\u0636\u0629\u0650 \u0644\u0644\u0642\u0627\u062f\u0631\u0650 \u0639\u0644\u064a\u0647\u0650\u060c \u0641\u0644\u064e\u0627 \u062a\u0635\u062d\u064f\u0651 \u0627\u0644\u0641\u0631\u064a\u0636\u0629\u064f \u0645\u0646\u0652 \u062c\u0644\u0648\u0633\u064d \u0644\u0645\u0646\u0652 \u064a\u0642\u062f\u0631\u064f \u0639\u0644\u064e\u0649 \u0627\u0644\u0642\u064a\u0627\u0645\u0650\u061b \u0644\u0642\u0648\u0644\u0647\u0650 \u062a\u0639\u0627\u0644\u064e\u0649: {\u0648\u064e\u0642\u064f\u0648\u0645\u064f\u0648\u0627 \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u0642\u064e\u0627\u0646\u0650\u062a\u0650\u064a\u0646\u064e}\u060c \u0648\u0642\u0648\u0644\u0647\u0650 \ufdfa \u0644\u0639\u0645\u0631\u0627\u0646\u064e \u0628\u0646\u0650 \u062d\u0635\u064a\u0646\u064d: \xab\u0635\u0644\u0650\u0651 \u0642\u0627\u0626\u0645\u064b\u0627 \u0641\u0625\u0646\u0652 \u0644\u0645\u0652 \u062a\u0633\u062a\u0637\u0639\u0652 \u0641\u0642\u0627\u0639\u062f\u064b\u0627 \u0641\u0625\u0646\u0652 \u0644\u0645\u0652 \u062a\u0633\u062a\u0637\u0639\u0652 \u0641\u0639\u0644\u064e\u0649 \u062c\u0646\u0628\u064d\xbb.",src:170},{t:"mcq",q:"\u0643\u0645\u0652 \u0639\u062f\u064e\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0641\u0631\u0648\u0636\u064e \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650\u061f",o:["\u0639\u0634\u0631\u0629\u064b","\u0623\u0631\u0628\u0639\u0629\u064e \u0639\u0634\u0631\u064e","\u0633\u062a\u064e\u0651\u0629\u064b","\u0627\u062b\u0646\u064a\u0652 \u0639\u0634\u0631\u064e"],a:3,e:"\u0633\u0631\u062f\u0647\u064e\u0627 \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0627\u062b\u0646\u064a\u0652 \u0639\u0634\u0631\u064e: \u0645\u0646\u064e \u0627\u0644\u0642\u064a\u0627\u0645\u0650 \u0648\u0627\u0644\u0646\u0650\u0651\u064a\u064e\u0651\u0629\u0650 \u0648\u062a\u0643\u0628\u064a\u0631\u0629\u0650 \u0627\u0644\u0625\u062d\u0631\u0627\u0645\u0650 \u0625\u0644\u064e\u0649 \u0627\u0644\u0633\u064e\u0651\u0644\u0627\u0645\u0650 \u0648\u0627\u0644\u062c\u0644\u0648\u0633\u0650 \u0644\u0647\u064f \u0648\u0627\u0644\u062a\u064e\u0651\u0631\u062a\u064a\u0628\u0650 \u0628\u064a\u0646\u064e \u0627\u0644\u0623\u0631\u0643\u0627\u0646\u0650.",src:170},{t:"tf",q:"\u0627\u0644\u0646\u0650\u0651\u064a\u064e\u0651\u0629\u064f \u0639\u0646\u062f\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u0650 \u0647\u064a\u064e \u0639\u0632\u0645\u064f \u0627\u0644\u0642\u0644\u0628\u0650 \u0639\u0644\u064e\u0649 \u0623\u062f\u0627\u0621\u0650 \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650 \u0627\u0644\u0645\u0639\u064a\u064e\u0651\u0646\u0629\u0650.",a:!0,e:"\u0647\u0630\u064e\u0627 \u062d\u062f\u064f\u0651\u0647\u064e\u0627 \u0639\u0646\u062f\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u0650\u060c \u0648\u0647\u064a\u064e \u0641\u0631\u0636\u064c\u061b \u0644\u0642\u0648\u0644\u0647\u0650 \ufdfa: \xab\u0625\u0646\u064e\u0651\u0645\u064e\u0627 \u0627\u0644\u0623\u0639\u0645\u0627\u0644\u064f \u0628\u0627\u0644\u0646\u0650\u0651\u064a\u064e\u0651\u0627\u062a\u0650\xbb.",src:169},{t:"mcq",q:"\u062a\u0646\u0639\u0642\u062f\u064f \u062a\u0643\u0628\u064a\u0631\u0629\u064f \u0627\u0644\u0625\u062d\u0631\u0627\u0645\u0650 \u0628\u0644\u0641\u0638\u0650:",o:["\u0633\u0628\u062d\u0627\u0646\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650","\u0628\u0633\u0645\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650","\u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0623\u0643\u0628\u0631\u064f","\u0644\u064e\u0627 \u0625\u0644\u0647\u064e \u0625\u0644\u064e\u0651\u0627 \u0627\u0644\u0644\u064e\u0651\u0647\u064f"],a:2,e:"\u0646\u0635\u064e\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0639\u0644\u064e\u0649 \u0644\u0641\u0638\u0650 \xab\u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0623\u0643\u0628\u0631\u064f\xbb\u061b \u0644\u0642\u0648\u0644\u0647\u0650 \ufdfa: \xab\u0645\u0641\u062a\u0627\u062d\u064f \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650 \u0627\u0644\u0637\u064f\u0651\u0647\u0648\u0631\u064f\u060c \u0648\u062a\u062d\u0631\u064a\u0645\u0647\u064e\u0627 \u0627\u0644\u062a\u064e\u0651\u0643\u0628\u064a\u0631\u064f\u060c \u0648\u062a\u062d\u0644\u064a\u0644\u0647\u064e\u0627 \u0627\u0644\u062a\u064e\u0651\u0633\u0644\u064a\u0645\u064f\xbb.",src:169},{t:"mcq",q:"\u0642\u0631\u0627\u0621\u0629\u064f \u0627\u0644\u0641\u0627\u062a\u062d\u0629\u0650 \u0647\u064a\u064e \u0627\u0644\u0641\u0631\u0636\u064f \u0627\u0644\u0631\u064e\u0651\u0627\u0628\u0639\u064f \u0639\u0646\u062f\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u0650\u060c \u0641\u0628\u0645\u064e \u0627\u0633\u062a\u062f\u0644\u064e\u0651 \u0639\u0644\u064e\u0649 \u0641\u0631\u0636\u064a\u064e\u0651\u062a\u0647\u064e\u0627\u061f",o:["\xab\u0635\u0644\u064f\u0651\u0648\u0627 \u0643\u0645\u064e\u0627 \u0631\u0623\u064a\u062a\u0645\u0648\u0646\u0650\u064a \u0623\u0635\u0644\u0650\u0651\u064a\xbb","\xab\u0644\u064e\u0627 \u0635\u0644\u0627\u0629\u064e \u0644\u0645\u0646\u0652 \u0644\u0645\u0652 \u064a\u0642\u0631\u0623\u0652 \u0628\u0641\u0627\u062a\u062d\u0629\u0650 \u0627\u0644\u0643\u062a\u0627\u0628\u0650\xbb","\xab\u0648\u062a\u062d\u0644\u064a\u0644\u0647\u064e\u0627 \u0627\u0644\u062a\u064e\u0651\u0633\u0644\u064a\u0645\u064f\xbb"],a:1,e:"\u0647\u0630\u064e\u0627 \u062f\u0644\u064a\u0644\u064f \u0627\u0644\u0643\u062a\u0627\u0628\u0650 \u0639\u0644\u064e\u0649 \u0641\u0631\u0636\u0650 \u0627\u0644\u0641\u0627\u062a\u062d\u0629\u0650. \u0648\u0623\u0645\u064e\u0651\u0627 \xab\u0635\u0644\u064f\u0651\u0648\u0627 \u0643\u0645\u064e\u0627 \u0631\u0623\u064a\u062a\u0645\u0648\u0646\u0650\u064a \u0623\u0635\u0644\u0650\u0651\u064a\xbb \u0641\u062f\u0644\u064a\u0644\u064f \u0627\u0644\u062a\u064e\u0651\u0631\u062a\u064a\u0628\u0650 \u0628\u064a\u0646\u064e \u0627\u0644\u0623\u0631\u0643\u0627\u0646\u0650\u060c \u0648\xab\u062a\u062d\u0644\u064a\u0644\u0647\u064e\u0627 \u0627\u0644\u062a\u064e\u0651\u0633\u0644\u064a\u0645\u064f\xbb \u062f\u0644\u064a\u0644\u064f \u0627\u0644\u0633\u064e\u0651\u0644\u0627\u0645\u0650.",src:170},{t:"tf",q:"\u062a\u0633\u0642\u0637\u064f \u0642\u0631\u0627\u0621\u0629\u064f \u0627\u0644\u0641\u0627\u062a\u062d\u0629\u0650 \u0639\u0646\u0650 \u0627\u0644\u0645\u0623\u0645\u0648\u0645\u0650 \u0625\u0630\u064e\u0627 \u062c\u0647\u0631\u064e \u0625\u0645\u0627\u0645\u0647\u064f \u0628\u0627\u0644\u0642\u0631\u0627\u0621\u0629\u0650.",a:!0,e:"\u0643\u0630\u064e\u0627 \u0642\u0627\u0644\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f\u061b \u0644\u0623\u0646\u064e\u0651\u0647\u064f \u0645\u0623\u0645\u0648\u0631\u064c \u0628\u0627\u0644\u0625\u0646\u0635\u0627\u062a\u0650: {\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064f\u0631\u0650\u0626\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064f \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0645\u0650\u0639\u064f\u0648\u0627 \u0644\u064e\u0647\u064f \u0648\u064e\u0623\u064e\u0646\u0652\u0635\u0650\u062a\u064f\u0648\u0627}\u060c \u0648\u0642\u0648\u0644\u0647\u0650 \ufdfa: \xab\u0648\u0625\u0630\u064e\u0627 \u0642\u0631\u0623\u064e \u0641\u0623\u0646\u0635\u062a\u064f\u0648\u0627\xbb. \u0641\u0625\u0646\u0652 \u0623\u0633\u0631\u064e\u0651 \u0627\u0644\u0625\u0645\u0627\u0645\u064f \u0642\u0631\u0623\u064e \u0627\u0644\u0645\u0623\u0645\u0648\u0645\u064f \u0648\u062c\u0648\u0628\u064b\u0627.",src:170},{t:"order",q:"\u0631\u062a\u0650\u0651\u0628\u0652 \u0647\u0630\u0647\u0650 \u0627\u0644\u0623\u0641\u0639\u0627\u0644\u064e \u0639\u0644\u064e\u0649 \u062a\u0631\u062a\u064a\u0628\u0650 \u0627\u0644\u0643\u062a\u0627\u0628\u0650 \u0641\u0650\u064a \u0639\u062f\u0650\u0651 \u0627\u0644\u0641\u0631\u0648\u0636\u0650.",items:["\u0627\u0644\u0631\u064f\u0651\u0643\u0648\u0639\u064f","\u0627\u0644\u0631\u064e\u0651\u0641\u0639\u064f \u0645\u0646\u064e \u0627\u0644\u0631\u064f\u0651\u0643\u0648\u0639\u0650","\u0627\u0644\u0633\u064f\u0651\u062c\u0648\u062f\u064f","\u0627\u0644\u0631\u064e\u0651\u0641\u0639\u064f \u0645\u0646\u064e \u0627\u0644\u0633\u064f\u0651\u062c\u0648\u062f\u0650","\u0627\u0644\u0633\u064e\u0651\u0644\u0627\u0645\u064f"],e:"\u0644\u0642\u0648\u0644\u0647\u0650 \ufdfa \u0644\u0644\u0645\u0633\u064a\u0621\u0650 \u0635\u0644\u0627\u062a\u0647\u064f: \xab\u062b\u0645\u064e\u0651 \u0627\u0631\u0643\u0639\u0652 \u062d\u062a\u064e\u0651\u0649 \u062a\u0637\u0645\u0626\u0646\u064e\u0651 \u0631\u0627\u0643\u0639\u064b\u0627\u060c \u062b\u0645\u064e\u0651 \u0627\u0631\u0641\u0639\u0652 \u062d\u062a\u064e\u0651\u0649 \u062a\u0639\u062a\u062f\u0644\u064e \u0642\u0627\u0626\u0645\u064b\u0627\u060c \u062b\u0645\u064e\u0651 \u0627\u0633\u062c\u062f\u0652 \u062d\u062a\u064e\u0651\u0649 \u062a\u0637\u0645\u0626\u0646\u064e\u0651 \u0633\u0627\u062c\u062f\u064b\u0627\u060c \u062b\u0645\u064e\u0651 \u0627\u0631\u0641\u0639\u0652 \u062d\u062a\u064e\u0651\u0649 \u062a\u0637\u0645\u0626\u0646\u064e\u0651 \u062c\u0627\u0644\u0633\u064b\u0627\xbb.",src:170},{t:"fill",q:"\u062d\u0642\u064a\u0642\u0629\u064f \u0627\u0644\u0637\u064f\u0651\u0645\u0623\u0646\u064a\u0646\u0629\u0650 \u0623\u0646\u0652 \u064a\u0645\u0643\u062b\u064e \u0628\u0639\u062f\u064e \u0627\u0633\u062a\u0642\u0631\u0627\u0631\u0650 \u0623\u0639\u0636\u0627\u0626\u0647\u0650 \u0632\u0645\u0646\u064b\u0627 \u0628\u0642\u062f\u0631\u0650 \u0645\u064e\u0627 \u064a\u0642\u0648\u0644\u064f: ____ \u0645\u0631\u064e\u0651\u0629\u064b \u0648\u0627\u062d\u062f\u0629\u064b.",bank:["\u0633\u0628\u062d\u0627\u0646\u064e \u0631\u0628\u0650\u0651\u064a\u064e \u0627\u0644\u0639\u0638\u064a\u0645\u0650","\u0633\u0628\u062d\u0627\u0646\u064e \u0631\u0628\u0650\u0651\u064a\u064e \u0627\u0644\u0623\u0639\u0644\u064e\u0649","\u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0623\u0643\u0628\u0631\u064f"],a:"\u0633\u0628\u062d\u0627\u0646\u064e \u0631\u0628\u0650\u0651\u064a\u064e \u0627\u0644\u0639\u0638\u064a\u0645\u0650",e:"\u0648\u0627\u0644\u0637\u064f\u0651\u0645\u0623\u0646\u064a\u0646\u0629\u064f \u0641\u0631\u0636\u064c \u0641\u0650\u064a \u0627\u0644\u0631\u064f\u0651\u0643\u0648\u0639\u0650 \u0648\u0627\u0644\u0633\u064f\u0651\u062c\u0648\u062f\u0650 \u0648\u0627\u0644\u0642\u064a\u0627\u0645\u0650 \u0648\u0627\u0644\u062c\u0644\u0648\u0633\u0650\u060c \u0648\u0645\u064e\u0627 \u0632\u0627\u062f\u064e \u0639\u0644\u064e\u0649 \u0647\u0630\u064e\u0627 \u0627\u0644\u0642\u062f\u0631\u0650 \u0641\u0647\u0648\u064e \u0633\u0646\u064e\u0651\u0629\u064c.",src:170},{t:"tf",q:"\u064a\u0635\u062d\u064f\u0651 \u0627\u0644\u062e\u0631\u0648\u062c\u064f \u0645\u0646\u064e \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650 \u0628\u063a\u064a\u0631\u0650 \u0633\u0644\u0627\u0645\u064d.",a:!1,e:"\u0627\u0644\u0633\u064e\u0651\u0644\u0627\u0645\u064f \u0641\u0631\u0636\u064c\u060c \u0648\u0627\u0644\u062c\u0644\u0648\u0633\u064f \u0644\u0647\u064f \u0641\u0631\u0636\u064c\u061b \u0641\u0644\u064e\u0627 \u064a\u062e\u0631\u062c\u064f \u0645\u0646\u064e \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650 \u0628\u063a\u064a\u0631\u0650 \u0627\u0644\u0633\u064e\u0651\u0644\u0627\u0645\u0650\u060c \u0648\u0644\u064e\u0627 \u064a\u0633\u0644\u0650\u0651\u0645\u064f \u0625\u0644\u064e\u0651\u0627 \u0648\u0647\u0648\u064e \u062c\u0627\u0644\u0633\u064c\u061b \u0644\u0642\u0648\u0644\u0647\u0650 \ufdfa: \xab\u0648\u062a\u062d\u0644\u064a\u0644\u0647\u064e\u0627 \u0627\u0644\u062a\u064e\u0651\u0633\u0644\u064a\u0645\u064f\xbb.",src:170},{t:"mcq",q:"\u0645\u0646\u0652 \u0633\u062c\u062f\u064e \u0642\u0628\u0644\u064e \u0623\u0646\u0652 \u064a\u0631\u0643\u0639\u064e \u0641\u0650\u064a \u0635\u0644\u0627\u062a\u0647\u0650:",o:["\u0628\u0637\u0644\u062a\u0652 \u0635\u0644\u0627\u062a\u0647\u064f","\u0635\u062d\u064e\u0651\u062a\u0652 \u0635\u0644\u0627\u062a\u0647\u064f","\u064a\u064f\u0639\u064a\u062f\u064f \u0627\u0644\u0631\u064f\u0651\u0643\u0648\u0639\u064e \u062b\u0645\u064e\u0651 \u064a\u0633\u062c\u062f\u064f"],a:0,e:"\u0627\u0644\u062a\u064e\u0651\u0631\u062a\u064a\u0628\u064f \u0628\u064a\u0646\u064e \u0627\u0644\u0623\u0631\u0643\u0627\u0646\u0650 \u0641\u0631\u0636\u064c\u061b \u0642\u0627\u0644\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f: \u0641\u0644\u064e\u0627 \u064a\u062c\u0648\u0632\u064f \u062a\u0642\u062f\u064a\u0645\u064f \u0645\u062a\u0623\u062e\u0650\u0651\u0631\u064d \u0648\u0644\u064e\u0627 \u062a\u0623\u062e\u064a\u0631\u064f \u0645\u062a\u0642\u062f\u0650\u0651\u0645\u064d \u0648\u0625\u0644\u064e\u0651\u0627 \u0628\u0637\u0644\u062a\u0650 \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u064f\u061b \u0644\u0642\u0648\u0644\u0647\u0650 \ufdfa: \xab\u0635\u0644\u064f\u0651\u0648\u0627 \u0643\u0645\u064e\u0627 \u0631\u0623\u064a\u062a\u0645\u0648\u0646\u0650\u064a \u0623\u0635\u0644\u0650\u0651\u064a\xbb.",src:170}]},{id:"u06l3",title:"\u0627\u0644\u0633\u0646\u0646\u064f \u0627\u0644\u0645\u0624\u0643\u062f\u0629\u064f",items:[{t:"info",h:"\u0642\u0633\u0645\u064e\u0627 \u0627\u0644\u0633\u064f\u0651\u0646\u0646\u0650",b:"\u0642\u0633\u064e\u0651\u0645\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0633\u0646\u0646\u064e \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650 \u0642\u0633\u0645\u064a\u0646\u0650: \u0645\u0624\u0643\u064e\u0651\u062f\u0629\u064c \u0643\u0627\u0644\u0648\u0627\u062c\u0628\u0650\u060c \u0648\u063a\u064a\u0631\u064f \u0645\u0624\u0643\u064e\u0651\u062f\u0629\u064d \u0643\u0627\u0644\u0645\u0633\u062a\u062d\u0628\u0650\u0651. \u0648\u0627\u0644\u0645\u0624\u0643\u064e\u0651\u062f\u0629\u064f \u062a\u0633\u0639\u064c\u060c \u0623\u0648\u064e\u0651\u0644\u0647\u064e\u0627 \u0642\u0631\u0627\u0621\u0629\u064f \u0633\u0648\u0631\u0629\u064d \u0623\u0648\u0652 \u0634\u064a\u0621\u064d \u0645\u0646\u064e \u0627\u0644\u0642\u0631\u0622\u0646\u0650 \u0628\u0639\u062f\u064e \u0627\u0644\u0641\u0627\u062a\u062d\u0629\u0650\u060c \u0648\u0622\u062e\u0631\u0647\u064e\u0627 \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u064f \u0639\u0644\u064e\u0649 \u0627\u0644\u0646\u064e\u0651\u0628\u064a\u0650\u0651 \ufdfa \u0641\u0650\u064a \u0627\u0644\u062a\u064e\u0651\u0634\u0647\u064f\u0651\u062f\u0650 \u0627\u0644\u0623\u062e\u064a\u0631\u0650.",src:172},{t:"mcq",q:"\u0627\u0644\u0633\u064f\u0651\u0646\u064e\u0651\u0629\u064f \u0627\u0644\u0645\u0624\u0643\u064e\u0651\u062f\u0629\u064f \u0639\u0646\u062f\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u0650 \u0628\u0645\u0646\u0632\u0644\u0629\u0650:",o:["\u0627\u0644\u0645\u0633\u062a\u062d\u0628\u0650\u0651","\u0627\u0644\u0648\u0627\u062c\u0628\u0650","\u0627\u0644\u0641\u0631\u0636\u0650"],a:1,e:"\u0642\u0627\u0644\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f: \u0633\u0646\u0646\u064f \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650 \u0642\u0633\u0645\u0627\u0646\u0650: \u0645\u0624\u0643\u064e\u0651\u062f\u0629\u064c \u0643\u0627\u0644\u0648\u0627\u062c\u0628\u0650\u060c \u0648\u063a\u064a\u0631\u064f \u0645\u0624\u0643\u064e\u0651\u062f\u0629\u064d \u0643\u0627\u0644\u0645\u0633\u062a\u062d\u0628\u0650\u0651.",src:170},{t:"tf",q:"\u0642\u0631\u0627\u0621\u0629\u064f \u0633\u0648\u0631\u0629\u064d \u0623\u0648\u0652 \u0634\u064a\u0621\u064d \u0645\u0646\u064e \u0627\u0644\u0642\u0631\u0622\u0646\u0650 \u0628\u0639\u062f\u064e \u0627\u0644\u0641\u0627\u062a\u062d\u0629\u0650 \u0633\u0646\u064e\u0651\u0629\u064c \u0645\u0624\u0643\u064e\u0651\u062f\u0629\u064c \u0641\u0650\u064a \u0627\u0644\u0635\u064f\u0651\u0628\u062d\u0650 \u0648\u0641\u0650\u064a \u0623\u064f\u0648\u0644\u064a\u064e\u064a\u0650 \u0627\u0644\u0638\u064f\u0651\u0647\u0631\u0650 \u0648\u0627\u0644\u0639\u0635\u0631\u0650 \u0648\u0627\u0644\u0645\u063a\u0631\u0628\u0650 \u0648\u0627\u0644\u0639\u0634\u0627\u0621\u0650.",a:!0,e:"\u0647\u0630\u0650\u0647\u0650 \u0623\u0648\u0644\u064e\u0649 \u0627\u0644\u0633\u064f\u0651\u0646\u0646\u0650 \u0627\u0644\u0645\u0624\u0643\u064e\u0651\u062f\u0629\u0650 \u0639\u0646\u062f\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u0650\u061b \u0644\u0645\u0627\u064e \u0631\u0648\u064a\u064e \u0623\u0646\u064e\u0651\u0647\u064f \ufdfa \u0643\u0627\u0646\u064e \u064a\u0642\u0631\u0623\u064f \u0641\u0650\u064a \u0627\u0644\u0638\u064f\u0651\u0647\u0631\u0650 \u0641\u0650\u064a \u0627\u0644\u0623\u064f\u0648\u0644\u064a\u064a\u0646\u0650 \u0628\u0623\u0645\u0650\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u0650 \u0648\u0633\u0648\u0631\u062a\u064a\u0646\u0650\u060c \u0648\u0641\u0650\u064a \u0627\u0644\u0623\u062e\u0631\u064a\u064a\u0646\u0650 \u0628\u0623\u0645\u0650\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u0650.",src:171},{t:"match",q:"\u0648\u0635\u0650\u0651\u0644\u0650 \u0627\u0644\u0645\u0648\u0636\u0639\u064e \u0628\u0627\u0644\u0630\u0650\u0651\u0643\u0631\u0650 \u0627\u0644\u0645\u0633\u0646\u0648\u0646\u0650 \u0641\u064a\u0647\u0650.",pairs:[["\u0627\u0644\u0631\u064f\u0651\u0643\u0648\u0639\u064f","\u0633\u0628\u062d\u0627\u0646\u064e \u0631\u0628\u0650\u0651\u064a\u064e \u0627\u0644\u0639\u0638\u064a\u0645\u0650 \u062b\u0644\u0627\u062b\u064b\u0627"],["\u0627\u0644\u0633\u064f\u0651\u062c\u0648\u062f\u064f","\u0633\u0628\u062d\u0627\u0646\u064e \u0631\u0628\u0650\u0651\u064a\u064e \u0627\u0644\u0623\u0639\u0644\u064e\u0649"],["\u0627\u0644\u0631\u064e\u0651\u0641\u0639\u064f \u0645\u0646\u064e \u0627\u0644\u0631\u064f\u0651\u0643\u0648\u0639\u0650 \u0644\u0644\u0625\u0645\u0627\u0645\u0650 \u0648\u0627\u0644\u0641\u0630\u0650\u0651","\u0633\u0645\u0639\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0644\u0645\u0646\u0652 \u062d\u0645\u062f\u0647\u064f\u060c \u0631\u0628\u064e\u0651\u0646\u064e\u0627 \u0644\u0643\u064e \u0627\u0644\u062d\u0645\u062f\u064f"]],e:"\u0648\u0627\u0644\u0645\u0623\u0645\u0648\u0645\u064f \u064a\u0642\u0648\u0644\u064f: \u0631\u0628\u064e\u0651\u0646\u064e\u0627 \u0644\u0643\u064e \u0627\u0644\u062d\u0645\u062f\u064f\u061b \u0644\u0642\u0648\u0644\u0647\u0650 \ufdfa: \xab\u0625\u0630\u064e\u0627 \u0642\u0627\u0644\u064e \u0627\u0644\u0625\u0645\u0627\u0645\u064f: \u0633\u0645\u0639\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0644\u0645\u0646\u0652 \u062d\u0645\u062f\u0647\u064f\u060c \u0641\u0642\u0648\u0644\u064f\u0648\u0627: \u0627\u0644\u0644\u064e\u0651\u0647\u0645\u064e\u0651 \u0631\u0628\u064e\u0651\u0646\u064e\u0627 \u0648\u0644\u0643\u064e \u0627\u0644\u062d\u0645\u062f\u064f\xbb.",src:171},{t:"tf",q:"\u062a\u0643\u0628\u064a\u0631\u0627\u062a\u064f \u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644\u0650 \u0628\u064a\u0646\u064e \u0627\u0644\u0623\u0631\u0643\u0627\u0646\u0650 \u0639\u062f\u064e\u0651\u0647\u064e\u0627 \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0645\u0646\u0652 \u0641\u0631\u0648\u0636\u0650 \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650.",a:!1,e:"\u0628\u0644\u0652 \u0639\u062f\u064e\u0651\u0647\u064e\u0627 \u0645\u0646\u064e \u0627\u0644\u0633\u064f\u0651\u0646\u0646\u0650 \u0627\u0644\u0645\u0624\u0643\u064e\u0651\u062f\u0629\u0650: \u062a\u0643\u0628\u064a\u0631\u0629\u064f \u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644\u0650 \u0645\u0646\u064e \u0627\u0644\u0642\u064a\u0627\u0645\u0650 \u0625\u0644\u064e\u0649 \u0627\u0644\u0633\u064f\u0651\u062c\u0648\u062f\u0650\u060c \u0648\u0645\u0646\u064e \u0627\u0644\u0633\u064f\u0651\u062c\u0648\u062f\u0650 \u0625\u0644\u064e\u0649 \u0627\u0644\u062c\u0644\u0648\u0633\u0650\u060c \u0648\u0645\u0646\u0647\u064f \u0625\u0644\u064e\u0649 \u0627\u0644\u0642\u064a\u0627\u0645\u0650\u061b \u0644\u0633\u0645\u0627\u0639\u0650 \u0630\u0644\u0643\u064e \u0645\u0646\u0647\u064f \ufdfa.",src:171},{t:"fill",q:"\u0645\u0646\u0652 \u0644\u0641\u0638\u0650 \u0627\u0644\u062a\u064e\u0651\u0634\u0647\u064f\u0651\u062f\u0650: \xab\u0627\u0644\u062a\u064e\u0651\u062d\u064a\u064e\u0651\u0627\u062a\u064f \u0644\u0644\u064e\u0651\u0647\u0650\u060c \u0648\u0627\u0644\u0635\u064e\u0651\u0644\u0648\u0627\u062a\u064f ____ \u060c \u0627\u0644\u0633\u064e\u0651\u0644\u0627\u0645\u064f \u0639\u0644\u064a\u0643\u064e \u0623\u064a\u064f\u0651\u0647\u064e\u0627 \u0627\u0644\u0646\u064e\u0651\u0628\u064a\u064f\u0651\xbb.",bank:["\u0648\u0627\u0644\u0637\u064e\u0651\u064a\u0650\u0651\u0628\u0627\u062a\u064f","\u0648\u0627\u0644\u0628\u0631\u0643\u0627\u062a\u064f","\u0648\u0627\u0644\u0635\u064e\u0651\u0627\u0644\u062d\u0627\u062a\u064f"],a:"\u0648\u0627\u0644\u0637\u064e\u0651\u064a\u0650\u0651\u0628\u0627\u062a\u064f",e:"\u0648\u0644\u0641\u0638\u064f \u0627\u0644\u062a\u064e\u0651\u0634\u0647\u064f\u0651\u062f\u0650 \u0633\u0646\u064e\u0651\u0629\u064c \u0645\u0624\u0643\u064e\u0651\u062f\u0629\u064c\u060c \u0648\u0643\u0630\u0644\u0643\u064e \u0627\u0644\u062a\u064e\u0651\u0634\u0647\u064f\u0651\u062f\u064f \u0627\u0644\u0623\u0648\u064e\u0651\u0644\u064f \u0648\u0627\u0644\u062b\u064e\u0651\u0627\u0646\u0650\u064a \u0648\u0627\u0644\u062c\u0644\u0648\u0633\u064f \u0644\u0647\u0645\u064e\u0627.",src:171},{t:"mcq",q:"\u064a\u064f\u0633\u0646\u064f\u0651 \u0627\u0644\u062c\u0647\u0631\u064f \u0628\u0627\u0644\u0642\u0631\u0627\u0621\u0629\u0650 \u0641\u0650\u064a:",o:["\u062c\u0645\u064a\u0639\u0650 \u0631\u0643\u0639\u0627\u062a\u0650 \u0627\u0644\u0645\u063a\u0631\u0628\u0650 \u0648\u0627\u0644\u0639\u0634\u0627\u0621\u0650","\u0627\u0644\u0638\u064f\u0651\u0647\u0631\u0650 \u0648\u0627\u0644\u0639\u0635\u0631\u0650 \u0648\u0627\u0644\u0639\u0634\u0627\u0621\u0650","\u0627\u0644\u0623\u064f\u0648\u0644\u064a\u064a\u0646\u0650 \u0645\u0646\u064e \u0627\u0644\u0645\u063a\u0631\u0628\u0650 \u0648\u0627\u0644\u0639\u0634\u0627\u0621\u0650 \u0648\u0627\u0644\u0635\u064f\u0651\u0628\u062d\u0650"],a:2,e:"\u0642\u0627\u0644\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f: \u0648\u064a\u0633\u0631\u064f\u0651 \u0641\u064a\u0645\u064e\u0627 \u0639\u062f\u064e\u0627 \u0630\u0644\u0643\u064e\u061b \u0641\u0627\u0644\u062c\u0647\u0631\u064f \u0641\u0650\u064a \u0627\u0644\u062c\u0647\u0631\u064a\u064e\u0651\u0629\u0650 \u0648\u0627\u0644\u0633\u0650\u0651\u0631\u064f\u0651 \u0641\u0650\u064a \u0627\u0644\u0633\u0650\u0651\u0631\u064a\u064e\u0651\u0629\u0650 \u0633\u0646\u064e\u0651\u062a\u0627\u0646\u0650 \u0645\u0624\u0643\u064e\u0651\u062f\u062a\u0627\u0646\u0650.",src:171},{t:"fill",q:"\u0627\u0644\u0633\u064f\u0651\u0646\u064e\u0651\u0629\u064f \u0641\u0650\u064a \u0627\u0644\u0646\u064e\u0651\u0627\u0641\u0644\u0629\u0650 \u0627\u0644\u0646\u064e\u0651\u0647\u0627\u0631\u064a\u064e\u0651\u0629\u0650 ____ \u060c \u0648\u0641\u0650\u064a \u0627\u0644\u0644\u064e\u0651\u064a\u0644\u064a\u064e\u0651\u0629\u0650 \u0627\u0644\u062c\u0647\u0631\u064f.",bank:["\u0627\u0644\u0625\u0633\u0631\u0627\u0631\u064f","\u0627\u0644\u062c\u0647\u0631\u064f","\u062a\u0631\u0643\u064f \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u0650"],a:"\u0627\u0644\u0625\u0633\u0631\u0627\u0631\u064f",e:"\u0647\u0630\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0646\u064e\u0651\u0627\u0641\u0644\u0629\u0650\u060c \u0625\u0644\u064e\u0651\u0627 \u0625\u0630\u064e\u0627 \u062e\u0627\u0641\u064e \u0623\u0646\u0652 \u064a\u0624\u0630\u0650\u064a\u064e \u063a\u064a\u0631\u0647\u064f \u0628\u0642\u0631\u0627\u0621\u062a\u0647\u0650 \u0641\u064a\u064f\u0633\u062a\u062d\u0628\u064f\u0651 \u0644\u0647\u064f \u0627\u0644\u0625\u0633\u0631\u0627\u0631\u064f. \u0648\u0623\u0645\u064e\u0651\u0627 \u0627\u0644\u0641\u0631\u064a\u0636\u0629\u064f \u0641\u0627\u0644\u062c\u0647\u0631\u064f \u0641\u0650\u064a \u0627\u0644\u062c\u0647\u0631\u064a\u064e\u0651\u0629\u0650 \u0648\u0627\u0644\u0633\u0650\u0651\u0631\u064f\u0651 \u0641\u0650\u064a \u0627\u0644\u0633\u0650\u0651\u0631\u064a\u064e\u0651\u0629\u0650.",src:171},{t:"mcq",q:"\u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u064f \u0639\u0644\u064e\u0649 \u0627\u0644\u0646\u064e\u0651\u0628\u064a\u0650\u0651 \ufdfa \u0641\u0650\u064a \u0627\u0644\u062a\u064e\u0651\u0634\u0647\u064f\u0651\u062f\u0650 \u0627\u0644\u0623\u062e\u064a\u0631\u0650 \u0639\u062f\u064e\u0651\u0647\u064e\u0627 \u0627\u0644\u0643\u062a\u0627\u0628\u064f:",o:["\u0633\u0646\u064e\u0651\u0629\u064b \u0645\u0624\u0643\u064e\u0651\u062f\u0629\u064b","\u0633\u0646\u064e\u0651\u0629\u064b \u063a\u064a\u0631\u064e \u0645\u0624\u0643\u064e\u0651\u062f\u0629\u064d","\u0641\u0631\u0636\u064b\u0627 \u0645\u0646\u0652 \u0641\u0631\u0648\u0636\u0650 \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650"],a:0,e:"\u0647\u064a\u064e \u0627\u0644\u062a\u064e\u0651\u0627\u0633\u0639\u0629\u064f \u0645\u0646\u064e \u0627\u0644\u0633\u064f\u0651\u0646\u0646\u0650 \u0627\u0644\u0645\u0624\u0643\u064e\u0651\u062f\u0629\u0650\u061b \u0641\u0628\u0639\u062f\u064e \u0642\u0631\u0627\u0621\u0629\u0650 \u0627\u0644\u062a\u064e\u0651\u0634\u0647\u064f\u0651\u062f\u0650 \u064a\u0642\u0648\u0644\u064f: \xab\u0627\u0644\u0644\u064e\u0651\u0647\u0645\u064e\u0651 \u0635\u0644\u0650\u0651 \u0639\u0644\u064e\u0649 \u0645\u062d\u0645\u064e\u0651\u062f\u064d \u0648\u0639\u0644\u064e\u0649 \u0622\u0644\u0650 \u0645\u062d\u0645\u064e\u0651\u062f\u064d\u060c \u0643\u0645\u064e\u0627 \u0635\u0644\u064e\u0651\u064a\u062a\u064e \u0639\u0644\u064e\u0649 \u0625\u0628\u0631\u0627\u0647\u064a\u0645\u064e \u0648\u0639\u0644\u064e\u0649 \u0622\u0644\u0650 \u0625\u0628\u0631\u0627\u0647\u064a\u0645\u064e\xbb.",src:172}]},{id:"u06l4",title:"\u0627\u0644\u0633\u0646\u0646\u064f \u063a\u064a\u0631\u064f \u0627\u0644\u0645\u0624\u0643\u062f\u0629\u0650",items:[{t:"info",h:"\u0627\u0644\u0633\u064f\u0651\u0646\u0646\u064f \u063a\u064a\u0631\u064f \u0627\u0644\u0645\u0624\u0643\u064e\u0651\u062f\u0629\u0650",b:"\u0639\u062f\u064e\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0627\u0644\u0633\u064f\u0651\u0646\u0646\u064e \u063a\u064a\u0631\u064e \u0627\u0644\u0645\u0624\u0643\u064e\u0651\u062f\u0629\u0650 \u0623\u0631\u0628\u0639\u064e \u0639\u0634\u0631\u0629\u064e \u0633\u0646\u064e\u0651\u0629\u064b\u060c \u0623\u0648\u064e\u0651\u0644\u0647\u064e\u0627 \u062f\u0639\u0627\u0621\u064f \u0627\u0644\u0627\u0633\u062a\u0641\u062a\u0627\u062d\u0650 \u0648\u0622\u062e\u0631\u0647\u064e\u0627 \u0627\u0644\u0630\u0650\u0651\u0643\u0631\u064f \u0648\u0627\u0644\u062f\u064f\u0651\u0639\u0627\u0621\u064f \u0628\u0639\u062f\u064e \u0627\u0644\u0633\u064e\u0651\u0644\u0627\u0645\u0650\u060c \u0648\u0647\u064a\u064e \u0639\u0646\u062f\u0647\u064f \u0628\u0645\u0646\u0632\u0644\u0629\u0650 \u0627\u0644\u0645\u0633\u062a\u062d\u0628\u0650\u0651.",src:174},{t:"fill",q:"\u062f\u0639\u0627\u0621\u064f \u0627\u0644\u0627\u0633\u062a\u0641\u062a\u0627\u062d\u0650: \xab\u0633\u0628\u062d\u0627\u0646\u0643\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0645\u064e\u0651 \u0648\u0628\u062d\u0645\u062f\u0643\u064e\u060c \u0648\u062a\u0628\u0627\u0631\u0643\u064e \u0627\u0633\u0645\u0643\u064e\u060c \u0648\u062a\u0639\u0627\u0644\u064e\u0649 ____ \u060c \u0648\u0644\u064e\u0627 \u0625\u0644\u0647\u064e \u063a\u064a\u0631\u0643\u064e\xbb.",bank:["\u062c\u062f\u064f\u0651\u0643\u064e","\u0630\u0643\u0631\u064f\u0643\u064e","\u0623\u0645\u0631\u064f\u0643\u064e"],a:"\u062c\u062f\u064f\u0651\u0643\u064e",e:"\u0642\u0627\u0644\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0641\u0650\u064a \u0636\u0628\u0637\u0650 \u0627\u0644\u0644\u064e\u0651\u0641\u0638\u0650: \u0627\u0644\u062c\u062f\u064f\u0651 \u0647\u0648\u064e \u0627\u0644\u0639\u0638\u0645\u0629\u064f. \u0648\u0647\u0648\u064e \u0623\u0648\u064e\u0651\u0644\u064f \u0627\u0644\u0633\u064f\u0651\u0646\u0646\u0650 \u063a\u064a\u0631\u0650 \u0627\u0644\u0645\u0624\u0643\u064e\u0651\u062f\u0629\u0650.",src:172},{t:"tf",q:"\u0627\u0644\u0627\u0633\u062a\u0639\u0627\u0630\u0629\u064f \u062a\u0643\u0648\u0646\u064f \u0641\u0650\u064a \u0627\u0644\u0631\u064e\u0651\u0643\u0639\u0629\u0650 \u0627\u0644\u0623\u0648\u0644\u064e\u0649\u060c \u0648\u0627\u0644\u0628\u0633\u0645\u0644\u0629\u064f \u0633\u0631\u064b\u0651\u0627 \u0641\u0650\u064a \u0643\u0644\u0650\u0651 \u0631\u0643\u0639\u0629\u064d.",a:!0,e:"\u0643\u0630\u064e\u0627 \u0646\u0635\u064e\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u064f\u061b \u0644\u0642\u0648\u0644\u0647\u0650 \u062a\u0639\u0627\u0644\u064e\u0649: {\u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u0631\u064e\u0623\u0652\u062a\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0639\u0650\u0630\u0652 \u0628\u0650\u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u064e\u0651\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0627\u0644\u0631\u064e\u0651\u062c\u0650\u064a\u0645\u0650}.",src:172},{t:"mcq",q:"\u0631\u0641\u0639\u064f \u0627\u0644\u064a\u062f\u064a\u0646\u0650 \u062d\u0630\u0648\u064e \u0627\u0644\u0645\u0646\u0643\u0628\u064a\u0646\u0650 \u064a\u0643\u0648\u0646\u064f:",o:["\u0639\u0646\u062f\u064e \u062a\u0643\u0628\u064a\u0631\u0629\u0650 \u0627\u0644\u0625\u062d\u0631\u0627\u0645\u0650 \u0648\u062d\u062f\u0647\u064e\u0627","\u0645\u0639\u064e \u0643\u0644\u0650\u0651 \u062a\u0643\u0628\u064a\u0631\u0629\u064d \u0645\u0646\u0652 \u062a\u0643\u0628\u064a\u0631\u0627\u062a\u0650 \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650","\u0639\u0646\u062f\u064e \u0627\u0644\u0625\u062d\u0631\u0627\u0645\u0650 \u0648\u0627\u0644\u0631\u064f\u0651\u0643\u0648\u0639\u0650 \u0648\u0627\u0644\u0631\u064e\u0651\u0641\u0639\u0650 \u0645\u0646\u0647\u064f \u0648\u0627\u0644\u0642\u064a\u0627\u0645\u0650 \u0645\u0646\u064e \u0627\u062b\u0646\u062a\u064a\u0646\u0650"],a:2,e:"\u0644\u0642\u0648\u0644\u0650 \u0627\u0628\u0646\u0650 \u0639\u0645\u0631\u064e: \xab\u0643\u0627\u0646\u064e \ufdfa \u0625\u0630\u064e\u0627 \u0642\u0627\u0645\u064e \u0625\u0644\u064e\u0649 \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650 \u0631\u0641\u0639\u064e \u064a\u062f\u064a\u0647\u0650 \u062d\u062a\u064e\u0651\u0649 \u064a\u0643\u0648\u0646\u064e\u0627 \u062d\u0630\u0648\u064e \u0645\u0646\u0643\u0628\u064a\u0647\u0650 \u062b\u0645\u064e\u0651 \u064a\u0643\u0628\u0650\u0651\u0631\u064f\u060c \u0641\u0625\u0630\u064e\u0627 \u0623\u0631\u0627\u062f\u064e \u0623\u0646\u0652 \u064a\u0631\u0643\u0639\u064e \u0631\u0641\u0639\u0647\u0645\u064e\u0627 \u0645\u062b\u0644\u064e \u0630\u0644\u0643\u064e\u060c \u0648\u0625\u0630\u064e\u0627 \u0631\u0641\u0639\u064e \u0631\u0623\u0633\u0647\u064f \u0645\u0646\u064e \u0627\u0644\u0631\u064f\u0651\u0643\u0648\u0639\u0650 \u0631\u0641\u0639\u0647\u0645\u064e\u0627 \u0643\u0630\u0644\u0643\u064e\xbb.",src:172},{t:"tf",q:"\u0639\u062f\u064e\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0642\u0648\u0644\u064e \xab\u0622\u0645\u064a\u0646\u064e\xbb \u0628\u0639\u062f\u064e \u0642\u0631\u0627\u0621\u0629\u0650 \u0627\u0644\u0641\u0627\u062a\u062d\u0629\u0650 \u0645\u0646\u064e \u0627\u0644\u0633\u064f\u0651\u0646\u0646\u0650 \u0627\u0644\u0645\u0624\u0643\u064e\u0651\u062f\u0629\u0650.",a:!1,e:"\u0628\u0644\u0652 \u062c\u0639\u0644\u0647\u064f \u0645\u0646\u0652 \u063a\u064a\u0631\u0650 \u0627\u0644\u0645\u0624\u0643\u064e\u0651\u062f\u0629\u0650\u061b \u0644\u0642\u0648\u0644\u0647\u0650 \ufdfa: \xab\u0625\u0630\u064e\u0627 \u0642\u0627\u0644\u064e \u0627\u0644\u0625\u0645\u0627\u0645\u064f: {\u063a\u064e\u064a\u0652\u0631\u0650 \u0627\u0644\u0652\u0645\u064e\u063a\u0652\u0636\u064f\u0648\u0628\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0627\u0644\u0636\u064e\u0651\u0627\u0644\u0650\u0651\u064a\u0646\u064e} \u0641\u0642\u0648\u0644\u064f\u0648\u0627: \u0622\u0645\u064a\u0646\u064e\u060c \u0641\u0625\u0646\u064e\u0651 \u0645\u0646\u0652 \u0648\u0627\u0641\u0642\u064e \u0642\u0648\u0644\u0647\u064f \u0642\u0648\u0644\u064e \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629\u0650 \u063a\u064f\u0641\u0631\u064e \u0644\u0647\u064f \u0645\u064e\u0627 \u062a\u0642\u062f\u064e\u0651\u0645\u064e \u0645\u0646\u0652 \u0630\u0646\u0628\u0647\u0650\xbb.",src:172},{t:"match",q:"\u0648\u0635\u0650\u0651\u0644\u0652 \u0643\u0644\u064e\u0651 \u0635\u0644\u0627\u0629\u064d \u0628\u0642\u062f\u0631\u0650 \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u0650 \u0627\u0644\u0645\u0633\u0646\u0648\u0646\u0650 \u0641\u064a\u0647\u064e\u0627.",pairs:[["\u0627\u0644\u0635\u064f\u0651\u0628\u062d\u064f","\u062a\u0637\u0648\u064a\u0644\u064f \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u0650"],["\u0627\u0644\u0639\u0635\u0631\u064f \u0648\u0627\u0644\u0645\u063a\u0631\u0628\u064f","\u062a\u0642\u0635\u064a\u0631\u064f \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u0650"],["\u0627\u0644\u0639\u0634\u0627\u0621\u064f \u0648\u0627\u0644\u0638\u064f\u0651\u0647\u0631\u064f","\u0627\u0644\u062a\u064e\u0651\u0648\u0633\u064f\u0651\u0637\u064f \u0641\u0650\u064a \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u0650"]],e:"\u0627\u0633\u062a\u0623\u0646\u0633\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0628\u0645\u0627\u064e \u0631\u0648\u064a\u064e \u0623\u0646\u064e\u0651 \u0639\u0645\u0631\u064e \u0643\u062a\u0628\u064e \u0625\u0644\u064e\u0649 \u0623\u0628\u0650\u064a \u0645\u0648\u0633\u064e\u0649: \u0627\u0642\u0631\u0623\u0652 \u0641\u0650\u064a \u0627\u0644\u0635\u064f\u0651\u0628\u062d\u0650 \u0628\u0637\u0648\u0627\u0644\u0650 \u0627\u0644\u0645\u0641\u0635\u064e\u0651\u0644\u0650\u060c \u0648\u0641\u0650\u064a \u0627\u0644\u0638\u064f\u0651\u0647\u0631\u0650 \u0628\u0623\u0648\u0627\u0633\u0637\u0650 \u0627\u0644\u0645\u0641\u0635\u064e\u0651\u0644\u0650\u060c \u0648\u0641\u0650\u064a \u0627\u0644\u0645\u063a\u0631\u0628\u0650 \u0628\u0642\u0635\u0627\u0631\u0650 \u0627\u0644\u0645\u0641\u0635\u064e\u0651\u0644\u0650.",src:172},{t:"mcq",q:"\u0645\u062d\u0644\u064f\u0651 \u062f\u0639\u0627\u0621\u0650 \u0627\u0644\u0642\u0646\u0648\u062a\u0650 \u0639\u0646\u062f\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u0650:",o:["\u0641\u0650\u064a \u0643\u0644\u0650\u0651 \u0631\u0643\u0639\u0629\u064d \u0645\u0646\u0652 \u0635\u0644\u0627\u0629\u0650 \u0627\u0644\u0635\u064f\u0651\u0628\u062d\u0650","\u0641\u0650\u064a \u0627\u0644\u0631\u064e\u0651\u0643\u0639\u0629\u0650 \u0627\u0644\u0623\u062e\u064a\u0631\u0629\u0650 \u0645\u0646\u064e \u0627\u0644\u0635\u064f\u0651\u0628\u062d\u0650 \u0623\u0648\u0650 \u0627\u0644\u0648\u062a\u0631\u0650","\u0641\u0650\u064a \u0627\u0644\u062a\u064e\u0651\u0634\u0647\u064f\u0651\u062f\u0650 \u0627\u0644\u0623\u062e\u064a\u0631\u0650 \u0645\u0646\u0652 \u0643\u0644\u0650\u0651 \u0635\u0644\u0627\u0629\u064d","\u0628\u0639\u062f\u064e \u0627\u0644\u0633\u064e\u0651\u0644\u0627\u0645\u0650 \u0645\u0646\u064e \u0627\u0644\u0641\u0631\u064a\u0636\u0629\u0650"],a:1,e:"\u0642\u0627\u0644\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f: \u064a\u0643\u0648\u0646\u064f \u0628\u0639\u062f\u064e \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u0650 \u0623\u0648\u0652 \u0628\u0639\u062f\u064e \u0627\u0644\u0631\u064e\u0651\u0641\u0639\u0650 \u0645\u0646\u064e \u0627\u0644\u0631\u064f\u0651\u0643\u0648\u0639\u0650\u060c \u0648\u0647\u0648\u064e \u0645\u0646\u064e \u0627\u0644\u0633\u064f\u0651\u0646\u0646\u0650 \u063a\u064a\u0631\u0650 \u0627\u0644\u0645\u0624\u0643\u064e\u0651\u062f\u0629\u0650.",src:172},{t:"fill",q:"\u0627\u0644\u062f\u064f\u0651\u0639\u0627\u0621\u064f \u0628\u064a\u0646\u064e \u0627\u0644\u0633\u064e\u0651\u062c\u062f\u062a\u064a\u0646\u0650: \xab\u0631\u0628\u0650\u0651 \u0627\u063a\u0641\u0631\u0652 \u0644\u0650\u064a ____ \u0648\u0639\u0627\u0641\u0646\u0650\u064a \u0648\u0627\u0647\u062f\u0646\u0650\u064a \u0648\u0627\u0631\u0632\u0642\u0646\u0650\u064a\xbb.",bank:["\u0648\u0627\u0631\u062d\u0645\u0646\u0650\u064a","\u0648\u0627\u062c\u0628\u0631\u0646\u0650\u064a","\u0648\u0627\u0646\u0635\u0631\u0646\u0650\u064a"],a:"\u0648\u0627\u0631\u062d\u0645\u0646\u0650\u064a",e:"\u0644\u0645\u0627\u064e \u0631\u0648\u064a\u064e \u0639\u0646\u0647\u064f \ufdfa \u0623\u0646\u064e\u0651\u0647\u064f \u0643\u0627\u0646\u064e \u064a\u0642\u0648\u0644\u064f \u0630\u0644\u0643\u064e \u0628\u064a\u0646\u064e \u0627\u0644\u0633\u064e\u0651\u062c\u062f\u062a\u064a\u0646\u0650\u060c \u0648\u0647\u0648\u064e \u0633\u0646\u064e\u0651\u0629\u064c \u063a\u064a\u0631\u064f \u0645\u0624\u0643\u064e\u0651\u062f\u0629\u064d.",src:172},{t:"mcq",q:"\u0645\u0646\u0652 \u0623\u0644\u0641\u0627\u0638\u0650 \u062f\u0639\u0627\u0621\u0650 \u0627\u0644\u0642\u0646\u0648\u062a\u0650 \u0627\u0644\u062a\u064a \u0630\u0643\u0631\u0647\u064e\u0627 \u0627\u0644\u0643\u062a\u0627\u0628\u064f:",o:["\u0627\u0644\u0644\u064e\u0651\u0647\u0645\u064e\u0651 \u0623\u0646\u062a\u064e \u0627\u0644\u0633\u064e\u0651\u0644\u0627\u0645\u064f \u0648\u0645\u0646\u0643\u064e \u0627\u0644\u0633\u064e\u0651\u0644\u0627\u0645\u064f","\u0627\u0644\u0644\u064e\u0651\u0647\u0645\u064e\u0651 \u0627\u0647\u062f\u0646\u0650\u064a \u0641\u064a\u0645\u0646\u0652 \u0647\u062f\u064a\u062a\u064e\u060c \u0648\u0639\u0627\u0641\u0646\u0650\u064a \u0641\u064a\u0645\u0646\u0652 \u0639\u0627\u0641\u064a\u062a\u064e","\u0627\u0644\u0644\u064e\u0651\u0647\u0645\u064e\u0651 \u0623\u0639\u0646\u0650\u0651\u064a \u0639\u0644\u064e\u0649 \u0630\u0643\u0631\u0643\u064e \u0648\u0634\u0643\u0631\u0643\u064e"],a:1,e:"\u0648\u062a\u0645\u0627\u0645\u0647\u064f \u0639\u0646\u062f\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u0650: \xab\u0648\u062a\u0648\u0644\u064e\u0651\u0646\u0650\u064a \u0641\u064a\u0645\u0646\u0652 \u062a\u0648\u0644\u064e\u0651\u064a\u062a\u064e\u060c \u0648\u0628\u0627\u0631\u0643\u0652 \u0644\u0650\u064a \u0641\u064a\u0645\u064e\u0627 \u0623\u0639\u0637\u064a\u062a\u064e... \u0641\u0625\u0646\u064e\u0651\u0643\u064e \u062a\u0642\u0636\u0650\u064a \u0648\u0644\u064e\u0627 \u064a\u064f\u0642\u0636\u064e\u0649 \u0639\u0644\u064a\u0643\u064e\xbb. \u0648\u0623\u0645\u064e\u0651\u0627 \u0627\u0644\u0622\u062e\u0631\u0627\u0646\u0650 \u0641\u0645\u0646\u0652 \u0623\u0630\u0643\u0627\u0631\u0650 \u0645\u064e\u0627 \u0628\u0639\u062f\u064e \u0627\u0644\u0633\u064e\u0651\u0644\u0627\u0645\u0650.",src:173}]},{id:"u06l5",title:"\u0627\u0644\u062c\u0644\u0648\u0633\u064f \u0648\u0627\u0644\u0633\u0644\u0627\u0645\u064f \u0648\u0627\u0644\u0630\u0643\u0631\u064f \u0628\u0639\u062f\u0647\u064f",items:[{t:"info",h:"\u0647\u064a\u0626\u0629\u064f \u0627\u0644\u062c\u0644\u0648\u0633\u0650 \u0641\u0650\u064a \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650",b:"\u0645\u0646\u064e \u0627\u0644\u0633\u064f\u0651\u0646\u0646\u0650 \u063a\u064a\u0631\u0650 \u0627\u0644\u0645\u0624\u0643\u064e\u0651\u062f\u0629\u0650 \u0647\u064a\u0626\u0629\u064f \u0627\u0644\u062c\u0644\u0648\u0633\u0650 \u0627\u0644\u0648\u0627\u0631\u062f\u0629\u064f \u0639\u0646\u0647\u064f \ufdfa: \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0634\u064f \u0641\u0650\u064a \u0633\u0627\u0626\u0631\u0650 \u0627\u0644\u062c\u0644\u0633\u0627\u062a\u0650\u060c \u0648\u0627\u0644\u062a\u064e\u0651\u0648\u0631\u0643\u064f \u0641\u0650\u064a \u0627\u0644\u062c\u0644\u0633\u0629\u0650 \u0627\u0644\u0623\u062e\u064a\u0631\u0629\u0650\u060c \u0645\u0639\u064e \u0648\u0636\u0639\u0650 \u0627\u0644\u064a\u062f\u064a\u0646\u0650 \u0639\u0644\u064e\u0649 \u0627\u0644\u0641\u062e\u0630\u064a\u0646\u0650 \u0648\u0627\u0644\u0625\u0634\u0627\u0631\u0629\u0650 \u0628\u0627\u0644\u0633\u064e\u0651\u0628\u0627\u0628\u0629\u0650 \u0639\u0646\u062f\u064e \u062a\u0644\u0627\u0648\u0629\u0650 \u0627\u0644\u062a\u064e\u0651\u0634\u0647\u064f\u0651\u062f\u0650.",src:173},{t:"mcq",q:"\u0627\u0644\u062a\u064e\u0651\u0648\u0631\u0643\u064f \u0639\u0646\u062f\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u0650 \u064a\u0643\u0648\u0646\u064f \u0641\u0650\u064a:",o:["\u0633\u0627\u0626\u0631\u0650 \u0627\u0644\u062c\u0644\u0633\u0627\u062a\u0650","\u0627\u0644\u062c\u0644\u0633\u0629\u0650 \u0627\u0644\u0623\u062e\u064a\u0631\u0629\u0650","\u0627\u0644\u062c\u0644\u0648\u0633\u0650 \u0628\u064a\u0646\u064e \u0627\u0644\u0633\u064e\u0651\u062c\u062f\u062a\u064a\u0646\u0650"],a:1,e:"\u0648\u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0634\u064f \u0641\u0650\u064a \u0633\u0627\u0626\u0631\u0650 \u0627\u0644\u062c\u0644\u0633\u0627\u062a\u0650\u061b \u0647\u0643\u0630\u064e\u0627 \u0642\u0633\u064e\u0651\u0645\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f\u060c \u0648\u0631\u0648\u0627\u0647\u064f \u0627\u0644\u0628\u062e\u0627\u0631\u064a\u064f\u0651 \u0639\u0646\u0652 \u0623\u0628\u0650\u064a \u062d\u0645\u064a\u062f\u064d \u0641\u0650\u064a \u0635\u0641\u0629\u0650 \u0635\u0644\u0627\u062a\u0647\u0650 \ufdfa.",src:173},{t:"match",q:"\u0648\u0635\u0650\u0651\u0644\u0652 \u0643\u0644\u064e\u0651 \u0647\u064a\u0626\u0629\u064d \u0628\u0648\u0635\u0641\u0647\u064e\u0627 \u0639\u0646\u062f\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u0650.",pairs:[["\u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0634\u064f","\u0623\u0646\u0652 \u064a\u062c\u0644\u0633\u064e \u0639\u0644\u064e\u0649 \u0628\u0627\u0637\u0646\u0650 \u0631\u062c\u0644\u0647\u0650 \u0627\u0644\u064a\u0633\u0631\u064e\u0649 \u0648\u064a\u0646\u0635\u0628\u064e \u0627\u0644\u064a\u0645\u0646\u064e\u0649"],["\u0627\u0644\u062a\u064e\u0651\u0648\u0631\u0643\u064f","\u0623\u0646\u0652 \u064a\u062c\u0639\u0644\u064e \u0628\u0627\u0637\u0646\u064e \u0627\u0644\u064a\u0633\u0631\u064e\u0649 \u062a\u062d\u062a\u064e \u0641\u062e\u0630\u0650 \u0627\u0644\u064a\u0645\u0646\u064e\u0649 \u0648\u064a\u062c\u0639\u0644\u064e \u0623\u0644\u064a\u062a\u0647\u064f \u0639\u0644\u064e\u0649 \u0627\u0644\u0623\u0631\u0636\u0650"],["\u0627\u0644\u0625\u0634\u0627\u0631\u0629\u064f \u0628\u0627\u0644\u0633\u064e\u0651\u0628\u0627\u0628\u0629\u0650","\u0623\u0646\u0652 \u064a\u0634\u064a\u0631\u064e \u0628\u0647\u064e\u0627 \u0648\u0644\u064e\u0627 \u064a\u062c\u0627\u0648\u0632\u064e \u0628\u0635\u0631\u0647\u064f \u0625\u0634\u0627\u0631\u062a\u0647\u064f"]],e:"\u0631\u0648\u064e\u0649 \u0627\u0644\u0628\u062e\u0627\u0631\u064a\u064f\u0651 \u0639\u0646\u0652 \u0623\u0628\u0650\u064a \u062d\u0645\u064a\u062f\u064d \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0634\u064e \u0641\u0650\u064a \u0627\u0644\u0631\u064e\u0651\u0643\u0639\u062a\u064a\u0646\u0650 \u0648\u0627\u0644\u062a\u064e\u0651\u0648\u0631\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0623\u062e\u064a\u0631\u0629\u0650\u060c \u0648\u0641\u0650\u064a \u0635\u0641\u0629\u0650 \u0627\u0644\u062a\u064e\u0651\u0634\u0647\u064f\u0651\u062f\u0650 \u0623\u0646\u064e\u0651\u0647\u064f \ufdfa \u0648\u0636\u0639\u064e \u064a\u062f\u064a\u0647\u0650 \u0639\u0644\u064e\u0649 \u0641\u062e\u0630\u064a\u0647\u0650 \u0648\u0623\u0634\u0627\u0631\u064e \u0628\u0627\u0644\u0633\u064e\u0651\u0628\u0627\u0628\u0629\u0650.",src:173},{t:"tf",q:"\u0627\u0644\u0633\u064f\u0651\u0646\u064e\u0651\u0629\u064f \u0648\u0636\u0639\u064f \u0627\u0644\u064a\u062f\u0650 \u0627\u0644\u064a\u0633\u0631\u064e\u0649 \u0641\u0648\u0642\u064e \u0627\u0644\u064a\u0645\u0646\u064e\u0649 \u0639\u0644\u064e\u0649 \u0627\u0644\u0635\u064e\u0651\u062f\u0631\u0650.",a:!1,e:"\u0628\u0644\u0650 \u0627\u0644\u064a\u0645\u0646\u064e\u0649 \u0641\u0648\u0642\u064e \u0627\u0644\u064a\u0633\u0631\u064e\u0649\u061b \u0648\u0644\u0642\u0648\u0644\u0650 \u062c\u0627\u0628\u0631\u064d: \xab\u0645\u0631\u064e\u0651 \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \ufdfa \u0628\u0631\u062c\u0644\u064d \u0648\u0647\u0648\u064e \u064a\u0635\u0644\u0650\u0651\u064a \u0648\u0642\u062f\u0652 \u0648\u0636\u0639\u064e \u064a\u062f\u0647\u064f \u0627\u0644\u064a\u0633\u0631\u064e\u0649 \u0639\u0644\u064e\u0649 \u0627\u0644\u064a\u0645\u0646\u064e\u0649 \u0641\u0627\u0646\u062a\u0632\u0639\u0647\u064e\u0627 \u0648\u0648\u0636\u0639\u064e \u0627\u0644\u064a\u0645\u0646\u064e\u0649 \u0639\u0644\u064e\u0649 \u0627\u0644\u064a\u0633\u0631\u064e\u0649\xbb.",src:173},{t:"mcq",q:"\u0642\u0627\u0644\u064e \ufdfa: \xab\u0646\u064f\u0647\u064a\u062a\u064f \u0623\u0646\u0652 \u0623\u0642\u0631\u0623\u064e \u0627\u0644\u0642\u0631\u0622\u0646\u064e \u0631\u0627\u0643\u0639\u064b\u0627 \u0623\u0648\u0652 \u0633\u0627\u062c\u062f\u064b\u0627\xbb\u061b \u0641\u0645\u064e\u0627 \u0627\u0644\u0630\u064a \u0623\u0645\u0631\u064e \u0628\u0647\u0650 \u0641\u0650\u064a \u0627\u0644\u0633\u064f\u0651\u062c\u0648\u062f\u0650\u061f",o:["\u062a\u0639\u0638\u064a\u0645\u064f \u0627\u0644\u0631\u064e\u0651\u0628\u0650\u0651","\u0631\u0641\u0639\u064f \u0627\u0644\u064a\u062f\u064a\u0646\u0650 \u062d\u0630\u0648\u064e \u0627\u0644\u0645\u0646\u0643\u0628\u064a\u0646\u0650","\u0627\u0644\u0627\u062c\u062a\u0647\u0627\u062f\u064f \u0641\u0650\u064a \u0627\u0644\u062f\u064f\u0651\u0639\u0627\u0621\u0650"],a:2,e:"\u062a\u0645\u0627\u0645\u064f \u0627\u0644\u062d\u062f\u064a\u062b\u0650: \xab\u0641\u0623\u0645\u064e\u0651\u0627 \u0627\u0644\u0631\u064f\u0651\u0643\u0648\u0639\u064f \u0641\u0639\u0638\u0650\u0651\u0645\u064f\u0648\u0627 \u0641\u064a\u0647\u0650 \u0627\u0644\u0631\u064e\u0651\u0628\u064e\u0651\u060c \u0648\u0623\u0645\u064e\u0651\u0627 \u0627\u0644\u0633\u064f\u0651\u062c\u0648\u062f\u064f \u0641\u0627\u062c\u062a\u0647\u062f\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u062f\u064f\u0651\u0639\u0627\u0621\u0650 \u0641\u0642\u0645\u0650\u0646\u064c \u0623\u0646\u0652 \u064a\u064f\u0633\u062a\u062c\u0627\u0628\u064e \u0644\u0643\u0645\u0652\xbb\u061b \u0641\u0627\u0644\u062a\u064e\u0651\u0639\u0638\u064a\u0645\u064f \u0644\u0644\u0631\u064f\u0651\u0643\u0648\u0639\u0650 \u0648\u0627\u0644\u062f\u064f\u0651\u0639\u0627\u0621\u064f \u0644\u0644\u0633\u064f\u0651\u062c\u0648\u062f\u0650.",src:173},{t:"fill",q:"\u0645\u0646\u0652 \u062f\u0639\u0627\u0621\u0650 \u0627\u0644\u062a\u064e\u0651\u0634\u0647\u064f\u0651\u062f\u0650 \u0627\u0644\u0623\u062e\u064a\u0631\u0650: \xab\u0623\u0639\u0648\u0630\u064f \u0628\u0643\u064e \u0645\u0646\u0652 \u0639\u0630\u0627\u0628\u0650 \u062c\u0647\u0646\u064e\u0651\u0645\u064e\u060c \u0648\u0645\u0646\u0652 \u0639\u0630\u0627\u0628\u0650 ____ \u060c \u0648\u0645\u0646\u0652 \u0641\u062a\u0646\u0629\u0650 \u0627\u0644\u0645\u062d\u064a\u064e\u0627 \u0648\u0627\u0644\u0645\u0645\u0627\u062a\u0650\u060c \u0648\u0645\u0646\u0652 \u0641\u062a\u0646\u0629\u0650 \u0627\u0644\u0645\u0633\u064a\u062d\u0650 \u0627\u0644\u062f\u064e\u0651\u062c\u064e\u0651\u0627\u0644\u0650\xbb.",bank:["\u0627\u0644\u0642\u0628\u0631\u0650","\u0627\u0644\u0646\u064e\u0651\u0627\u0631\u0650","\u0627\u0644\u0622\u062e\u0631\u0629\u0650"],a:"\u0627\u0644\u0642\u0628\u0631\u0650",e:"\u064a\u0642\u0648\u0644\u0647\u064f \u0628\u0639\u062f\u064e \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650 \u0639\u0644\u064e\u0649 \u0627\u0644\u0646\u064e\u0651\u0628\u064a\u0650\u0651 \ufdfa\u061b \u0644\u0642\u0648\u0644\u0647\u0650: \xab\u0625\u0630\u064e\u0627 \u0641\u0631\u063a\u064e \u0623\u062d\u062f\u0643\u0645\u0652 \u0645\u0646\u064e \u0627\u0644\u062a\u064e\u0651\u0634\u0647\u064f\u0651\u062f\u0650 \u0627\u0644\u0623\u062e\u064a\u0631\u0650 \u0641\u0644\u064a\u062a\u0639\u0648\u064e\u0651\u0630\u0652 \u0628\u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0645\u0646\u0652 \u0623\u0631\u0628\u0639\u064d\xbb.",src:173},{t:"tf",q:"\u0627\u0644\u0633\u064f\u0651\u0646\u064e\u0651\u0629\u064f \u0623\u0646\u0652 \u064a\u0628\u062f\u0623\u064e \u0628\u0627\u0644\u062a\u064e\u0651\u0633\u0644\u064a\u0645\u0650 \u0639\u0646\u0652 \u064a\u0645\u064a\u0646\u0647\u0650 \u062b\u0645\u064e\u0651 \u064a\u0633\u0644\u0650\u0651\u0645\u064e \u0639\u0646\u0652 \u064a\u0633\u0627\u0631\u0647\u0650.",a:!0,e:"\u0639\u062f\u064e\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u0627\u0644\u062a\u064e\u0651\u064a\u0627\u0645\u0646\u064e \u0628\u0627\u0644\u0633\u064e\u0651\u0644\u0627\u0645\u0650 \u062b\u0645\u064e\u0651 \u0627\u0644\u062a\u064e\u0651\u0633\u0644\u064a\u0645\u0629\u064e \u0627\u0644\u062b\u064e\u0651\u0627\u0646\u064a\u0629\u064e \u0639\u0646\u0652 \u064a\u0633\u0627\u0631\u0647\u0650 \u0633\u0646\u064e\u0651\u062a\u064a\u0646\u0650\u061b \u0644\u0645\u0627\u064e \u0631\u0648\u064a\u064e \u0623\u0646\u064e\u0651\u0647\u064f \ufdfa \u0643\u0627\u0646\u064e \u064a\u0633\u0644\u0650\u0651\u0645\u064f \u0639\u0646\u0652 \u064a\u0645\u064a\u0646\u0647\u0650 \u0648\u0639\u0646\u0652 \u064a\u0633\u0627\u0631\u0647\u0650 \u062d\u062a\u064e\u0651\u0649 \u064a\u064f\u0631\u064e\u0649 \u0628\u064a\u0627\u0636\u064f \u062e\u062f\u0650\u0651\u0647\u0650.",src:174},{t:"mcq",q:"\u0645\u0646\u0652 \u0633\u0628\u064e\u0651\u062d\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u062f\u0628\u0631\u064e \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650 \u062b\u0644\u0627\u062b\u064b\u0627 \u0648\u062b\u0644\u0627\u062b\u064a\u0646\u064e\u060c \u0648\u062d\u0645\u062f\u064e \u062b\u0644\u0627\u062b\u064b\u0627 \u0648\u062b\u0644\u0627\u062b\u064a\u0646\u064e\u060c \u0648\u0643\u0628\u064e\u0651\u0631\u064e \u062b\u0644\u0627\u062b\u064b\u0627 \u0648\u062b\u0644\u0627\u062b\u064a\u0646\u064e\u060c \u0641\u062a\u0644\u0643\u064e:",o:["\u062a\u0633\u0639\u0629\u064c \u0648\u062a\u0633\u0639\u0648\u0646\u064e","\u0645\u0626\u0629\u064c","\u062b\u0644\u0627\u062b\u0629\u064c \u0648\u062b\u0644\u0627\u062b\u0648\u0646\u064e","\u0633\u062a\u064e\u0651\u0629\u064c \u0648\u0633\u062a\u064f\u0651\u0648\u0646\u064e"],a:0,e:"\u0648\u0641\u0650\u064a \u0627\u0644\u062d\u062f\u064a\u062b\u0650: \u0648\u0642\u0627\u0644\u064e \u062a\u0645\u0627\u0645\u064e \u0627\u0644\u0645\u0626\u0629\u0650: \xab\u0644\u064e\u0627 \u0625\u0644\u0647\u064e \u0625\u0644\u064e\u0651\u0627 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u062d\u062f\u0647\u064f \u0644\u064e\u0627 \u0634\u0631\u064a\u0643\u064e \u0644\u0647\u064f\u060c \u0644\u0647\u064f \u0627\u0644\u0645\u0644\u0643\u064f \u0648\u0644\u0647\u064f \u0627\u0644\u062d\u0645\u062f\u064f \u0648\u0647\u0648\u064e \u0639\u0644\u064e\u0649 \u0643\u0644\u0650\u0651 \u0634\u064a\u0621\u064d \u0642\u062f\u064a\u0631\u064c\xbb\u060c \u063a\u064f\u0641\u0631\u062a\u0652 \u062e\u0637\u0627\u064a\u0627\u0647\u064f \u0648\u0625\u0646\u0652 \u0643\u0627\u0646\u062a\u0652 \u0645\u062b\u0644\u064e \u0632\u0628\u062f\u0650 \u0627\u0644\u0628\u062d\u0631\u0650.",src:174},{t:"match",q:"\u0648\u0635\u0650\u0651\u0644\u0652 \u0643\u0644\u064e\u0651 \u0635\u062d\u0627\u0628\u064a\u064d\u0651 \u0628\u0627\u0644\u0630\u0650\u0651\u0643\u0631\u0650 \u0627\u0644\u0630\u064a \u0631\u0648\u0627\u0647\u064f \u0628\u0639\u062f\u064e \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u0650.",pairs:[["\u062b\u0648\u0628\u0627\u0646\u064f","\u0627\u0644\u0644\u064e\u0651\u0647\u0645\u064e\u0651 \u0623\u0646\u062a\u064e \u0627\u0644\u0633\u064e\u0651\u0644\u0627\u0645\u064f \u0648\u0645\u0646\u0643\u064e \u0627\u0644\u0633\u064e\u0651\u0644\u0627\u0645\u064f\u060c \u062a\u0628\u0627\u0631\u0643\u062a\u064e \u064a\u064e\u0627 \u0630\u064e\u0627 \u0627\u0644\u062c\u0644\u0627\u0644\u0650 \u0648\u0627\u0644\u0625\u0643\u0631\u0627\u0645\u0650"],["\u0645\u0639\u0627\u0630\u064f \u0628\u0646\u064f \u062c\u0628\u0644\u064d","\u0627\u0644\u0644\u064e\u0651\u0647\u0645\u064e\u0651 \u0623\u0639\u0646\u0650\u0651\u064a \u0639\u0644\u064e\u0649 \u0630\u0643\u0631\u0643\u064e \u0648\u0634\u0643\u0631\u0643\u064e \u0648\u062d\u0633\u0646\u0650 \u0639\u0628\u0627\u062f\u062a\u0643\u064e"],["\u0623\u0628\u0648 \u0623\u0645\u0627\u0645\u0629\u064e","\u0645\u0646\u0652 \u0642\u0631\u0623\u064e \u0622\u064a\u0629\u064e \u0627\u0644\u0643\u0631\u0633\u064a\u0650\u0651 \u062f\u0628\u0631\u064e \u0643\u0644\u0650\u0651 \u0635\u0644\u0627\u0629\u064d \u0644\u0645\u0652 \u064a\u0645\u0646\u0639\u0647\u064f \u0645\u0646\u0652 \u062f\u062e\u0648\u0644\u0650 \u0627\u0644\u062c\u0646\u064e\u0651\u0629\u0650 \u0625\u0644\u064e\u0651\u0627 \u0623\u0646\u0652 \u064a\u0645\u0648\u062a\u064e"]],e:"\u0648\u0632\u0627\u062f\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f \u062d\u062f\u064a\u062b\u064e \u0627\u0644\u0645\u063a\u064a\u0631\u0629\u0650 \u0628\u0646\u0650 \u0634\u0639\u0628\u0629\u064e: \u0643\u0627\u0646\u064e \u064a\u0642\u0648\u0644\u064f \u062f\u0628\u0631\u064e \u0643\u0644\u0650\u0651 \u0635\u0644\u0627\u0629\u064d \u0645\u0643\u062a\u0648\u0628\u0629\u064d: \xab\u0644\u064e\u0627 \u0625\u0644\u0647\u064e \u0625\u0644\u064e\u0651\u0627 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u062d\u062f\u0647\u064f \u0644\u064e\u0627 \u0634\u0631\u064a\u0643\u064e \u0644\u0647\u064f... \u0627\u0644\u0644\u064e\u0651\u0647\u0645\u064e\u0651 \u0644\u064e\u0627 \u0645\u0627\u0646\u0639\u064e \u0644\u0645\u0627\u064e \u0623\u0639\u0637\u064a\u062a\u064e\xbb.",src:174},{t:"tf",q:"\u0643\u0627\u0646\u064e \u0633\u0639\u062f\u064f \u0628\u0646\u064f \u0623\u0628\u0650\u064a \u0648\u0642\u064e\u0651\u0627\u0635\u064d \u064a\u0639\u0644\u0650\u0651\u0645\u064f \u0623\u0648\u0644\u0627\u062f\u0647\u064f \u0627\u0644\u062a\u064e\u0651\u0639\u0648\u064f\u0651\u0630\u064e \u062f\u0628\u0631\u064e \u0643\u0644\u0650\u0651 \u0635\u0644\u0627\u0629\u064d \u0645\u0646\u064e \u0627\u0644\u0628\u062e\u0644\u0650 \u0648\u0627\u0644\u062c\u0628\u0646\u0650 \u0648\u0623\u0631\u0630\u0644\u0650 \u0627\u0644\u0639\u0645\u0631\u0650 \u0648\u0641\u062a\u0646\u0629\u0650 \u0627\u0644\u062f\u064f\u0651\u0646\u064a\u064e\u0627 \u0648\u0639\u0630\u0627\u0628\u0650 \u0627\u0644\u0642\u0628\u0631\u0650.",a:!0,e:"\u0643\u0630\u064e\u0627 \u0630\u0643\u0631\u064e \u0627\u0644\u0643\u062a\u0627\u0628\u064f: \u0643\u0627\u0646\u064e \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \ufdfa \u064a\u062a\u0639\u0648\u064e\u0651\u0630\u064f \u062f\u0628\u0631\u064e \u0643\u0644\u0650\u0651 \u0635\u0644\u0627\u0629\u064d \u0628\u0647\u0630\u0647\u0650 \u0627\u0644\u0643\u0644\u0645\u0627\u062a\u0650\u060c \u0648\u0643\u0627\u0646\u064e \u0633\u0639\u062f\u064c \u064a\u0639\u0644\u0650\u0651\u0645\u0647\u0646\u064e\u0651 \u0623\u0648\u0644\u0627\u062f\u0647\u064f.",src:174}]}]}},1510,[]);
